/* Draft Constitution (1948) counterparts and Constituent Assembly debate dates.
   Facts extracted from constitutionofindia.net (Centre for Law and Policy Research); see tools/build_drafting.py. */
window.COI_DRAFTING={"31B": {"url": "https://www.constitutionofindia.net/articles/article-31b-validation-of-certain-acts-and-regulations/"}, "134A": {"url": "https://www.constitutionofindia.net/articles/article-134a-certificate-for-appeal-to-the-supreme-court/", "addedLater": true}, "35": {"url": "https://www.constitutionofindia.net/articles/article-35-legislation-to-give-effect-to-the-provisions-of-this-part/", "draft": "27", "draftText": "Notwithstanding anything elsewhere contained in this Constitution, Parliament shall have, and the Legislature of a State for the time being specified in Part I or Part III of the First Schedule shall not have, power to make laws-\n(a) With respect to any of the matters which under this Part are required to be provided for by legislation by Parliament, and\n(b) For prescribing punishment for those acts which are declared to be offences under this Part; and Parliament shall, as soon as may be after the commencement of this Constitution, make laws to provide for such matters and for prescribing punishment for such acts:\nProvided that any law in force in the territory of India or in any part thereof with respect to any of the matters referred to in clause (a) of this article or providing for punishment for any act which is declared to be an offence under this Part shall continue in force therein until altered or repealed or amended by Parliament or other competent authority.", "debated": ["1948-12-09"], "adopted": "1948-12-09"}, "136": {"url": "https://www.constitutionofindia.net/articles/article-136-special-leave-to-appeal-by-the-supreme-court/", "draft": "112", "draftText": "The Supreme Court may, in its discretion, grant special leave to appeal from any judgment, decree or final order in any cause or matter, passed or made by any court or tribunal in the territory of India except the States for the time being specified in Part III of the First Schedule, in cases where the provisions of article 110 or article 111 of this Constitution do not apply.", "debated": ["1949-06-06", "1949-10-16"], "adopted": "1949-10-16"}, "137": {"url": "https://www.constitutionofindia.net/articles/article-137-review-of-judgments-or-orders-by-the-supreme-court/", "debated": ["1949-06-06"], "adopted": "1949-06-06", "draft": "112A", "addedLater": true}, "138": {"url": "https://www.constitutionofindia.net/articles/article-138-enlargement-of-the-jurisdiction-of-the-supreme-court/", "draft": "114", "draftText": "(1) The Supreme Court shall have such further jurisdiction and powers with respect to any of the matters in the Union List as Parliament may by law confer.\n(2) The Supreme Court shall have such further jurisdiction and powers with respect to any matter as the Government of India and any State may by special agreement confer, if Parliament by law provides for the exercise of such jurisdiction and powers by the Supreme Court.", "debated": ["1949-06-06"], "adopted": "1949-06-06"}, "139": {"url": "https://www.constitutionofindia.net/articles/article-139-conferment-on-the-supreme-court-of-powers-to-issue-certain-writs/", "draft": "115", "draftText": "(1) The Supreme Court shall have such further jurisdiction and powers with respect to any of the matters in the Union List as Parliament may by law confer.\n(2) The Supreme Court shall have such further jurisdiction and powers with respect to any matter as the Government of India and any State may by special agreement confer, if Parliament by law provides for the exercise of such jurisdiction and powers by the Supreme Court.", "debated": ["1949-05-27"], "adopted": "1949-05-27"}, "139A": {"url": "https://www.constitutionofindia.net/articles/article-139a-transfer-of-certain-cases/", "addedLater": true}, "140": {"url": "https://www.constitutionofindia.net/articles/article-140-ancillary-powers-of-supreme-court/", "draft": "116", "draftText": "Parliament may by law make provision for conferring upon the Supreme Court such supplemental powers not inconsistent with any of the provisions of this Constitution as may appear to be necessary or desirable for the purpose of enabling the court more effectively to exercise the jurisdiction conferred upon it by or under this Constitution.", "debated": ["1949-05-27"], "adopted": "1949-05-27"}, "141": {"url": "https://www.constitutionofindia.net/articles/article-141-law-declared-by-supreme-court-to-be-binding-on-all-courts/", "draft": "117", "draftText": "The law declared by the Supreme Court shall be binding on all courts within the territory of India.", "debated": ["1949-05-27"], "adopted": "1949-05-27"}, "142": {"url": "https://www.constitutionofindia.net/articles/article-142-enforcement-of-decrees-and-orders-of-supreme-court-and-orders-as-to-discovery-etc/", "draft": "118", "draftText": "(1) The Supreme Court in the exercise of its jurisdiction may pass such decree or make such order as is necessary for doing complete justice in any cause or matter pending before it, and any decree so passed or order so made shall be enforceable throughout the territory of India in such manner as may be prescribed by or under any law made by Parliament.\n(2) Subject to the provisions of any law made in this behalf by Parliament the Supreme Court shall, as respects the whole of the territory of India, have all and every power to make any order for the purpose of securing the attendance of any person, the discovery or production of any documents, or the investigation or punishment of any contempt of itself.", "debated": ["1949-05-27"], "adopted": "1949-05-27"}, "143": {"url": "https://www.constitutionofindia.net/articles/article-143-power-of-president-to-consult-supreme-court/", "draft": "119", "draftText": "(1) If at any time it appears to the President that a question of law or fact has arisen, or is likely to arise, which is of such a nature and such public importance that it is expedient to obtain the opinion of the Supreme Court upon it, he may refer the question to that court for consideration and the court may, after such hearing as it thinks fit, report to the President its opinion thereon.\n(2) The President may, notwithstanding anything contained in clause (i) of the proviso to article 109 of this Constitution, refer a dispute of the kind mentioned in the said clause to the Supreme Court for decision, and the Supreme Court shall thereupon, after giving the parties an opportunity of being heard, decide the same and report the fact to the President.", "debated": ["1949-05-27", "1949-06-06"], "adopted": "1949-06-06"}, "144": {"url": "https://www.constitutionofindia.net/articles/article-144-civil-and-judicial-authorities-to-act-in-aid-of-the-supreme-court/", "draft": "120", "draftText": "All authorities, civil and judicial, in the territory of India shall act in aid of the Supreme Court.", "debated": ["1949-05-27"], "adopted": "1949-05-27"}, "145": {"url": "https://www.constitutionofindia.net/articles/article-145-rules-of-court-etc/", "draft": "121", "draftText": "(1) Subject to the provisions of any law made by Parliament, the Supreme Court may from time to time, with the approval of the President, make rules for regulating generally the practice and procedure of the Court including-\n(a) Rules as to the persons practising before the court,\n(b) Rules as to the procedure for hearing appeals and other matters including the time within which appeals to the Court are to be entered and the time to be allowed to advocates appearing before the court to make their submissions in respect thereof,\n(c) Rules as to the costs of and incidental to any proceedings in the court and as to the fees to be charged in respect of proceedings therein,\n(d) Rules as to the granting of bail,\n(e) Rules as to stay of proceedings, and\n(f) Rules providing for the summary determination of any appeal which appears to the court to be frivolous or vexatious or brought for the purpose of delay.\n(2) The minimum number of judges who are to sit for the purpose of deciding any case involving a substantial question of law as to the interpretation of this Constitution, or for the purpose of hearing any reference under article 119 of this Constitution shall be five:\nProvided that it shall be open to every judge to sit for the said purposes unless owing to illness, personal interest or other sufficient cause he is unable to do so.\n(3) No opinion for the purpose of any report under article 119 of this Constitution and no judgment shall be delivered by the Supreme Court save in open court.\n(4) No such report shall be made and no judgment shall be delivered by the Supreme Court save with the concurrence of a majority of the judges present at the hearing of the case, but nothing in this clause shall be deemed to prevent a judge who does not concur from delivering a dissenting opinion or judgment.", "debated": ["1949-06-06"], "adopted": "1949-06-06"}, "146": {"url": "https://www.constitutionofindia.net/articles/article-146-officers-and-servants-and-the-expenses-of-the-supreme-court/", "draft": "122", "draftText": "(1) The salaries, allowances and pensions payable to or in respect of the officers and servants of the Supreme Court shall be fixed by the Chief Justice of India in consultation with the President.\n(2) The administrative expenses of the Supreme Court, including all salaries, allowances and pensions payable to or in respect of the officers and servants of the court, shall be charged upon the revenues of India, and any fees or other moneys taken by the court shall form part of those revenues.", "debated": ["1949-05-27"], "adopted": "1949-05-27"}, "160": {"url": "https://www.constitutionofindia.net/articles/article-160-discharge-of-the-functions-of-the-governor-in-certain-contingencies/", "draft": "138", "draftText": "The Legislature of a State may make such provision as it thinks fit (The President may make such provision as he thinks fit) for the discharge of the functions of the Governor of the/a State in any contingency not provided for in this Chapter.", "debated": ["1949-06-01"], "adopted": "1949-06-01"}, "161": {"url": "https://www.constitutionofindia.net/articles/article-161-power-of-governor-to-grant-pardons-etc-and-to-suspend-remit-or-commute-sentences-in-certain-cases/", "draft": "141", "draftText": "The Governor of a State shall have the power to grant pardons, reprieves, respites or remissions of punishment, or to suspend, remit or commute the sentence, of any person convicted of any offence against any law relating to a matter with respect to which the Legislature of the State has power to make laws.", "debated": ["1949-06-01", "1949-10-17"], "adopted": "1949-10-17"}, "162": {"url": "https://www.constitutionofindia.net/articles/article-162-extent-of-executive-power-of-state/", "draft": "142", "draftText": "Subject to the provisions of this Constitution, the executive power of each State shall extend-\n(a) To the matters with respect to which the Legislature of the State has power to make laws, and\n(b) To the exercise of such rights, authority and jurisdiction as are exercisable under any agreement entered into with any State or group of States for the time being specified in Part III of the First Schedule under article 236 or article 237 of this Constitution.", "debated": ["1949-06-01"], "adopted": "1949-06-01"}, "163": {"url": "https://www.constitutionofindia.net/articles/article-163-council-of-ministers-to-aid-and-advise-governor/", "draft": "143", "draftText": "(1) There shall be a Council of ministers with the Chief Minister at the head to aid and advise the Governor in the exercise of his functions, except in so far as he is by or under this Constitution required to exercise his functions or any of them in his discretion.\n(2) If any question arises whether any matter is or is not a matter as respects which the Governor is by or under this Constitution required to act in his discretion, the decision of the Governor in his discretion shall be final, and the validity of anything done by the Governor shall not be called in question on the ground that he ought or ought not to have acted in his discretion.\n(3) The question whether any, and if so what, advice was tendered by ministers to the Governor shall not be inquired into in any court.", "debated": ["1949-06-01"], "adopted": "1949-06-01"}, "164": {"url": "https://www.constitutionofindia.net/articles/article-164-other-provisions-as-to-ministers/", "draft": "144", "draftText": "(1) The Governor's ministers shall be appointed by him and shall hold office during his pleasure:\nProvided that in the States of Bihar, Central Provinces and Berar and Orissa, there shall be a minister in charge of tribal welfare who may in addition be in charge of the welfare of the Scheduled Castes and backward classes or any other work.\n(2) Before a minister enters upon his office, the Governor shall administer to him the oaths of office and of secrecy according to the forms set out for the purpose in the Third Schedule.\n(3) A minister who, for any period of six consecutive months, is not a member of the Legislature of the State shall at the expiration of that period cease to be a minister.\n(4) In choosing his ministers and in his relations with them the Governor shall be generally guided by the Instructions set out in the Fourth Schedule, but the validity of anything done by the Governor shall not be called in question on the ground that it was done otherwise than in accordance with such Instructions.\n(5) The salaries and allowances of ministers shall be such as the Legislature of the State may from time to time by law determine and, until the Legislature of the State so determine, shall be as specified in the Second Schedule.\n(6) The functions of the Governor under this article with respect to the appointment and dismissal of ministers shall be exercised by him in his discretion.", "debated": ["1949-06-01", "1949-10-14"], "adopted": "1949-10-14"}, "165": {"url": "https://www.constitutionofindia.net/articles/article-165-advocate-general-for-the-state/", "draft": "145", "draftText": "(1) The Governor of each State shall appoint a person who is qualified to be appointed a judge of a High Court, to be Advocate-General for the State.\n(2) It shall be the duty of the Advocate-General to give advice to the Government of the State upon such legal matters and to perform such other duties of a legal character as may from time to time be referred or assigned to him by the Governor, and to discharge the functions conferred on him by or under this Constitution or any other law for the time being in force. (3) The Advocate-General shall retire from office upon the resignation of the Chief Minister in the State, but he may continue in office until his successor is appointed or he is reappointed.\n(4) The Advocate-General shall receive such remuneration as the Governor may determine.", "debated": ["1949-06-01"], "adopted": "1949-06-01"}, "186": {"url": "https://www.constitutionofindia.net/articles/article-186-salaries-and-allowances-of-the-speaker-and-deputy-speaker-and-the-chairman-and-deputy-chairman/", "draft": "163", "draftText": "There shall be paid to the Speaker and the Deputy Speaker of the Legislative Assembly and to the Chairman and the Deputy Chairman of the Legislative Council such salaries and allowances as may be respectively fixed by the Legislature of the State by law, and, until provision in that behalf is so made, such salaries and allowances as are specified in the Second Schedule.", "notDebated": true, "adopted": "1949-06-02"}, "185": {"url": "https://www.constitutionofindia.net/articles/article-185-the-chairman-or-the-deputy-chairman-not-to-preside-while-a-resolution-for-his-removal-from-office-is-under-consideration/", "debated": ["1949-06-02"], "adopted": "1949-06-02", "draft": "162A", "addedLater": true}, "187": {"url": "https://www.constitutionofindia.net/articles/article-187-secretariat-of-state-legislature/", "debated": ["1949-07-30"], "adopted": "1949-07-30", "draft": "163A", "addedLater": true}, "188": {"url": "https://www.constitutionofindia.net/articles/article-188-oath-or-affirmation-by-members/", "draft": "165", "draftText": "Every member of the Legislative Assembly or the Legislative Council of a State shall, before taking his seat, make and subscribe before the Governor or some person appointed in this behalf by him, a declaration according to the form set out for the purpose in the Third Schedule.", "notDebated": true, "adopted": "1949-06-02"}, "230": {"url": "https://www.constitutionofindia.net/articles/article-230-extension-of-jurisdiction-of-high-courts-to-union-territories/", "notDebated": true}, "231": {"url": "https://www.constitutionofindia.net/articles/article-231-establishment-of-a-common-high-court-for-two-or-more-states/", "notDebated": true}, "243N": {"url": "https://www.constitutionofindia.net/articles/article-243n-continuance-of-existing-laws-and-panchayats/", "notDebated": true}, "31A": {"url": "https://www.constitutionofindia.net/articles/article-31a-saving-of-laws-providing-for-acquisition-of-estates-etc/"}, "301": {"url": "https://www.constitutionofindia.net/articles/article-301-freedom-of-trade-commerce-and-intercourse/", "debated": ["1949-06-15", "1949-09-08"], "adopted": "1949-09-08", "addedLater": true}, "306": {"url": "https://www.constitutionofindia.net/articles/article-306-power-of-certain-states-in-part-b-of-the-first-schedule-to-impose-restrictions-on-trade-and-commerce/"}, "3": {"url": "https://www.constitutionofindia.net/articles/article-3-formation-of-new-states-and-alteration-of-areas-boundaries-or-names-of-existing-states/", "draft": "3", "draftText": "Parliament may by law-\n(a) Form a new State by separation of territory from a State or by uniting two or more States or parts of States;\n(b) Increase the area of any State;\n(c) Diminish the area of any State;\n(d) Alter the boundaries of any State;\n(e) Alter the name of any State:\nProvided that no Bill for the purpose shall be introduced in either House of Parliament except by the Government of India and unless\n(a) Either-\n(i) A representation in that behalf has been made to the President by a majority of the representatives of the territory in the Legislature of the State from which the territory is to be separated or excluded; or\n(ii) A resolution in that behalf has been passed by the Legislature of any State whose boundaries or name will be affected by the proposal to be contained in the Bill; and\n(b) Where the proposal contained in the Bill affects the boundaries or name of any State, other than a State for the time being specified in Part III of the First Schedule, the views of the Legislature of the State both with respect to the proposal to introduce the Bill and with respect to the provisions thereof have been ascertained by the President; and where such proposal affects the boundaries or name of any State for the time being specified in Part III of the First Schedule, the previous consent of the State to the proposal has been obtained.", "debated": ["1948-11-17", "1948-11-18", "1949-10-13"]}, "4": {"url": "https://www.constitutionofindia.net/articles/article-4/", "draft": "4", "draftText": "(1) Any law referred to in article 2 or article 3 of this Constitution shall contain such provisions for the amendment of the First Schedule as may be necessary to give effect to the provisions of the law and may also contain such incidental and consequential provisions as Parliament may deem necessary.\n(2) No such law as aforesaid shall be deemed to be an amendment of this Constitution for the purposes of article 304.", "debated": ["1948-11-18"], "adopted": "1948-11-18"}, "343": {"url": "https://www.constitutionofindia.net/articles/article-343-official-language-of-the-union/", "debated": ["1949-09-14"]}, "5": {"url": "https://www.constitutionofindia.net/articles/article-5-citizenship-at-the-commencement-of-the-constitution/", "draft": "5", "draftText": "At the date of commencement of this Constitution-\n(a) Every person who or either of whose parents or any of whose grandparents was born in the territory of India as defined in this Constitution and who has not made his permanent abode in any foreign State after the first day of April, 1947; and\n(b) Every person who or either of whose parents or any of whose grandparents was born in India as defined in the Government of India Act, 1935 (as originally enacted), or in Burma, Ceylon or Malaya, and who has his domicile in the territory of India as defined in this Constitution, shall be a citizen of India, provided that he has not acquired the citizenship of any foreign State before the date of commencement of this Constitution.\nExplanation.- For the purposes of clause (b) of this article, a person shall be deemed to have his domicile in the territory of India", "debated": ["1949-08-10", "1949-08-11", "1949-08-12"], "adopted": "1949-08-12"}, "6": {"url": "https://www.constitutionofindia.net/articles/article-6-rights-of-citizenship-of-certain-persons-who-have-migrated-to-india-from-pakistan/", "debated": ["1949-08-10", "1949-08-11", "1949-08-12"], "adopted": "1949-08-12", "draft": "5A"}, "7": {"url": "https://www.constitutionofindia.net/articles/article-7-rights-of-citizenship-of-certain-migrants-to-pakistan/", "debated": ["1949-08-10", "1949-08-11", "1949-08-12"], "draft": "5AA"}, "8": {"url": "https://www.constitutionofindia.net/articles/article-8-rights-of-citizenship-of-certain-persons-of-indian-origin-residing-outside-india/", "debated": ["1949-08-10", "1949-08-11", "1949-08-12"], "draft": "5B"}, "9": {"url": "https://www.constitutionofindia.net/articles/article-9-persons-voluntarily-acquiring-citizenship-of-a-foreign-state-not-to-be-citizens/", "debated": ["1949-08-10", "1949-08-11", "1949-08-12"]}, "10": {"url": "https://www.constitutionofindia.net/articles/article-10-continuance-of-the-rights-of-citizenship/", "debated": ["1949-08-10", "1949-08-11", "1949-08-12"], "draft": "5C"}, "344": {"url": "https://www.constitutionofindia.net/articles/article-344-commission-and-committee-of-parliament-on-official-language/", "debated": ["1949-09-12", "1949-09-13", "1949-09-14"], "adopted": "1949-09-14"}, "338A": {"url": "https://www.constitutionofindia.net/articles/article-338a-national-commission-for-scheduled-tribes/"}, "345": {"url": "https://www.constitutionofindia.net/articles/article-345-official-language-or-languages-of-a-state/"}, "346": {"url": "https://www.constitutionofindia.net/articles/article-346-official-language-for-communication-between-one-state-and-another-or-between-a-state-and-the-union/"}, "347": {"url": "https://www.constitutionofindia.net/articles/article-347-special-provision-relating-to-language-spoken-by-a-section-of-the-population-of-a-state/", "debated": ["1949-09-14"]}, "348": {"url": "https://www.constitutionofindia.net/articles/article-348-language-to-be-used-in-the-supreme-court-and-in-the-high-courts-and-for-acts-bills-etc/", "notDebated": true}, "349": {"url": "https://www.constitutionofindia.net/articles/article-349-special-procedure-for-enactment-of-certain-laws-relating-to-language/", "debated": ["1949-09-14"]}, "350": {"url": "https://www.constitutionofindia.net/articles/article-350-language-to-be-used-in-representations-for-redress-of-grievances/", "notDebated": true, "adopted": "1949-09-14"}, "11": {"url": "https://www.constitutionofindia.net/articles/article-11-parliament-to-regulate-the-right-of-citizenship-by-law/", "draft": "6", "draftText": "Parliament may, by law, make further provision regarding the acquisition and termination of citizenship and all other matters relating thereto.", "debated": ["1949-08-10", "1949-08-11", "1949-08-12"], "adopted": "1949-08-12"}, "351": {"url": "https://www.constitutionofindia.net/articles/article-351-directive-for-development-of-the-hindi-language/", "debated": ["1949-09-14"]}, "12": {"url": "https://www.constitutionofindia.net/articles/article-12-definitions/", "draft": "7", "draftText": "In this Part, unless the context otherwise requires, \"the State\" includes the Government and Parliament of India and the Government and the Legislature of each of the States and all local or other authorities within the territory of India.", "debated": ["1948-11-25"]}, "13": {"url": "https://www.constitutionofindia.net/articles/article-13-laws-inconsistent-with-or-in-derogation-of-the-fundamental-rights/", "draft": "8", "draftText": "(1) All laws in force immediately before the commencement of this Constitution in the territory of India, in so far as they are inconsistent with the provisions of this Part, shall, to the extent of such inconsistency, be void.\n(2) The State shall not make any law which takes away or abridges the rights conferred by this Part and any law made in contravention of this clause shall, to the extent of the contravention, be void:\nProvided that nothing in this clause shall prevent the State from making any law for the removal of any inequality, disparity, disadvantage or discrimination arising out of any existing law.\n(3) In this article, the expression \"law\" includes any Ordinance, order, bye-law, rule, regulation, notification, custom or usage having the force of law in the territory of India or any part thereof.", "debated": ["1948-11-25", "1948-11-26", "1948-11-29"], "adopted": "1948-11-29"}, "15": {"url": "https://www.constitutionofindia.net/articles/article-15-prohibition-of-discrimination-on-grounds-of-religion-race-caste-sex-or-place-of-birth/", "draft": "9", "draftText": "(1) The State shall not discriminate against any citizen on grounds only of religion, race, caste, sex or any of them. In particular, no citizen shall, on grounds only of religion, race, caste, sex or any of them, be subject to any disability, liability, restriction or condition with regard to-\n(a) Access to shops, public restaurants, hotels and places of public entertainment, or\n(b) The use of wells, tanks 3, roads and places of public resort maintained wholly or partly out of the revenues of the State or dedicated to the use of the general public.\n(2) Nothing in this article shall prevent the State from making any special provision for women and children.", "debated": ["1948-11-29"], "adopted": "1948-11-29"}, "16": {"url": "https://www.constitutionofindia.net/articles/article-16-equality-of-opportunity-in-matters-of-public-employment/", "draft": "10", "draftText": "(1) There shall be equality of opportunity for all citizens in matters of employment under the State.\n(2) No citizen shall, on grounds only of religion, race, caste, sex, descent, place of birth or any of them, be ineligible for any office under the State.\n(3) Nothing in this article shall prevent the State from making any provision for the reservation of appointments or posts in favour of any backward class of citizens who, in the opinion of the State, are not adequately represented in the services under the State.\n(4) Nothing in this article shall affect the operation of any law which provides that the incumbent of an office in connection with the affairs of any religious or denominational institution or any member of the governing body thereof shall be a person professing a particular religion or belonging to a particular denomination.", "debated": ["1948-11-30"], "adopted": "1948-11-30"}, "353": {"url": "https://www.constitutionofindia.net/articles/article-353-effect-of-proclamation-of-emergency/", "draft": "276", "draftText": "Where a Proclamation of Emergency is in operation, then, notwithstanding anything contained in this Constitution:\n(a) The executive power of the Union shall extend to the giving of directions to any State as to the manner in which the executive power thereof is to be exercised;\n(b) The power of Parliament to make laws with respect to any matter shall include power to make laws conferring powers and imposing duties or authorising the conferring of powers and the imposition of duties upon the Government of India or officers and authorities of the Government of India as respects that matter.", "debated": ["1949-08-03"]}, "18": {"url": "https://www.constitutionofindia.net/articles/article-18-abolition-of-titles/", "draft": "12", "draftText": "(1) No title shall be conferred by the State.\n(2) No citizen of India shall accept any title from any foreign State.\n(3) No person holding any office of profit or trust under the State shall, without the consent of the President, accept any present, emolument, title or office of any kind from or under any foreign State.", "debated": ["1948-11-30", "1948-12-01"], "adopted": "1948-12-01"}, "354": {"url": "https://www.constitutionofindia.net/articles/article-354-application-of-provisions-relating-to-distribution-of-revenues-while-a-proclamation-of-emergency-is-in-operation/", "draft": "277", "draftText": "The President may, while a Proclamation of Emergency is in operation, by order, direct that all or any of the provisions of articles 249 to 259 of this Constitution shall for such period, not extending in any case beyond the expiration of the financial year in which such proclamation ceases to operate, as may be specified in the order, have effect subject to such exceptions or modifications as he thinks fit.", "debated": ["1949-08-19", "1949-08-20"]}, "20": {"url": "https://www.constitutionofindia.net/articles/article-20-protection-in-respect-of-conviction-for-offences/", "draft": "14", "draftText": "(1) No person shall be convicted of any offence except for violation of a law in force at the time of the commission of the act charged as an offence, nor be subjected to a penalty greater than that which might have been inflicted under the law at the time of the commission of the offence.\n(2) No person shall be punished for the same offence more than once.\n(3) No person accused of any offence shall be compelled to be a witness against himself.", "debated": ["1948-12-02", "1948-12-03", "1948-12-06"], "adopted": "1948-12-06"}, "21": {"url": "https://www.constitutionofindia.net/articles/article-21-protection-of-life-and-personal-liberty/", "draft": "15", "draftText": "No person shall be deprived of his life or personal liberty except according to procedure established by law, nor shall any person be denied equality before the law or the equal protection of the laws within the territory of India.", "debated": ["1948-12-06", "1948-12-13"], "adopted": "1948-12-13"}, "22": {"url": "https://www.constitutionofindia.net/articles/article-22-protection-against-arrest-and-detention-in-certain-cases/", "debated": ["1949-09-15", "1949-09-16"], "adopted": "1949-09-16", "draft": "15A", "addedLater": true}, "21A": {"url": "https://www.constitutionofindia.net/articles/article-21a-right-to-education/"}, "23": {"url": "https://www.constitutionofindia.net/articles/article-23-prohibition-of-traffic-in-human-beings-and-forced-labour/", "draft": "17", "draftText": "(1) Traffic in human beings and begar and other similar forms of forced labour are prohibited and any contravention of this provision shall be an offence punishable in accordance with law.\n(2) Nothing in this article shall prevent the State from imposing compulsory service for public purposes. In imposing such service the State shall not make any discrimination on the ground of race, religion, caste or class.", "debated": ["1948-12-03"], "adopted": "1948-12-03"}, "24": {"url": "https://www.constitutionofindia.net/articles/article-24-prohibition-of-employment-of-children-in-factories-etc/", "draft": "18", "draftText": "No child below the age of fourteen years shall be employed to work in any factory or mine or engaged in any other hazardous employment.", "debated": ["1948-12-03"], "adopted": "1948-12-03"}, "25": {"url": "https://www.constitutionofindia.net/articles/article-25-freedom-of-conscience-and-free-profession-practice-and-propagation-of-religion/", "draft": "19", "draftText": "(1) Subject to public order, morality and health and to the other provisions of this Part, all persons are equally entitled to freedom of conscience and the right freely to profess, practise and propagate religion.\nExplanation.-The wearing and carrying of kirpans shall be deemed to be included in the profession of the Sikh religion.\n(2) Nothing in this article shall affect the operation of any existing law or preclude the State from making any law-\n(a) Regulating or restricting any economic, financial, political or other secular activity which may be associated with religious practice;\n(b) For social welfare and reform or for throwing open Hindu religious institutions of a public character to any class or section of Hindus.", "debated": ["1948-12-03", "1948-12-06"]}, "26": {"url": "https://www.constitutionofindia.net/articles/article-26-freedom-to-manage-religious-affairs/", "draft": "20", "draftText": "Every religious denomination or any section thereof shall have the right-\n(a) To establish and maintain institutions for religious and charitable purposes;\n(b) To manage its own affairs in matters of religion;\n(c) To own and acquire movable and immovable property; and\n(d) To administer such property in accordance with law.", "debated": ["1948-12-07"], "adopted": "1948-12-07"}, "27": {"url": "https://www.constitutionofindia.net/articles/article-27-freedom-as-to-payment-of-taxes-for-promotion-of-any-particular-religion/", "draft": "21", "draftText": "No person may be compelled to pay any taxes, the proceeds of which are specifically appropriated in payment of expenses for the promotion or maintenance of any particular religion or religious denomination.", "debated": ["1948-12-07"]}, "28": {"url": "https://www.constitutionofindia.net/articles/article-28-freedom-as-to-attendance-at-religious-instruction-or-religious-worship-in-certain-educational-institutions/", "draft": "22", "draftText": "(1) No religious instruction shall be provided by the State in any educational institution wholly maintained out of State funds:\nProvided that nothing in this clause shall apply to an educational institution which is administered by the State but has been established under any endowment or trust which requires that religious instruction shall be imparted in such institution.\n(2) No person attending any educational institution recognised by the State or receiving aid out of State funds shall be required to take part in any religious instruction that may be imparted in such institution or to attend any religious worship that may be conducted in such institution or in any premises attached thereto unless such person, or if such person is a minor, his guardian has given his consent thereto.\n(3) Nothing in this article shall prevent any community or denomination from providing religious instruction for pupils of that community or denomination in an educational institution outside its working hours.", "debated": ["1948-12-07"], "adopted": "1948-12-07"}, "29": {"url": "https://www.constitutionofindia.net/articles/article-29-protection-of-interests-of-minorities/", "debated": ["1948-12-07", "1948-12-08"], "adopted": "1948-12-08"}, "30": {"url": "https://www.constitutionofindia.net/articles/article-30-right-of-minorities-to-establish-and-administer-educational-institutions/", "draft": "23A", "draftText": "(3) (a) All minorities whether based on religion, community or language shall have the right to establish and administer educational institutions of their choice.\n(b) The State shall not, in granting aid to educational institutions, discriminate against any educational institution on the ground that it is under the management of a minority, whether based on religion, community or language.", "debated": ["1948-12-08"]}, "31C": {"url": "https://www.constitutionofindia.net/articles/article-31c-saving-of-laws-giving-effect-to-certain-directive-principles/"}, "32": {"url": "https://www.constitutionofindia.net/articles/article-32-remedies-for-enforcement-of-rights-conferred-by-this-part/", "draft": "25", "draftText": "(1) The right to move the Supreme Court by appropriate proceedings for the enforcement of the rights conferred by this Part is guaranteed.\n(2) The Supreme Court shall have power to issue directions or orders in the nature of the writs of habeas corpus, mandamus, prohibition, quo warranto and certiorari, whichever may be appropriate, for the enforcement of any of the rights conferred by this Part.\n(3) Parliament may by law empower any other court to exercise within the local limits of its jurisdiction all or any of the powers exercisable by the Supreme Court under clause (2) of this article.\n(4) The rights guaranteed by this article shall not be suspended except as otherwise provided for by this Constitution.", "debated": ["1948-12-09"], "adopted": "1948-12-09"}, "34": {"url": "https://www.constitutionofindia.net/articles/article-34-restriction-on-rights-conferred-by-this-part-while-martial-law-is-in-force-in-any-area/", "debated": ["1949-11-14", "1949-11-16"], "addedLater": true}, "38": {"url": "https://www.constitutionofindia.net/articles/article-38-state-to-secure-a-social-order-for-the-promotion-of-welfare-of-the-people/", "draft": "30", "draftText": "The State shall strive to promote the welfare of the people by securing and protecting as effectively as it may a social order in which justice, social, economic and political, shall inform all the institutions of the national life.", "debated": ["1948-11-19"]}, "39": {"url": "https://www.constitutionofindia.net/articles/article-39-certain-principles-of-policy-to-be-followed-by-the-state/", "draft": "31", "draftText": "The State shall, in particular, direct its policy towards securing-\n(i) That the citizens, men and women equally, have the right to an adequate means of livelihood;\n(ii) That the ownership and control of the material resources of the community are so distributed as best to subserve the common good;\n(iii) That the operation of the economic system does not result in the concentration of wealth and means of production to the common detriment;\n(iv) That there is equal pay for equal work for both men and women;\n(v) That the strength and health of workers, men and women and the tender age of children are not abused and that citizens are not forced by economic necessity to enter avocations unsuited to their age or strength;\n(vi) That childhood and youth are protected against exploitation and against moral and material abandonment.", "debated": ["1948-11-22"], "adopted": "1948-11-22"}, "39A": {"url": "https://www.constitutionofindia.net/articles/article-39a-equal-justice-and-free-legal-aid/"}, "40": {"url": "https://www.constitutionofindia.net/articles/article-40-organisation-of-village-panchayats/", "draft": "31A", "draftText": "The State shall take steps to organise village panchayats and endow them with such powers and authority as may be necessary to enable them to function as units of self-government.", "addedLater": true}, "41": {"url": "https://www.constitutionofindia.net/articles/article-41-right-to-work-to-education-and-to-public-assistance-in-certain-cases/", "draft": "32", "draftText": "The State shall, within the limits of its economic capacity and development, make effective provision for securing the right to work, to education and to public assistance in case of unemployment, old age, sickness, disablement, and other cases of undeserved want.", "debated": ["1948-11-23"]}, "42": {"url": "https://www.constitutionofindia.net/articles/article-42-provision-for-just-and-humane-conditions-of-work-and-maternity-relief/", "draft": "33", "draftText": "The State shall make provision for securing just and humane conditions of work and for maternity relief.", "debated": ["1948-11-23"], "adopted": "1948-11-23"}, "392": {"url": "https://www.constitutionofindia.net/articles/article-392-power-of-the-president-to-remove-difficulties/", "draft": "313", "draftText": "(1) Subject to the provisions of clause (1) of article 311 of this Constitution, the President may, for the purpose of removing any difficulties, particularly in relation to the transition from the provisions of the Government of India Act, 1935, to the provisions of this Constitution, by Order, direct that this Constitution shall, during such period as may be specified in the Order, have effect subject to such adaptations, whether by way of variation, addition, or repeal, as he may deem to be necessary or expedient:\nProvided that no such order shall be made after the first meeting of Parliament duly constituted under Chapter II of Part V of this Constitution.\n(2) Every order made under clause (1) of this article shall be laid before each House of Parliament.\nArticle 392, Constitution of India 1950\n(1) The President may, for the purpose of removing any difficulties, particularly in relation to the transition from the provisions of the Government of India Act, 1935, to the provisions of this Constitution, by order direct that this Constitution shall, during such period as may be specified in the order, have effect subject to such adaptations, whether by way of modification, addition or omission, as he may deem to be necessary or expedient:\nProvided that no such order shall be made after the first meeting of Parliament duly constituted under Chapter II of Part V.\n(2) Every order made under clause (1) shall be laid before Parliament.\n(3) The powers conferred on the President by this article, by article 324, by clause (3) of article 367 and by article 391 shall, before the commencement of this Constitution, be exercisable by the Governor-General of the Dominion of India.", "debated": ["1949-10-07"], "adopted": "1949-10-07"}, "43": {"url": "https://www.constitutionofindia.net/articles/article-43-living-wage-etc-for-workers/", "draft": "34", "draftText": "The State shall endeavour to secure, by suitable legislation or economic organisation or in any other way, to all workers, industrial or otherwise, work, a living wage, conditions of work ensuring a decent standard of life and full enjoyment of leisure and social and cultural opportunities.", "debated": ["1948-11-23"]}, "43A": {"url": "https://www.constitutionofindia.net/articles/article-43a-participation-of-workers-in-management-of-industries/"}, "43B": {"url": "https://www.constitutionofindia.net/articles/article-43b-promotion-of-co-operative-societies/"}, "45": {"url": "https://www.constitutionofindia.net/articles/article-45-provision-for-early-childhood-care-and-education-to-children-below-the-age-of-six-years/", "draft": "36", "draftText": "Every citizen is entitled to free primary education and the State shall endeavour to provide, within a period of ten years from the commencement of this Constitution, for free and compulsory education for all children until they complete the age of fourteen years.", "debated": ["1948-11-23"]}, "46": {"url": "https://www.constitutionofindia.net/articles/article-46-promotion-of-educational-and-economic-interests-of-scheduled-castes-scheduled-tribes-and-other-weaker-sections/", "draft": "37", "draftText": "The State shall promote with special care the educational and economic interests of the weaker sections of the people, and, in particular, of the Scheduled Castes and the scheduled tribes, and shall protect them from social injustice and all forms of exploitation.", "debated": ["1948-11-23"], "adopted": "1948-11-23"}, "47": {"url": "https://www.constitutionofindia.net/articles/article-47-duty-of-the-state-to-raise-the-level-of-nutrition-and-the-standard-of-living-and-to-improve-public-health/", "draft": "38", "draftText": "The State shall regard the raising of the level of nutrition and the standard of living of its people and the improvement of public health as among its primary duties.", "debated": ["1948-11-23", "1948-11-24"], "adopted": "1948-11-24"}, "31": {"url": "https://www.constitutionofindia.net/articles/article-31-compulsory-acquisition-of-property/", "draft": "24", "draftText": "(1) No person shall be deprived of his property save by authority of law.\n(2) No property, movable or immovable, including any interest in, or in any company owning, any commercial or industrial undertaking, shall be taken possession of or acquired for public purposes under any law authorising the taking of such possession or such acquisition, unless the law provides for the payment of compensation for the property taken possession of or acquired and either fixes the amount of the compensation, or specifies the principles on which, and the manner in which, the compensation is to be determined.\n(3) Nothing in clause (2) of this article shall affect-\n(a) The provisions of any existing law, or\n(b) The provisions of any law which the State may hereafter make for the purpose of imposing or levying any tax or for the promotion of public health or the prevention of danger to life or property."}, "31D": {"url": "https://www.constitutionofindia.net/articles/article-31d-saving-of-laws-in-respect-of-anti-national-activities/"}, "48": {"url": "https://www.constitutionofindia.net/articles/article-48-organisation-of-agriculture-and-animal-husbandry/", "debated": ["1949-11-14"], "draft": "38A", "addedLater": true}, "48A": {"url": "https://www.constitutionofindia.net/articles/article-48a-protection-and-improvement-of-environment-and-safeguarding-of-forests-and-wild-life/"}, "49": {"url": "https://www.constitutionofindia.net/articles/article-49-protection-of-monuments-and-places-and-objects-of-national-importance/", "draft": "39", "draftText": "It shall be the obligation of the State to protect every monument or place or object of artistic or historic interest, declared by Parliament by law to be of national importance, from spoliation, destruction, removal, disposal or export, as the case may be, and to preserve and maintain according to law made by Parliament all such monuments or places or objects.", "debated": ["1948-11-24"], "adopted": "1948-11-24"}, "50": {"url": "https://www.constitutionofindia.net/articles/article-50-separation-of-judiciary-from-executive/", "debated": ["1948-11-24", "1948-11-25"], "draft": "39A", "addedLater": true}, "2": {"url": "https://www.constitutionofindia.net/articles/article-2-admission-or-establishment-of-new-states/", "draft": "2", "draftText": "Parliament may, from time to time, by law admit into the Union, or establish, new States on such terms and conditions as it thinks fit.", "debated": ["1948-11-05", "1948-11-17"]}, "352": {"url": "https://www.constitutionofindia.net/articles/article-352-proclamation-of-emergency/", "draft": "275", "draftText": "(1) If the President is satisfied that a grave emergency exists whereby the security of India is threatened, whether by war or domestic violence, he may by proclamation, make a declaration to that effect.\n(2) A proclamation issued under clause (1) of this article (in this Constitution referred to as \"a Proclamation of Emergency\")-\n(a) May be revoked by a subsequent proclamation;\n(b) Shall be laid before each House of Parliament;\n(c) Shall cease to operate at the expiration of six months, unless before the expiration of that period it has been approved by resolutions of both Houses of Parliament.\n(3) A Proclamation of Emergency declaring that the security of India is threatened by war or by domestic violence may be made before the actual occurrence of war or of any such violence if the President is satisfied that there is imminent danger thereof.", "debated": ["1949-08-02"]}, "14": {"url": "https://www.constitutionofindia.net/articles/article-14-equality-before-law/", "debated": ["1948-12-06", "1948-12-13"], "partOf": "15"}, "17": {"url": "https://www.constitutionofindia.net/articles/article-17-abolition-of-untouchability/", "draft": "11", "draftText": "\"Untouchability\" is abolished and its practice in any form is forbidden. The enforcement of any disability arising out of \"Untouchability\" shall be an offence punishable in accordance with law.", "debated": ["1948-11-29"]}, "32A": {"url": "https://www.constitutionofindia.net/articles/article-32a-constitutional-validity-of-state-laws-not-to-be-considered-in-proceedings-under-article-32/"}, "33": {"url": "https://www.constitutionofindia.net/articles/article-33-power-of-parliament-to-modify-the-rights-conferred-by-this-part-in-their-application-to-forces-etc/", "draft": "26", "draftText": "Parliament may by law determine to what extent any of the rights guaranteed in this Part shall in their application to the members of the Armed Forces or the Forces charged with the maintenance of public order be restricted or abrogated so as to ensure the proper discharge of their duties and the maintenance of discipline among them.", "debated": ["1948-12-09"]}, "36": {"url": "https://www.constitutionofindia.net/articles/article-36-definition/", "draft": "28", "draftText": "In this Part, unless the context otherwise requires, \"the State\" has the same meaning as in Part III of this Constitution.", "debated": ["1948-11-19"]}, "37": {"url": "https://www.constitutionofindia.net/articles/article-37-application-of-the-principles-contained-in-this-part/", "draft": "29", "draftText": "The provisions contained in this Part shall not be enforceable by any court, but the principles therein laid down are nevertheless fundamental in the governance of the country and it shall be the duty of the State to apply these principles in making laws.", "debated": ["1948-11-19"], "adopted": "1948-11-19"}, "51": {"url": "https://www.constitutionofindia.net/articles/article-51-promotion-of-international-peace-and-security/", "draft": "40", "draftText": "The State shall promote international peace and security by the prescription of open, just and honourable relations between nations, by the firm establishment of the understandings of international law as the actual rule of conduct among governments and by the maintenance of justice and respect for treaty obligations in the dealings of organised people with one another.", "debated": ["1948-11-25"], "adopted": "1948-11-25"}, "51A": {"url": "https://www.constitutionofindia.net/articles/article-51a-fundamental-duties/"}, "52": {"url": "https://www.constitutionofindia.net/articles/article-52-the-president-of-india/", "draft": "41", "draftText": "There shall be a President of India.", "debated": ["1948-12-10"]}, "53": {"url": "https://www.constitutionofindia.net/articles/article-53-executive-power-of-the-union/", "draft": "42", "draftText": "(1) The executive power of the Union shall be vested in the President and may be exercised by him in accordance with the Constitution and the law.\n(2) Without prejudice to the generality of the foregoing provision, the supreme command of the Defence Forces of India shall be vested in the President and the exercise thereof shall be regulated by law.\n(3) Nothing in this article shall-\n(a) Be deemed to transfer to the President any functions conferred by any existing law on the Government of any State or other authority, or\n(b) Prevent Parliament from conferring by law functions on authorities other than the President.", "debated": ["1948-12-10", "1949-10-16"]}, "54": {"url": "https://www.constitutionofindia.net/articles/article-54-election-of-president/", "draft": "43", "draftText": "The President shall be elected by the members of an electoral college consisting of-\n(a) The members of both Houses of Parliament, and\n(b) The elected members of the Legislatures of the States.", "debated": ["1948-12-10", "1948-12-13"]}, "58": {"url": "https://www.constitutionofindia.net/articles/article-58-qualifications-for-election-as-president/", "draft": "47", "draftText": "(1) No person shall be eligible for election as President unless he-\n(a) Is a citizen of India,\n(b) Has completed the age of thirty-five years, and\n(c) Is qualified for election as a member of the House of the People.\n(2) A person shall not be eligible for election as President if he holds any office or position of emolument under the Government of India or the Government of any State or under any local or other authority subject to the control of any of the said Governments.\nExplanation.- For the purposes of this clause a person shall not be deemed to hold any office or position of emolument by reason only that-\n(a) He is a minister either for India or for any State for the time being specified in Part I of the First Schedule; or\n(b) He is a minister for any State for the time being specified in Part III of the First Schedule, if he is responsible to the Legislature of the State, or, where there are two Houses of the Legislature of the State, to the Lower House of the Legislature, and if not less than three-fourths of the members of the Legislature or House, as the case may be, are elected.", "debated": ["1948-12-27", "1949-10-13"]}, "59": {"url": "https://www.constitutionofindia.net/articles/article-59-conditions-of-presidents-office/", "draft": "48", "draftText": "(1) The President shall not be a member either of Parliament or of the Legislature of any State, and if a member of Parliament or of the Legislature of any State be elected President, he shall be deemed to have vacated his seat in Parliament or such Legislature, as the case may be, on the date on which he enters upon his office as President.\n(2) The President shall not hold any other office or position of emolument.\n(3) The President shall have an official residence and there shall be paid to the President such emoluments and allowances as may be determined by Parliament by law and, until provision in that behalf is so made, such emoluments and allowances as are specified in the Second Schedule.\n(4) The emoluments and allowances of the President shall not be diminished during his term of office.", "debated": ["1948-12-27", "1949-10-14"]}, "60": {"url": "https://www.constitutionofindia.net/articles/article-60-oath-or-affirmation-by-the-president/", "draft": "49", "draftText": "Every President and every person acting as President or discharging the functions of the President shall before entering upon his office make and subscribe in the presence of the Chief Justice of India an affirmation or oath in the following form, that is to say-\n\"I, A. B., do solemnly affirm (or swear) that I will faithfully execute the office of President (or discharge the functions of the President) of India and will to the best of my ability preserve, protect and defend the Constitution and the law and that I will devote myself to the service and well-being of the people of India.\"", "debated": ["1948-12-27"], "adopted": "1948-12-27"}, "368": {"url": "https://www.constitutionofindia.net/articles/article-368-power-of-parliament-to-amend-the-constitution-and-procedure-therefor/", "draft": "304", "draftText": "(1) An amendment of the Constitution may be initiated by the introduction of a Bill for the purpose in either House of Parliament, and when the Bill is passed in each House by a majority of the total membership of that House and by a majority of not less than two-thirds of the members of that House present and voting, it shall be presented to the President for his assent and upon such assent being given to the Bill, the Constitution shall stand amended in accordance with the terms of the Bill:\nProvided that if such amendment seeks to make any change in-\n(a) Any of the Lists in the Seventh Schedule;\n(b) The representation of States in Parliament; or\n(c) The powers of the Supreme Court. the amendment shall also require to be ratified by the Legislatures of not less than one-half of the States for the time being specified in Part I of the First Schedule and the Legislatures of not less than one-third of the States for the time being specified in Part III of that Schedule.\n(2) Notwithstanding anything in the last preceding clause, an amendment of the Constitution seeking to make any change in the provisions of this Constitution relating to the method of choosing a Governor or the number of Houses of the Legislature in any State for the time being specified in Part I of the First Schedule may be initiated by the introduction of a Bill for the purpose in the Legislative Assembly of the State or, where the State has a Legislative Council, in either House of the Legislature of the State, and when the Bill is passed by the Legislative Assembly or, where the State has a Legislative Council, by both Houses of the Legislature of the State, by a majority of the total membership of the Assembly or each House, as the case may be, it shall be submitted to Parliament for ratification, and when it is ratified by each House of Parliament by a majority of the total membership of that House it shall be presented to the President for assent and upon such assent being given to the Bill, the Constitution shall stand amended in accordance with the terms of the Bill.\nExplanation.-Where a group of States is for the time being specified in Part III of the First Schedule, the entire group shall be deemed to be a single State for the purposes of the proviso to clause (1) of this article.", "debated": ["1949-09-17"]}, "55": {"url": "https://www.constitutionofindia.net/articles/article-55-manner-of-election-of-president/", "draft": "44", "draftText": "(1) As far as practicable, there shall be uniformity in the scale of representation of the different States at the election of the President.\n(2) For the purpose of securing such uniformity the number of votes which each elected member of Parliament and of the Legislature of each State is entitled to cast at such election shall be determined in the following manner :-\n(a) Every elected member of the Legislature of a State shall have as many votes as there are multiples of one thousand in the quotient obtained by dividing the population of the State by the total number of elected members of the Legislature;\n(b) If, after taking the said multiples of one thousand, the remainder is not less than five hundred, then the vote of each member referred to in sub-clause (a) of this clause shall be further increased by one;\n(c) Each elected member of either House of Parliament shall have such number of votes as may be obtained by dividing the total number of votes assigned to the members of the Legislatures of the States under sub-clauses (a) and (b) of this clause by the total number of such members, fractions exceeding one-half being counted as one and other fractions being disregarded.\n(3) The election of the President shall be held in accordance with the system of proportional representation by means of the single transferable vote and the voting at such election shall be by secret ballot.\nExplanation.—In this article, the expression \"the Legislature of a State\" means, where the Legislature is bicameral, the Lower House of the Legislature, and the expression \"population\" means the population as ascertained at the last preceding census.", "debated": ["1948-12-13"]}, "56": {"url": "https://www.constitutionofindia.net/articles/article-56-term-of-office-of-president/", "draft": "45", "draftText": "The President shall hold office for a term of five years from the date on which he enters upon his office:\nProvided that—\n(a) The President may, by resignation under his hand addressed to the Chairman of the Council of States and the Speaker of the House of the People, resign his office;\n(b) The President may, for violation of the Constitution, be removed from office by impeachment in the manner provided in article 50 of this Constitution:\n(c) The President shall, notwithstanding the expiration of his term, continue to hold office until his successor enters upon his office.", "debated": ["1948-12-13"]}, "57": {"url": "https://www.constitutionofindia.net/articles/article-57-eligibility-for-re-election/", "draft": "46", "draftText": "A person who holds, or who has held, office as President shall be eligible for re-election to that office once, but only once.", "debated": ["1948-12-13"]}, "62": {"url": "https://www.constitutionofindia.net/articles/article-62-time-of-holding-election-to-fill-vacancy-in-the-office-of-president-and-the-term-of-office-of-person-elected-to-fill-casual-vacancy/", "draft": "51", "draftText": "(1) An election to fill a vacancy caused by the expiration of the term of office of President shall be completed before the expiration of the term.\n(2) An election to fill a vacancy in the office of President occurring by reason of his death, resignation or removal, or otherwise shall be held as soon as possible after, and in no case later than six months from, the date of occurrence of the vacancy; and the person elected to fill the vacancy shall be entitled to hold office for the full term of five years as provided in article 45 of this Constitution.", "debated": ["1948-12-28"]}, "61": {"url": "https://www.constitutionofindia.net/articles/article-61-procedure-for-impeachment-of-the-president/", "draft": "50", "draftText": "(1) When a President is to be impeached for violation of the Constitution, the charge shall be preferred by either House of Parliament.\n(2) No such charge shall be preferred unless-\n(a) The proposal to prefer such charge is contained in a resolution which has been moved after a notice in writing signed by not less than thirty members of the House has been given of their intention to move the resolution, and\n(b) Such resolution has been supported by not less than two-thirds of the total membership of the House.\n(3) When a charge has been so preferred by either House of Parliament, the other House shall investigate the charge or cause the charge to be investigated and the President shall have the right to appear and to be represented at such investigation.\n(4) If as a result of the investigation a resolution is passed, supported by not less than two-thirds of the total membership of the House by which the charge was investigated or caused to be investigated, declaring that the charge preferred against the President has been sustained, such resolution shall have the effect of removing the President from his office as from the date on which the resolution is so passed.", "debated": ["1948-12-28"]}, "63": {"url": "https://www.constitutionofindia.net/articles/article-63-the-vice-president-of-india/", "draft": "52", "draftText": "There shall be a Vice-President of India.", "debated": ["1948-12-28"]}, "64": {"url": "https://www.constitutionofindia.net/articles/article-64-the-vice-president-to-be-ex-officio-chairman-of-the-council-of-states/", "draft": "53", "draftText": "The Vice-President shall be ex-officio Chairman of the Council of States and shall not hold any other office or position of emolument:\nProvided that during any period when the Vice-President acts as President or discharges the functions of the President under article 54 of this Constitution, he shall not perform the duties of the office of Chairman of the Council of States.", "debated": ["1948-12-28"], "adopted": "1948-12-28"}, "65": {"url": "https://www.constitutionofindia.net/articles/article-65-the-vice-president-to-act-as-president-or-to-discharge-his-functions-during-casual-vacancies-in-the-office-or-during-the-absence-of-president/", "draft": "54", "draftText": "(1) In the event of the occurrence of any vacancy in the office of the President by reason of his death, resignation or removal, or otherwise, the Vice-President shall act as President until the date on which a new President elected in accordance with the provisions of this Chapter to fill such vacancy enters upon his office.\n(2) When the President is unable to discharge his functions owing to absence, illness or any other cause, the Vice-President shall discharge his functions until the date on which the President resumes his duties.\n(3) The Vice-President shall, during, and in respect of, the period while he is so acting as, or discharging the functions of the, President, have all the powers and immunities of the President.", "debated": ["1948-12-28"]}, "66": {"url": "https://www.constitutionofindia.net/articles/article-66-election-of-vice-president/", "draft": "55 (1) to (4)", "draftText": "(1) The Vice-President shall be elected by the members of both Houses of Parliament assembled at a joint meeting in accordance with the system of proportional representation by means of the single transferable vote and the voting at such election shall be by secret ballot.\n(2) The Vice-President shall not be a member either of Parliament or of the Legislature of any State, and if a member of Parliament or of the Legislature of any State be elected Vice-President, he shall be deemed to have vacated his seat in Parliament or such Legislature, as the case may be, on the date on which he enters upon his office as Vice-President.\n(3) No person shall be eligible for election as Vice-President unless he-\n(a) Is a citizen of India;\n(b) Has completed the age of thirty-five years; and\n(c) Is qualified for election as a member of the Council of States.\n(4) A person shall not be eligible for election as Vice-President if he holds any office or position of emolument under the Government of India or the Government of any State or under any local or other authority subject to the control of any of the said Governments.\nExplanation.-For the purposes of this clause, a person shall not be deemed to hold any office or position of emolument by reason only that-\n(a) He is a minister either for India or for any State for the time being specified in Part I of the First Schedule; or\n(b) He is a minister for any State for the time being specified in Part III of the First Schedule, if he is responsible to the Legislature of the State, or, where there are two Houses of the Legislature of the State, to the Lower House of such Legislature, and if not less than three-fourths of the members of such Legislature or House, as the case may be, are elected.", "debated": ["1948-11-28", "1948-11-29", "1949-10-13"]}, "67": {"url": "https://www.constitutionofindia.net/articles/article-67-term-of-office-of-vice-president/", "draft": "56", "draftText": "The Vice-President shall hold office for a term of five years from the date on which he enters upon his office:\nProvided that-\n(a) A Vice-President may, by writing under his hand addressed to the President, resign his office;\n(b) A Vice-President may be removed from his office for incapacity or want of confidence by a resolution of the Council of States passed by a majority of all the then members of the Council and agreed to by the House of the People; but no resolution for the purpose of this clause shall be moved unless at least fourteen days' notice has been given of the intention to move the resolution;\n(c) A Vice-President shall, notwithstanding the expiration of his term, continue to hold office until his successor enters upon his office.", "debated": ["1948-12-29"]}, "68": {"url": "https://www.constitutionofindia.net/articles/article-68-time-of-holding-election-to-fill-vacancy-in-the-office-of-vice-president-and-the-term-of-office-of-person-elected-to-fill-casual-vacancy/", "draft": "55 (5) to (6)", "draftText": "(5) An election to fill a vacancy caused by the expiration of the term of office of Vice-President shall be completed before the expiration of the term.\n(6) An election to fill a vacancy in the office of Vice-President occurring by reason of his death, resignation or removal, or otherwise shall be held as soon as possible after the occurrence of the vacancy, and the person elected to fill such vacancy shall be entitled to hold office for the full term of five years as provided in article 56 of this Constitution.", "debated": ["1948-12-28", "1948-12-29", "1949-10-13"]}, "69": {"url": "https://www.constitutionofindia.net/articles/article-69-oath-or-affirmation-by-the-vice-president/", "notDebated": true, "addedLater": true}, "71": {"url": "https://www.constitutionofindia.net/articles/article-71-matters-relating-to-or-connected-with-the-election-of-a-president-or-vice-president/", "draft": "58", "draftText": "(1) All doubts and disputes arising out of or in connection with the election of a President or Vice-President shall be inquired into and decided by the Supreme Court whose decision shall be final.\n(2) Subject to the provisions of this Constitution, Parliament may by law regulate any matter relating to or connected with the election of a President or Vice-President.", "debated": ["1948-12-29"]}, "72": {"url": "https://www.constitutionofindia.net/articles/article-72-power-of-president-to-grant-pardons-etc-and-to-suspend-remit-or-commute-sentences-in-certain-cases/", "draft": "59", "draftText": "(1) The President shall have the power to grant pardons, reprieves, respites or remissions of punishment or to suspend, remit or commute the sentence of any person convicted of any offence-\n(a) In all cases where the punishment or sentence is by a Court Martial;\n(b) In all cases where the punishment or sentence is for an offence under any law relating to a matter with respect to which Parliament has, and the Legislature of the State in which the offence is committed has not, power to make laws:\n(c) In all cases where the sentence is a sentence of death.\n(2) Nothing in sub-clause (a) of clause (1) of this article shall affect the power conferred by law on any officer of the Armed Forces of India to suspend, remit or commute a sentence passed by a Court Martial.\n(3) Nothing in sub-clause (c) of clause (1) of this article shall affect the power to suspend, remit or commute a sentence of death exercisable by the Governor or the Ruler of the State under any law for the time being in force.", "debated": ["1948-12-29", "1949-10-17"]}, "73": {"url": "https://www.constitutionofindia.net/articles/article-73-extent-of-executive-power-of-the-union/", "draft": "60", "draftText": "(1) Subject to the provisions of this Constitution, the executive power of the Union shall extend-\n(a) To the matters with respect to which Parliament has power to make laws; and\n(b) To the exercise of such rights, authority and jurisdiction as are exercisable by the Government of India by virtue of any treaty or agreement:\nProvided that the executive power referred to in sub-clause (a) of this clause shall not, save as expressly provided in this Constitution or in any law made by Parliament, extend in any State to matters with respect to which the Legislature of the State has also power to make laws.\n(2) Until otherwise provided by Parliament, a State and any officer or authority of a State may, notwithstanding anything contained in this article, continue to exercise in matters with respect to which Parliament has power to make laws for that State such executive power or functions as the State or officer or authority thereof could exercise immediately before the commencement of this Constitution.", "debated": ["1948-12-29", "1948-12-30"], "adopted": "1948-12-30"}, "74": {"url": "https://www.constitutionofindia.net/articles/article-74-council-of-ministers-to-aid-and-advise-president/", "draft": "61", "draftText": "(1) There shall be a Council of ministers with the Prime Minister at the head to aid and advise the President in the exercise of his functions.\n(2) The question whether any, and if so what, advice was tendered by ministers to the President shall not be inquired into in any court.", "debated": ["1948-12-30"], "adopted": "1948-12-30"}, "75": {"url": "https://www.constitutionofindia.net/articles/article-75-other-provisions-as-to-ministers/", "draft": "62", "draftText": "(1) The Prime Minister shall be appointed by the President and the other ministers shall be appointed by the President on the advice of the Prime Minister.\n(2) The ministers shall hold office during the pleasure of the President.\n(3) The Council shall be collectively responsible to the House of the People.\n(4) Before a minister enters upon his office, the President shall administer to him the oaths of office and of secrecy according to the forms set out for the purpose in the Third Schedule.\n(5) A minister who, for any period of six consecutive months, is not a member of either House of Parliament shall at the expiration of that period cease to be a minister.\n(6) The salaries and allowances of ministers shall be such as Parliament may from time to time by law determine and, until Parliament so determine, shall be as specified in the Second Schedule.", "debated": ["1948-12-30", "1948-12-31", "1949-10-14", "1949-10-17"]}, "76": {"url": "https://www.constitutionofindia.net/articles/article-76-attorney-general-for-india/", "draft": "63", "draftText": "(1) The President shall appoint a person, who is qualified to be appointed a judge of the Supreme Court, to be Attorney-General for India.\n(2) It shall be the duty of the Attorney-General to give advice to the Government of India upon such legal matters and to perform such other duties of a legal character, as may from time to time be referred or assigned to him by the President, and to discharge the functions conferred on him by or under this Constitution or any other law for the time being in force.\n(3) In the performance of his duties the Attorney-General shall have right of audience in all courts in the territory of India.\n(4) The Attorney-General shall hold office during the pleasure of the President, and shall receive such remuneration as the President may determine.", "debated": ["1949-01-07"]}, "77": {"url": "https://www.constitutionofindia.net/articles/article-77-conduct-of-business-of-the-government-of-india/", "draft": "64", "draftText": "(1) All executive action of the Government of India shall be expressed to be taken in the name of the President.\n(2) Orders and other instruments made and executed in the name of the President shall be authenticated in such manner as may be specified in rules to be made by the President, and the validity of an order or instrument which is so authenticated shall not be called in question on the ground that it is not an order or instrument made or executed by the President.", "debated": ["1949-01-07"], "adopted": "1949-01-07"}, "78": {"url": "https://www.constitutionofindia.net/articles/article-78-duties-of-prime-minister-as-respects-the-furnishing-of-information-to-the-president-etc/", "draft": "65", "draftText": "It shall be the duty of the Prime Minister-\n(a) To communicate to the President all decisions of the Council of ministers relating to the administration of the affairs of the Union and proposals for legislation:\n(b) To furnish such information relating to the administration of the affairs of the Union and proposals for legislation as the President may call for; and\n(c) If the President so requires, to submit for the consideration of the Council of ministers any matter on which a decision has been taken by a minister but which has not been considered by the Council.", "debated": ["1949-01-07"]}, "79": {"url": "https://www.constitutionofindia.net/articles/article-79-constitution-of-parliament/", "draft": "66", "draftText": "There shall be a Parliament for the Union which shall consist of the President and two Houses to be known respectively as the Council of States and the House of the People.", "debated": ["1949-01-03"]}, "80": {"url": "https://www.constitutionofindia.net/articles/article-80-composition-of-the-council-of-states/", "draft": "67 (1) to (4)", "draftText": "(1) The Council of States shall consist of two hundred and fifty members of whom-\n(a) Fifteen members shall be nominated by the President in the manner provided in clause (2) of this article; and\n(b) The remainder shall be representatives of the States:\nProvided that the total number of representatives of the States for the time being specified in Part III of the First Schedule shall not exceed forty per cent of this remainder.\n(2) The members to be nominated by the President under sub-clause (a) of clause (1) of this article shall consist of persons having special knowledge or practical experience in respect of such matters as the following, namely,-\n(a) Literature, art, science and education;\n(b) Agriculture, fisheries and allied subjects;\n(c) Engineering and architecture;\n(d) Public administration and social services.\n(3) The representatives of each State for the time being specified in Part I or Part III of the First Schedule in the Council of States shall-\n(a) Where the Legislature of the State has two Houses, be elected by the elected members of the Lower House;\n(b) Where the Legislature of the State has only one House, be elected by the elected members of that House; and\n(c) Where there is no House of the Legislature for the State, be chosen in such manner as Parliament may by law prescribe.\n(4) The representatives of the States for the time being specified in Part II of the First Schedule in the Council of States shall be chosen in such manner as Parliament may by law prescribe.", "debated": ["1949-01-03", "1949-10-17"]}, "81": {"url": "https://www.constitutionofindia.net/articles/article-81-composition-of-the-house-of-the-people/", "debated": ["1949-01-04", "1949-10-17"]}, "82": {"url": "https://www.constitutionofindia.net/articles/article-82-readjustment-after-each-census/", "draft": "67 (8)", "draftText": "Upon the completion of each census the representation of the several States in the Council of States and of the several territorial constituencies in the House of the People shall, subject to the provisions of Article 289 of this Constitution, be readjusted by such authority, in such manner and with effect from such date as Parliament may, by law, determine.", "debated": ["1949-01-04"]}, "83": {"url": "https://www.constitutionofindia.net/articles/article-83-duration-of-houses-of-parliament/", "draft": "68", "draftText": "(1) The Council of States shall not be subject to dissolution, but as nearly as possible one-third of the members thereof shall retire as soon as may be on the expiration of every second year in accordance with the provisions made in that behalf by Parliament by law.\n(2) The House of the People, unless sooner dissolved, shall continue for five years from the date appointed for its first meeting and no longer, and the expiration of the said period of five years shall operate as the dissolution of the House:\nProvided that the said period may, while a Proclamation of Emergency is in operation, be extended by the President for a period not exceeding one year at a time and not extending in any case beyond a period of six months after the Proclamation has ceased to operate.", "debated": ["1949-05-18"], "adopted": "1949-05-18"}, "70": {"url": "https://www.constitutionofindia.net/articles/article-70-discharge-of-presidents-functions-in-other-contingencies/", "draft": "57", "draftText": "Parliament may make such provision as it thinks fit for the discharge of the functions of the President in any contingency not provided for in this Chapter.", "debated": ["1948-12-29"]}, "123": {"url": "https://www.constitutionofindia.net/articles/article-123-power-of-president-to-promulgate-ordinances-during-recess-of-parliament/", "draft": "102", "draftText": "(1) If at any time, except when both Houses of Parliament are in session, the President is satisfied that circumstances exist which render it necessary for him to take immediate action, he may promulgate such Ordinances as the circumstances appear to him to require.\n(2) An Ordinance promulgated under this article shall have the same force and effect as an Act of Parliament assented to by the President, but every such Ordinance-\n(a) Shall be laid before both Houses of Parliament and shall cease to operate at the expiration of six weeks from the re-assembly of Parliament, or, if before the expiration of that period resolutions disapproving it are passed by both Houses, upon the passing of the second of those resolutions; and\n(b) May be withdrawn at any time by the President.\nExplanation:–Where the Houses of Parliament are summoned to reassemble on different dates, the period of six weeks shall be reckoned from the later of those dates for the purposes of this clause.\n(3) If and so far as an Ordinance under this article makes any provision which Parliament would not under this Constitution be competent to enact, it shall be void.", "debated": ["1949-05-23"], "adopted": "1949-05-23"}, "19": {"url": "https://www.constitutionofindia.net/articles/article-19-protection-of-certain-rights-regarding-freedom-of-speech-etc/", "draft": "13", "draftText": "(1) Subject to the other provisions of this article, all citizens shall have the right-\n(a) To freedom of speech and expression;\n(b) To assemble peaceably and without arms;\n(c) To form associations or unions;\n(d) To move freely throughout the territory of India;\n(e) To reside and settle in any part of the territory of India;\n(f) To acquire, hold and dispose of property; and\n(g) To practise any profession, or to carry on any occupation, trade or business.\n(2) Nothing in sub-clause (a) of clause (1) of this article shall affect the operation of any existing law, or prevent the State from making any law, relating to libel, slander, defamation, sedition or any other matter which offends against decency. or morality or undermines the authority or foundation of the State.\n(3) Nothing in sub-clause (b) of the said clause shall affect the operation of any existing law, or prevent the State from making any law, imposing in the interests of public order restrictions on the exercise of the right conferred by the said sub-clause.\n(4) Nothing in sub-clause (c) of the said clause shall affect the operation of any existing law, or prevent the State from making any law, imposing, in the interests of the general public, restrictions on the exercise of the right conferred by the said sub-clause.\n(5) Nothing in sub-clauses (d), (e) and (f) of the said clause shall affect the operation of any existing law, or prevent the State from making any law, imposing restrictions on the exercise of any of the rights conferred by the said sub-clauses either in the interests of the general public or for the protection of the interests of any aboriginal tribe.\n(6) Nothing in sub-clause (g) of the said clause shall affect the operation of any existing law, or prevent the State from making any law, imposing in the interests of public order, morality or health, restrictions on the exercise of the right conferred by the said sub-clause and in particular prescribing, or empowering any authority to prescribe, the professional or technical qualifications necessary for practising any profession or carrying on any occupation, trade or business.", "debated": ["1948-12-01", "1948-12-02", "1949-10-16", "1949-10-17"]}, "44": {"url": "https://www.constitutionofindia.net/articles/article-44-uniform-civil-code-for-the-citizens/", "draft": "35", "draftText": "The State shall endeavour to secure for the citizens a uniform civil code throughout the territory of India.", "debated": ["1948-11-23"]}, "1": {"url": "https://www.constitutionofindia.net/articles/article-1-name-and-territory-of-the-union/", "draft": "1", "draftText": "(1) India shall be a Union of States.\n(2) The States shall mean the States for the time being specified in Parts I, II and III of the First Schedule.\n(3) The territory of India shall comprise-\n(a) The territories of the States;\n(b) The territories for the time being specified in Part IV of the First Schedule; and\n(c) Such other territories as may be acquired.", "debated": ["1948-11-15", "1948-11-17", "1949-09-17", "1949-09-18"], "adopted": "1949-09-18"}, "245": {"url": "https://www.constitutionofindia.net/articles/article-245-extent-of-laws-made-by-parliament-and-by-the-legislatures-of-states/", "draft": "216", "draftText": "(1) Subject to the provisions of this Constitution, Parliament may make laws for the whole or any part of the territory of India, and the Legislature of a State may make laws for the whole or any part of the State.\n(2) No law made by Parliament shall be deemed to be invalid on the ground that it would have extraterritorial operation."}, "246A": {"url": "https://www.constitutionofindia.net/articles/article-246a-special-provision-with-respect-to-goods-and-services-tax/", "notDebated": true}, "247": {"url": "https://www.constitutionofindia.net/articles/article-247-power-of-parliament-to-provide-for-the-establishment-of-certain-additional-courts/", "draft": "219", "draftText": "Notwithstanding anything in this Chapter, Parliament may by law provide for the establishment of any additional courts for the better administration of laws made by Parliament or of any existing law with respect to a matter enumerated in the Union List.", "debated": ["1949-06-13"]}, "250": {"url": "https://www.constitutionofindia.net/articles/article-250-power-of-parliament-to-legislate-with-respect-to-any-matter-in-the-state-list-if-a-proclamation-of-emergency-is-in-operation/", "draft": "227", "draftText": "(1) Notwithstanding anything in this Chapter, Parliament shall, while a Proclamation of Emergency is in operation, have power to make laws for the whole or any part of the territory of India with respect to any of the matters enumerated in the State List.\n(2) A law made by Parliament which Parliament would not but for the issue of a Proclamation of Emergency have been competent to make shall, to the extent of the incompetency, cease to have effect on the expiration of a period of six months after the Proclamation has ceased to operate, except as respects\" things done or omitted to be done before the expiration of the said period.", "debated": ["1949-06-13"]}, "251": {"url": "https://www.constitutionofindia.net/articles/article-251-inconsistency-between-laws-made-by-parliament-under-articles-249-and-250-and-laws-made-by-the-legislatures-of-states/", "draft": "228", "draftText": "Nothing in articles 226 and 227 of this Constitution shall restrict the power of the Legislature of a State to make any law which under this Constitution it has power to make, but if any provision of a law made by the Legislature of a State is repugnant to any provision of a law made by Parliament which Parliament has under either of the said articles power to make, the law made by Parliament, whether passed before or after the law made by the Legislature of the State shall prevail, and the law made by the Legislature of the State shall to the extent of the repugnancy, but so long only as the law made by Parliament continues to have effect, be inoperative.", "debated": ["1949-06-13"]}, "256": {"url": "https://www.constitutionofindia.net/articles/article-256-obligation-of-states-and-the-union/", "draft": "233", "draftText": "The executive power of every State shall be so exercised as to ensure compliance with the laws made by Parliament and any existing laws which apply in that State and the executive power of the Union shall extend to the giving of such directions to a State as may appear to the Government of India to be necessary for this purpose.", "debated": ["1949-06-13"]}, "257A": {"url": "https://www.constitutionofindia.net/articles/article-257a-assistance-to-states-by-deployment-of-armed-forces-or-other-forces-of-the-union/"}, "258A": {"url": "https://www.constitutionofindia.net/articles/article-258a-power-of-the-states-to-entrust-functions-to-the-union/", "notDebated": true}, "259": {"url": "https://www.constitutionofindia.net/articles/article-259-armed-forces-in-states-in-part-b-of-the-first-schedule/"}, "246": {"url": "https://www.constitutionofindia.net/articles/article-246-subject-matter-of-laws-made-by-parliament-and-by-the-legislatures-of-states/", "draft": "217", "draftText": "(1) Notwithstanding anything in the two next succeeding clauses, Parliament has exclusive power to make laws with respect to any of the matters enumerated in List I in the Seventh Schedule (in this Constitution referred to as the \"Union List\").\n(2) Notwithstanding anything in the next succeeding clause, Parliament and, subject to the preceding clause, the Legislature of any State for the time being specified in Part I of the First Schedule also, have power to make laws with respect to any of the matters enumerated in List III in the Seventh Schedule (in this Constitution referred to as the \"Concurrent List\").\n(3) Subject to the two preceding clauses, the Legislature of any State for the time being specified in Part I of the First Schedule has exclusive power to make laws for such State or any part thereof with respect to any of the matters enumerated in List II in the Seventh Schedule (in this Constitution referred to as the \"State List\").\n(4) Parliament has power to make laws with respect to any matter for any part of the territory of India not included for the time being in Part I or Part III of the First Schedule notwithstanding that such matter is a matter enumerated in the State List.", "debated": ["1949-06-13"]}, "248": {"url": "https://www.constitutionofindia.net/articles/article-248-residuary-powers-of-legislation/", "draft": "223", "draftText": "(1) Parliament has exclusive power to make any law with respect to any matter not enumerated in the Concurrent List or State List.\n(2) Such power shall include the power of making any law imposing a tax not mentioned in either of those Lists.", "debated": ["1949-06-13"]}, "253": {"url": "https://www.constitutionofindia.net/articles/article-253-legislation-for-giving-effect-to-international-agreements/", "draft": "230", "draftText": "Notwithstanding anything in the foregoing provisions of this Chapter, Parliament has power to make any law for any State or part thereof for implementing any treaty, agreement or convention with any other country or countries.", "debated": ["1949-06-13", "1949-10-14"], "adopted": "1949-10-14"}, "255": {"url": "https://www.constitutionofindia.net/articles/article-255-requirements-as-to-recommendations-and-previous-sanctions-to-be-regarded-as-matters-of-procedure-only/", "draft": "232", "draftText": "No Act of Parliament or of a Legislature of a State for the time being specified in Part I of the First Schedule and no provision in any such Act shall be invalid by reason only that some recommendation required by this Constitution was not given, if assent to that Act was given-\n(a) Where the recommendation required was that of the Governor, either by the Governor or by the President;\n(b) Where the recommendation required was that of the President, by the President.", "debated": ["1949-06-13"]}, "263": {"url": "https://www.constitutionofindia.net/articles/article-263-provisions-with-respect-to-an-inter-state-council/", "draft": "246", "draftText": "If at any time it appears to the President that the public interests would be served by the establishment of a Council charged with the duty of-\n(a) Inquiring into and advising upon disputes which may have arisen between States;\n(b) Investigating and discussing subjects in which some or all of the States, or the Union and one or more of the States have a common interest; or\n(c) Making recommendations upon any such subject and, in particular, recommendations for the better co-ordination of policy and action with respect to that subject, it shall be lawful for the President by order to establish such a Council and to define the nature of the duties to be performed by it and its organisation and procedure."}, "249": {"url": "https://www.constitutionofindia.net/articles/article-249-power-of-parliament-to-legislate-with-respect-to-a-matter-in-the-state-list-in-the-national-interest/", "draft": "226", "draftText": "Notwithstanding anything in the foregoing provisions of this Chapter, if the Council of States has declared by resolution supported by not less than two-thirds of the members present and voting that it is necessary or expedient in the national interest that Parliament should make laws with respect to any matter enumerated in the State List specified in the resolution, it shall be lawful for Parliament to make laws for the whole or any part of the territory of India with respect to that matter."}, "252": {"url": "https://www.constitutionofindia.net/articles/article-252-power-of-parliament-to-legislate-for-two-or-more-states-by-consent-and-adoption-of-such-legislation-by-any-other-state/", "draft": "229", "draftText": "(1) If it appears to the Legislature or Legislatures of one or more States to be desirable that any of the matters with respect to which Parliament has no power to make laws for the State or States except as provided in articles 226 and 227 of this Constitution should be regulated in such State or States by Parliament by law, and a resolution or resolutions to that effect is or are passed by the House or, where there are two Houses, by both the Houses of the Legislature of the State or of each of the States, it shall be lawful for Parliament to pass an Act for regulating that matter accordingly, and any Act so passed shall apply to such State or States and to any other State by which it is adopted afterwards by resolution passed in that behalf by the House or, where there are two Houses, by each of the Houses of the Legislature of that State.\n(2) Any Act so passed by Parliament may be amended or repealed by an Act of Parliament passed or adopted in like manner but shall not, as respects any State to which it applies, be amended or repealed by an Act of the Legislature of that State.", "debated": ["1949-06-13"], "adopted": "1949-06-13"}, "254": {"url": "https://www.constitutionofindia.net/articles/article-254-inconsistency-between-laws-made-by-parliament-and-laws-made-by-the-legislatures-of-states/", "draft": "231", "draftText": "(1) If any provision of a law made by the Legislature of a State is repugnant to any provision of a law made by Parliament which Parliament is competent to enact, or to any provision of any existing law regarding a matter with respect to which Parliament has power to make laws, then, subject to the provisions of clause (2) of this article, the law made by Parliament, whether passed before or after the law made by the Legislature of such State or, as the case may be, the existing law shall prevail and the law made by the Legislature of the State shall, to the extent of the repugnancy, be void.\n(2) Where a law made by the Legislature of a State for the time being specified in Part I of the First Schedule with respect to one of the matters enumerated in the Concurrent List contains any provision repugnant to the provisions of an earlier law made by Parliament or any existing law with respect to that matter, then the law so made by the Legislature of such State shall, if it has been reserved for the consideration of the President and has received his assent, prevail:\nProvided that nothing in this clause shall prevent Parliament from enacting at any time any law with respect to the same matter including a law adding to, amending, varying or repealing the law so made by the Legislature of the State.", "debated": ["1949-06-13"], "adopted": "1949-06-13"}, "257": {"url": "https://www.constitutionofindia.net/articles/article-257-control-of-the-union-over-states-in-certain-cases/", "draft": "234", "draftText": "(1) The executive power of every State shall be so exercised as not to impede or prejudice the exercise of the executive power of the Union, and the executive power of the Union shall extend to the giving of such directions to a State as may appear to the Government of India to be necessary for that purpose.\n(2) The executive power of the Union shall also extend to the giving of directions to a State as to the construction and maintenance of means of communication declared in the direction to be of national or military importance:\nProvided that nothing in this clause shall be taken as restricting the power of Parliament to declare highways or waterways to be national highways or national waterways or the power of the Union with respect to the highways or waterways so declared or the power of the Union to construct and maintain means of communication as part of its functions with respect to naval, military and air force works.", "debated": ["1949-06-13", "1949-09-09"], "adopted": "1949-09-09"}, "258": {"url": "https://www.constitutionofindia.net/articles/article-258-power-of-the-union-to-confer-powers-etc-on-states-in-certain-cases/", "draft": "235", "draftText": "(1) Notwithstanding anything in this Constitution, the President may with the consent of the Government of a State, entrust either conditionally or unconditionally to that Government or to its officers functions in relation to any matter to which the executive power of the Union extends.\n(2) A law made by Parliament which applies in any State may, notwithstanding that it relates to a matter with respect to which the Legislature of the State has no power to make laws, confer powers and impose duties, or authorise the conferring of powers and the imposition of duties, upon the State or officers and authorities thereof.\n(3) Where by virtue of this article powers and duties have been conferred or imposed upon a State or officers or authorities thereof, there shall be paid by the Government of India to the State such sum as may be agreed or, in default of agreement, as may be determined by an arbitrator appointed by the Chief Justice of India in respect of any extra costs of administration incurred by the State in connection with the exercise of those powers and duties.", "debated": ["1949-06-13"], "adopted": "1949-06-13"}, "260": {"url": "https://www.constitutionofindia.net/articles/article-260-jurisdiction-of-the-union-in-relation-to-territories-outside-india/", "draft": "236", "draftText": "(1) The Government of India may by agreement with any State for the time being specified in Part III of the First Schedule, but subject to the provisions of this Constitution in regard to the relationship between the Union and such State, undertake any executive, legislative or judicial functions vested in that State.\n(2) The Government of India may also enter into such an agreement with the Government of any Indian State not specified for the time being in the First Schedule, but every such agreement shall be subject to, and governed by, the law relating to the exercise of foreign jurisdiction for the time being in force.\nExplanation.-In this clause, the expression \"Indian State\" means any territory, not being part of the territory of India which the President recognises as being such a State.\n(3) If an agreement entered into with any State under clause (1) of this article provides for any matter with respect to which provision has been already made in an agreement entered into with such a State under article 237 of this Constitution by the Government of any State for the time being specified in Part I of the First Schedule, then the latter agreement shall, in so far as it provides for such matter, be deemed to be revoked and of no effect on and from the date of conclusion of the former agreement.\n(4) On an agreement under clause (1) of this article being concluded between the Union and a State for the time being specified in Part III of the First Schedule-\n(a) The executive power of the Union shall extend to any matter specified in that behalf in such agreement;\n(b) Parliament shall have power to make laws with respect to any matter specified in that behalf in such agreement; and\n(c) The Supreme Court of India shall, subject to the provisions of clause (2) of article 114 of this Constitution, have jurisdiction with respect to any matter specified in that behalf in such agreement.", "debated": ["1949-06-13", "1949-10-13"], "adopted": "1949-10-13"}, "261": {"url": "https://www.constitutionofindia.net/articles/article-261-public-acts-records-and-judicial-proceedings/", "draft": "238", "draftText": "(1) Full faith and credit shall be given throughout the territory of India to public acts, records and judicial proceedings of the Union and of every State.\n(2) The manner in which and the conditions under which the acts, records and proceedings referred to in clause (1) of this article shall be proved and the effect thereof determined shall be as provided by law.\n(3) Final judgments or orders delivered or passed by civil courts in any part of the territory of India shall be capable of execution anywhere within that territory according to law:\nProvided that the provisions of clauses (1) and (3) of this article shall not apply to public acts, records and judicial proceedings of, and the final judgment or order delivered or passed by civil courts in, any State for the time being specified in Part III of the First Schedule unless Parliament has, under the terms of any agreement entered into in that behalf by such State with the Union, power to make laws with respect to the matters enumerated in entries 2, 4 and 5 of the Concurrent List.", "debated": ["1949-06-13"], "adopted": "1949-06-13"}, "262": {"url": "https://www.constitutionofindia.net/articles/article-262-adjudication-of-disputes-relating-to-waters-of-inter-state-rivers-or-river-valleys/", "debated": ["1949-09-09"], "adopted": "1949-09-09", "addedLater": true}, "264": {"url": "https://www.constitutionofindia.net/articles/article-264-interpretation/", "draft": "247", "draftText": "In this Part, unless the context otherwise requires,-\n(a) \"Finance Commission\" means a Finance Commission constituted under article 260 of this Constitution;\n(b) \"State\" does not include a State for the time being specified in Part II of the First Schedule;\n(c) References to States for the time being specified in Part II of the First Schedule shall include references to any territory specified in Part IV of the First Schedule and any other territory comprised within the territory of India but not specified in that Schedule."}, "265": {"url": "https://www.constitutionofindia.net/articles/article-265-taxes-not-to-be-imposed-save-by-authority-of-law/", "draft": "248", "draftText": "Subject to the following provisions of this Chapter with respect to the assignment of the whole or part of the net proceeds of certain taxes and duties to States, the expression \"revenues of India\" includes all revenues and public moneys raised or received by the 'Government of India and the expression \"revenues of the State\" includes all revenues and public moneys raised or received by the Government of a State.", "debated": ["1949-08-04"], "adopted": "1949-08-04"}, "266": {"url": "https://www.constitutionofindia.net/articles/article-266-consolidated-funds-and-public-accounts-of-india-and-of-the-states/", "adopted": "1949-08-04"}, "267": {"url": "https://www.constitutionofindia.net/articles/article-267-contingency-fund/", "debated": ["1949-08-04", "1949-10-13"]}, "268": {"url": "https://www.constitutionofindia.net/articles/article-268-duties-levied-by-the-union-but-collected-and-appropriated-by-the-states/", "draft": "249", "draftText": "(1) Such stamp duties and such duties of excise on medicinal and toilet preparations as are mentioned in the Union List shall be levied by the Government of India but shall be collected-\n(a) In the case where such duties are leviable within any State for the time being specified in Part II of the First Schedule, by the Government of India, and\n(b) In other cases, by the States within which such duties are respectively leviable.\n(2) The proceeds in any financial year of any such duty leviable in that year within any State shall not form part of the revenues of India, but shall be assigned to that State.", "debated": ["1949-08-04", "1949-08-05"], "adopted": "1949-08-05"}, "268A": {"url": "https://www.constitutionofindia.net/articles/article-268a-service-tax-levied-by-union-and-collected-and-appropriated-by-the-union-and-the-states/"}, "269": {"url": "https://www.constitutionofindia.net/articles/article-269-taxes-levied-and-collected-by-the-union-but-assigned-to-the-states/", "draft": "250", "draftText": "(1) The following duties and taxes shall be levied and collected by the Government of India but shall be assigned to the States in the manner provided in clause (2) of this article, namely:-\n(a) Duties in respect of succession to property other than agricultural land;\n(b) Estate duty in respect of property other than agricultural land;\n(c) Terminal taxes on goods or passengers carried by railway or air;\n(d) Taxes on railway fares and freights.\n(2) The net proceeds in any financial year of any such duty or tax, except in so far as those proceeds represent proceeds attributable to States for the time being specified in Part II of the First Schedule, shall not form part of the revenues of India, but shall be assigned to the States within which that duty or tax is leviable in that year, and shall be distributed among those States in accordance with such principles of distribution as may be formulated by Parliament by law.", "debated": ["1949-08-05", "1949-08-19", "1949-09-09"]}, "269A": {"url": "https://www.constitutionofindia.net/articles/article-269a-levy-and-collection-of-goods-and-services-tax-in-course-of-inter-state-trade-or-commerce/"}, "270": {"url": "https://www.constitutionofindia.net/articles/article-270-taxes-levied-and-distributed-between-the-union-and-the-states/", "draft": "251", "draftText": "(1) Taxes on income other than agricultural income shall be levied and collected by the Government of India and distributed between the Union and the States in the manner provided in clause (2) of this article.\n(2) Such percentage, as may be prescribed, of the net proceeds in any financial year of any such tax, except in so far as those proceeds represent proceeds attributable to States for the time being specified in Part II of the First Schedule or the taxes payable in respect of Union emoluments, shall not form part of the revenues of India, but shall be assigned to the States within which that tax is leviable in that year, and shall be distributed among those States in such manner and from such time as may be prescribed.\n(3) For the purposes of clause (2) of this article, in each financial year such percentage as may be prescribed of so much of the net proceeds of taxes on income as does not represent the net proceeds of taxes payable in respect of Union emoluments shall be deemed to represent proceeds attributable to States for the time being specified in Part II of the First Schedule.\n(4) In this article-\n(a) \"Taxes on income\" includes any sum levied by the Government of India in lieu of any tax on income as referred to in clause (a) of the proviso to article 266 of this Constitution but does not include a corporation tax;\n(b) \"Prescribed\" means-\n(i) Until a Finance Commission has been constituted, prescribed by the President by order, and\n(ii) After a Finance Commission has been constituted, prescribed by the President by order after considering the recommendations of the Finance Commission.\n(c) \"Union emoluments\" includes all emoluments and pensions payable out of the revenues of India in respect of which income-tax is chargeable.", "debated": ["1949-08-05"], "adopted": "1949-08-05"}, "271": {"url": "https://www.constitutionofindia.net/articles/article-271-surcharge-on-certain-duties-and-taxes-for-purposes-of-the-union/", "draft": "252", "draftText": "Notwithstanding anything contained in articles 250 and 251 of this Constitution, Parliament may at any time increase any of the duties or taxes referred to in those articles by a surcharge for purposes of the Union and the whole proceeds of any such surcharge shall form part of the revenues of India.", "debated": ["1949-08-05"], "adopted": "1949-08-05"}, "272": {"url": "https://www.constitutionofindia.net/articles/article-272-taxes-which-are-levied-and-collected-by-the-union-and-may-be-distributed-between-the-union-and-the-states/", "draft": "253", "draftText": "(1) No duties on salt shall be levied by the Union.\n(2) Union duties of excise other than such duties of excise on medicinal and toilet preparations as are mentioned in the Union List shall be levied and collected by the Government of India, but, if Parliament by law so provides, there shall be paid out of the revenues of India to the States to which the law imposing the duty extends, sums equivalent to the whole or any part of the net proceeds of that duty, and those sums shall be distributed among those States in accordance with such principles of distribution as may be formulated by such law."}, "273": {"url": "https://www.constitutionofindia.net/articles/article-273-grants-in-lieu-of-export-duty-on-jute-and-jute-products/", "draft": "254", "draftText": "Notwithstanding anything in article 253 of this Constitution, such proportion, as Parliament may by law determine, of the net proceeds in each year of any export duty on jute or jute-products shall not form part of the revenues of India, but shall be assigned to the States in which jute is grown in accordance with such principles of distribution as may be formulated by such law:\nProvided that until Parliament so determine, there shall be assigned to those States out of the net proceeds of the duty in each year such part thereof and in such proportions as may have been fixed in that behalf by any order made under the Government of India Act, 1935, and in force immediately before the commencement of this Constitution.", "debated": ["1949-08-08"], "adopted": "1949-08-08"}, "274": {"url": "https://www.constitutionofindia.net/articles/article-274-prior-recommendation-of-president-required-to-bills-affecting-taxation-in-which-states-are-interested/", "debated": ["1949-08-08"], "adopted": "1949-08-08", "draft": "254A"}, "275": {"url": "https://www.constitutionofindia.net/articles/article-275-grants-from-the-union-to-certain-states/", "draft": "255", "draftText": "Such sums, as Parliament may by law provide, shall be charged on the revenues of India in each year as grants-in-aid of the revenues of such States as Parliament may determine to be in need of assistance, and different sums may be fixed for different States:\nProvided that there shall be paid out of the revenues of India as grants-in-aid of the revenues of a State for the time being specified in Part I of the First Schedule such capital and recurring sums as may be necessary to enable that State to meet the costs of such schemes of development as may be undertaken by the State with the approval of the Government of India for the purpose of promoting the welfare of the scheduled tribes in that State or raising the level of administration of the scheduled areas in that State to that of the administration of the rest of the areas of that State:\nProvided further that there shall be paid out of the revenues of India as grants-in-aid of the revenues of the State of Assam sums, capital and recurring, equivalent to-\n(a) The average excess of expenditure over the revenues during the three years immediately preceding the commencement of this Constitution in respect of the administration of the tribal areas specified in Part I of the table appended to paragraph 19 of the sixth Schedule; and\n(b) The costs of such schemes of development as may be undertaken by that State with the approval of the Government of India for the purpose of raising the level of administration of the said areas to that of the administration of the rest of the areas of that State.", "debated": ["1949-08-08", "1949-08-09"], "adopted": "1949-08-09"}, "276": {"url": "https://www.constitutionofindia.net/articles/article-276-taxes-on-professions-trades-callings-and-employments/", "draft": "256", "draftText": "(1) Notwithstanding anything in article 217 of this Constitution but subject to the provisions of clauses (2) and (3) of this article, the Legislature of a State shall have power to make laws with respect to taxes on professions, trades, callings and employments for the benefit of the State or of a municipality, district board, local board or other local authority therein.\n(2) The total amount payable in respect of any one person to the State or to any one municipality, district board, local board or other local authority in the State by way of taxes on professions, trades, callings and employments shall not exceed two hundred and fifty rupees per annum:\nProvided that, if in the financial year immediately preceding the commencement of this Constitution there was in force in any State or any such municipality, board or authority, a tax on professions, trades, callings or employments, the rate, or the maximum rate, of which exceeded two hundred and fifty rupees per annum, such tax may continue to be levied until provision to the contrary is made by Parliament by law, and any law so made by Parliament may be made either generally or in relation to any specified States, municipalities, boards or authorities.\n(3) The power of the Legislature of a State to make laws as aforesaid with respect to taxes on professions, trades, callings and employments shall not be construed as limiting in any way the power of Parliament to make laws with respect to taxes on income accruing from or arising out of professions, trades, callings and employments.", "debated": ["1949-08-09"], "adopted": "1949-08-09"}, "277": {"url": "https://www.constitutionofindia.net/articles/article-277-savings/", "draft": "257", "draftText": "Any taxes, duties, cesses or fees which immediately before the commencement of this Constitution, were being lawfully levied by the Government of any State or by any municipality or other local authority or body for the purposes of the State, municipality, district or other local area may, notwithstanding that those taxes, duties, cesses or fees are mentioned in the Union List, continue to be levied and to be applied to the same purposes until provision to the contrary is made by Parliament.", "debated": ["1949-08-09"]}, "278": {"url": "https://www.constitutionofindia.net/articles/article-278-agreement-with-states-in-part-b-of-the-first-schedule-with-regard-to-certain-financial-matters/", "draft": "258", "draftText": "(1) Notwithstanding anything contained in this Chapter, the Union may, subject to the provisions of clause (2) of this article, enter into an agreement with a State for the time being specified in Part III of the First Schedule with respect to the levy and collection of any tax or duty leviable by the Government of India in such State and for the distribution of the proceeds thereof otherwise than in accordance with the provisions of this Chapter and, when an agreement is so entered into, the provisions of this Chapter shall in relation to such State have effect subject to the terms of such agreement.\n(2) An agreement entered into under clause (1) of this article shall continue in force for a period not exceeding ten years from the commencement of this Constitution:\nProvided that the President may at any time after the expiration of five years from such commencement terminate or modify any such agreement if after consideration of the report of the Finance Commission he thinks it necessary to do so."}, "279": {"url": "https://www.constitutionofindia.net/articles/article-279-calculation-of-net-proceeds-etc/", "draft": "259", "draftText": "(1) In the foregoing provisions of this Chapter, \"net proceeds\" means in relation to any tax or duty the proceeds thereof reduced by the cost of collection, and for the purposes of those provisions the net proceeds of any tax or duty, or of any part of any tax or duty, in or attributable to any area shall be ascertained and certified by the Auditor-General of India, whose certificate shall be final.\n(2) Subject as aforesaid, and to any other express provision in this Chapter, a law made by Parliament or an order of the President may, in any case where under this Part of this Constitution the proceeds of any duty or tax are, or may be, assigned to any State, provide for the manner in which the proceeds are to be calculated, for the time from or at which and the manner in which any payments are to be made, for the making of adjustments between one financial year and another, and for any other incidental or ancillary matters.", "debated": ["1949-08-09"]}, "279A": {"url": "https://www.constitutionofindia.net/articles/article-279a-goods-and-services-tax-council/", "notDebated": true}, "280": {"url": "https://www.constitutionofindia.net/articles/article-280-finance-commission/", "draft": "260", "draftText": "(1) The President shall, at the expiration of five years from the commencement of this Constitution and thereafter at the expiration of every fifth year or at such other time as the President considers necessary, by order constitute a Finance Commission which shall consist of a Chairman and four other members to be appointed by the President.\n(2) Parliament may, by law, determine the qualifications which shall be requisite for appointment as members of the Commission and the manner in which they shall be selected.\n(3) It shall be the duty of the Commission to make recommendations to the President as to-\n(a) The distribution between the Union and the States of the net proceeds of taxes which are to be, or may be, divided between them under this Chapter and the allocation between the States of the respective shares of such proceeds;\n(b) The principles which should govern the grants-in-aid to the States out of the revenues of India;\n(c) The continuance or modification of the terms of any agreement entered into by the Union with any State for the time being specified in Part III of the First Schedule as respects the levy, collection and distribution of any tax or duty leviable by the Government of India in such State; and\n(d) Any other matter referred to the Commission by the President in the interest of sound finance.\n(4) The Commission shall determine their procedure and shall have such powers in the performance of their functions as Parliament may by law confer on them.", "debated": ["1949-08-09", "1949-08-10"], "adopted": "1949-08-10"}, "281": {"url": "https://www.constitutionofindia.net/articles/article-281-recommendations-of-the-finance-commission/", "draft": "261", "draftText": "The President shall cause every recommendation made by the Finance Commission under the foregoing provisions of this Chapter together with an explanatory memorandum as to the action taken thereon to be laid before Parliament.", "debated": ["1949-08-10"], "adopted": "1949-08-10"}, "282": {"url": "https://www.constitutionofindia.net/articles/article-282-expenditure-defrayable-by-the-union-or-a-state-out-of-its-revenues/", "draft": "262", "draftText": "The Union or a State may make any grants for any public purpose, notwithstanding that the purpose is not one with respect to which Parliament or the Legislature of the State, as the case may be, may make laws.", "debated": ["1949-08-10"]}, "283": {"url": "https://www.constitutionofindia.net/articles/article-283-custody-etc-of-consolidated-funds-contingency-funds-and-moneys-credited-to-the-public-accounts/", "draft": "263", "draftText": "(1) Rules may be made by the President and by the Governor of a State for the purpose of securing that all moneys received on account of the revenues of India or of the State, as the case may be, shall, with such exceptions, if any, as may be specified in the rules, be paid into the public accounts of India or of the State, and the rules so made may pre- scribe, or authorise some person to prescribe, the procedure to be followed in respect of the payment of moneys into the said account, the withdrawal of moneys thereform, the custody of moneys therein and any other matter connected with or ancillary to the matters aforesaid.\n(2) Notwithstanding anything in this article, Parliament may by law regulate the custody of moneys received on account of the revenues of India, their payment into the public account of India and the withdrawal of moneys from such account, and the Legislature of a State may by law regulate the custody of all moneys received on account of the revenues of the State, their payment into the public account of the State and the withdrawal of moneys from such account, and any rules made under this article shall have effect subject to the provisions of any such law.", "debated": ["1949-08-10", "1949-09-09", "1949-10-13"], "adopted": "1949-10-13"}, "284": {"url": "https://www.constitutionofindia.net/articles/article-284-custody-of-suitors-deposits-and-other-moneys-received-by-public-servants-and-courts/", "addedLater": true}, "285": {"url": "https://www.constitutionofindia.net/articles/article-285-exemption-of-property-of-the-union-from-state-taxation/", "draft": "264", "draftText": "The property of the Union shall, save in so far as Parliament may by law otherwise provide, be exempt from all taxes imposed by or by any authority within a State:\nProvided that until Parliament, by law, otherwise provides, any property of the Union which was immediately before the commencement of this Constitution liable or treated as liable to any such tax shall, so long as that tax continues, continue to be liable or to be treated as liable thereto.", "debated": ["1949-09-09"], "adopted": "1949-09-09"}, "286": {"url": "https://www.constitutionofindia.net/articles/article-286-restrictions-as-to-imposition-of-tax-on-the-sale-or-purchase-of-goods/", "debated": ["1949-10-16"], "adopted": "1949-10-16", "addedLater": true}, "287": {"url": "https://www.constitutionofindia.net/articles/article-287-exemption-from-taxes-on-electricity/", "draft": "265", "draftText": "Save in so far as Parliament may, by law, otherwise provide, no law of a State shall impose, or authorise the imposition of, a tax on the consumption or sale of electricity (whether produced by Government or other person) which is-\n(a) Consumed by the Government of India, or sold to the Government of India for consumption by that Government; or\n(b) Consumed in the construction, maintenance or operation of a Union railway by the Government or a railway company operating that railway or sold to that Government or any such railway company for consumption in the construction, maintenance or operation of a Union railway,\nand any such law imposing, or authorising the imposition of, a tax on the sale of electricity shall secure that the price of electricity sold to the Government of India for consumption by that Government, or to any such railway company as aforesaid for consumption in the construction, maintenance or operation of a Union railway, shall be less by the amount of the tax than the price charged to other consumers of a substantial quantity of electricity.", "debated": ["1949-09-09"], "adopted": "1949-09-09"}, "288": {"url": "https://www.constitutionofindia.net/articles/article-288-exemption-from-taxation-by-states-in-respect-of-water-or-electricity-in-certain-cases/", "debated": ["1949-09-09"], "adopted": "1949-09-09", "addedLater": true}, "289": {"url": "https://www.constitutionofindia.net/articles/article-289-exemption-of-property-and-income-of-a-state-from-union-taxation/", "draft": "266", "draftText": "Subject as hereinafter provided, the Government of a State shall not be liable to Union taxation in respect of lands or buildings situate within the territory of India, or income accruing, arising or received within such territory:\nProvided that-\n(a) Where a trade or business of any kind is carried on by or on behalf of the Government of a State, nothing in this article shall exempt that Government from any Union tax or the levy of a sum in lieu of such tax in respect of that trade or business or any operations connected therewith, or any income arising in connection therewith, or any property occupied for the purposes thereof;\n(b) Nothing in this article shall exempt the Ruler of any State for the time being specified in Part III of the First Schedule from any Union tax in respect of lands, buildings or income being his personal property or personal income.\nExplanation.-For the purposes of this article, any operations incidental to the ordinary functions of the Government of a State, such as, the sale of the forest produce of any forest under the control of the Government of a State or of any article produced in any jail within a State, shall not be deemed to be a trade or business carried on by or on behalf of the Government of the State.", "debated": ["1949-09-09"], "adopted": "1949-09-09"}, "290": {"url": "https://www.constitutionofindia.net/articles/article-290-adjustment-in-respect-of-certain-expenses-and-pensions/", "draft": "267", "draftText": "Where under the provisions of this Constitution the expenses of any court or Commission, or pensions payable to or in respect of a person who has served before the commencement of this Constitution under the Crown in India, are charged on the revenues of India or the revenues of a State for the time being specified in Part I of the First Schedule, then if-\n(a) In the case of a charge on the revenues of India, the court or Commission serves any of the separate needs of a State so specified, or the person has served wholly or in part in connection with the affairs of such a State; or\n(b) In the case of a charge on the revenues of a State so specified, the court or Commission serves any of the separate needs of the Union or another State so specified, or the person has served wholly or in part in connection with the affairs of the Union or another such State,\nthere shall be charged on and paid out of the revenues of the State or, as the case may be, the revenues of India or of the other State, such contribution in respect of expenses or pensions as may be agreed, or as may in default of agreement be determined by an arbitrator to be appointed by the Chief Justice of India.", "debated": ["1949-08-10"]}, "290A": {"url": "https://www.constitutionofindia.net/articles/article-290a-annual-payment-to-certain-devaswom-funds/"}, "291": {"url": "https://www.constitutionofindia.net/articles/article-291-privy-purse-sums-of-rulers/"}, "292": {"url": "https://www.constitutionofindia.net/articles/article-292-borrowing-by-the-government-of-india/", "draft": "268", "draftText": "The executive power of the Union extends to borrowing upon the security of the revenues of India within such limits, if any, as may from time to time be fixed by Parliament by law and to the giving of guarantees within such limits, if any, as may be so fixed.", "debated": ["1949-08-10"], "adopted": "1949-08-10"}, "293": {"url": "https://www.constitutionofindia.net/articles/article-293-borrowing-by-state/", "draft": "269", "draftText": "(1) Subject to the provisions of this article, the executive power of a State for the time being specified in Part I of the First Schedule extends to borrowing within the territory of India upon the security of the revenues of the State within such limits, if any, as may from time to time be fixed by the Legislature of such State by law and to the giving of guarantees within such limits, if any, as may be so fixed.\n(2) The Government of India may, subject to such conditions, if any, as it may think fit to impose, make loans to States for the time being specified in Part I or Part III of the First Schedule or so long as any limits fixed under the last preceding article are not exceeded, give guarantees in respect of loans raised by any such State and any sums required for the purpose of making such loans shall be charged on the revenues of India.\n(3) A State for the time being specified in Part I or Part III of the First Schedule may not without the consent of the Government of India raise any loan if there is still outstanding any part of a loan which has been made to the State by the Government of India or its predecessor Government or in respect of which a guarantee has been given by the Government of India or by its predecessor Government. A consent under this clause may be granted subject to such conditions, if any, as the Government of India may think fit to impose.", "debated": ["1949-08-10"]}, "294": {"url": "https://www.constitutionofindia.net/articles/article-294-succession-to-property-assets-rights-liabilities-and-obligations-in-certain-cases/", "draft": "284", "draftText": "As from the commencement of this Constitution, the Government of India and the Government of each State for the time being specified in Part I of the First Schedule shall respectively be the successors of the Government of the Dominion of India and of the corresponding Governors' Provinces as regards all property, assets and liabilities subject to any adjustment made or to be made by reason of the creation before the commencement of this Constitution of the Dominion of Pakistan or of the Provinces of West Bengal, East Bengal, West Punjab and East Punjab.", "debated": ["1949-06-15", "1949-10-13"]}, "295": {"url": "https://www.constitutionofindia.net/articles/article-295-succession-to-property-assets-rights-liabilities-and-obligations-in-other-cases/", "notDebated": true, "addedLater": true}, "296": {"url": "https://www.constitutionofindia.net/articles/article-296-property-accruing-by-escheat-or-lapse-or-as-bona-vacantia/", "draft": "271", "draftText": "Subject as hereinafter provided, any property in the territory of India except the States for the time being specified in Part III of the First Schedule which, if this Constitution had not come into operation, would have accrued to His Majesty by escheat or lapse, or as bona vacantia for want of a rightful owner, shall, if it is property situate in a State for the time being specified in Part I of the First Schedule, vest in such State for the purposes of the Government of that State, and shall, in any other case, vest in the Union for the purposes of the Government of India. Provided that any property which at the date when it would have so accrued to His Majesty was in the possession or under the control of the Government of India or the Government of a State for the time being specified in Part I of the First Schedule shall, according as the purposes for which it was then used or held were purposes of the Union or of a State so specified, vest in the Union for the purposes of the Government of India or in the State for the purposes of the Government of that State.", "debated": ["1949-06-15"]}, "297": {"url": "https://www.constitutionofindia.net/articles/article-297-things-of-value-within-territorial-waters-or-continental-shelf-and-resources-of-the-exclusive-economic-zone-to-vest-in-the-union/", "addedLater": true}, "298": {"url": "https://www.constitutionofindia.net/articles/article-298-power-to-carry-on-trade-etc/", "draft": "272", "draftText": "(1) The executive power of the Union and of each State for the time being specified in Part I of the First Schedule shall extend, subject to any Act of the appropriate Legislature, to the grant, sale, disposition or mortgage of any property held for the purposes of the Union or of such State, as the case may be, and to the purchase or acquisition of property for those purposes respectively, and to the making of contracts.\n(2) All property acquired for the purposes of the Union or of a State for the time being specified in Part I of the First Schedule shall vest in the Union or any such State, as the case may be.", "debated": ["1949-06-15"]}, "299": {"url": "https://www.constitutionofindia.net/articles/article-299-contracts/", "draft": "273", "draftText": "(1) All contracts made in the exercise of the executive power of the Union or of a State for the time being specified in Part I of the First Schedule shall be expressed to be made by the President, or by the Governor of the State, as the case may be, and all such contracts and all assurances of property made in the exercise of that power shall be executed on behalf of the President or the Governor by such persons and in such manner as he may direct or authorise.\n(2) Neither the President, nor the Governor of a State, shall be personally liable in respect of any contract or assurance made or executed for the purposes of this Constitution, or for the purposes of any enactment relating to the Government of India heretofore in force, nor shall any person making or executing such contract or assurance on behalf of any of them be personally liable in respect thereof.", "debated": ["1949-06-15"], "adopted": "1949-06-15"}, "300": {"url": "https://www.constitutionofindia.net/articles/article-300-suits-and-proceedings/", "draft": "274", "draftText": "(1) The Government of India may sue or be sued by the name of the Government of India and the Government of a State for the time being specified in Part I of the First Schedule may sue or be sued by the name of the State and may, subject to any provisions which may be made by Act of Parliament or by the Legislature of such State, enacted by virtue of powers conferred by this Constitution, sue or be sued in relation to their respective affairs in the like cases as the Dominion of India and the corresponding Provinces might have sued or been sued if this Constitution had not been enacted.\n(2) If at the date of commencement of this Constitution-\n(a) Any legal proceedings are pending to which the Dominion of India is a party, the Government of India shall be deemed to be substituted for the Dominion in those proceedings; and\n(b) Any legal proceedings are pending to which a Province is a Party, the corresponding State shall be deemed to be substituted for the Province in those proceedings.", "debated": ["1949-06-15"]}, "300A": {"url": "https://www.constitutionofindia.net/articles/article-300a-persons-not-to-be-deprived-of-property-save-by-authority-of-law/", "notDebated": true}, "302": {"url": "https://www.constitutionofindia.net/articles/article-302-power-of-parliament-to-impose-restrictions-on-trade-commerce-and-intercourse/", "debated": ["1949-09-08"], "addedLater": true}, "303": {"url": "https://www.constitutionofindia.net/articles/article-303-restrictions-on-the-legislative-powers-of-the-union-and-of-the-states-with-regard-to-trade-and-commerce/", "debated": ["1949-09-08"], "adopted": "1949-09-08", "addedLater": true}, "304": {"url": "https://www.constitutionofindia.net/articles/article-304-restrictions-on-trade-commerce-and-intercourse-among-states/", "addedLater": true}, "305": {"url": "https://www.constitutionofindia.net/articles/article-305-saving-of-existing-laws-and-laws-providing-for-state-monopolies/", "debated": ["1949-10-13"], "adopted": "1949-10-13", "addedLater": true}, "307": {"url": "https://www.constitutionofindia.net/articles/article-307-appointment-of-authority-for-carrying-out-the-purposes-of-articles-301-to-304/", "addedLater": true}, "308": {"url": "https://www.constitutionofindia.net/articles/article-308-interpretation/", "draft": "281", "draftText": "In this Part, unless the context otherwise requires, the expression \"State\" means a State for the time being specified in Part I of the First Schedule.", "debated": ["1949-09-07"]}, "309": {"url": "https://www.constitutionofindia.net/articles/article-309-recruitment-and-conditions-of-service-of-persons-serving-the-union-or-a-state/", "draft": "282", "draftText": "(1) Subject to the provisions of clause (2) of this article, Acts of the appropriate Legislature may regulate the recruitment and the conditions of service of persons appointed to public services, and to posts in connection with the affairs, of the Union or any State.\n(2) No person who is a member of any civil service or holds any civil post in connection with the affairs of the Government of India or the Government of a State shall be dismissed, removed or reduced in rank until he has been given a reasonable opportunity of showing cause against the action proposed to be taken in regard to him:\nProvided that this clause shall not apply-\n(a) Where a person is dismissed, removed, or reduced in rank on the ground of conduct which has led to his conviction on a criminal charge; or\n(b) Where an authority empowered to dismiss a person or remove him or reduce him in rank is satisfied that for some reason to be recorded by that authority in writing it is not reasonably practicable to give that person an opportunity of showing cause.", "debated": ["1949-09-07"]}, "310": {"url": "https://www.constitutionofindia.net/articles/article-310-tenure-of-office-of-persons-serving-the-union-or-a-state/", "addedLater": true}, "311": {"url": "https://www.constitutionofindia.net/articles/article-311-dismissal-removal-or-reduction-in-rank-of-persons-employed-in-civil-capacities-under-the-union-or-a-state/", "debated": ["1949-09-08"], "adopted": "1949-09-08", "addedLater": true}, "312": {"url": "https://www.constitutionofindia.net/articles/article-312-all-india-services/", "debated": ["1949-09-08"]}, "312A": {"url": "https://www.constitutionofindia.net/articles/article-312a-power-of-parliament-to-vary-or-revoke-conditions-of-service-of-officers-of-certain-services/", "notDebated": true}, "313": {"url": "https://www.constitutionofindia.net/articles/article-313-transitional-provisions/", "draft": "283", "draftText": "Until other provision is made in this behalf under this Constitution, any rules which were in force immediately before the commencement of this Constitution and were applicable to any public service or any post which has continued to exist after the commencement of this Constitution as a service or post under the Union or a State shall continue in force so far as consistent with the provisions of this Constitution.", "debated": ["1949-09-08"]}, "314": {"url": "https://www.constitutionofindia.net/articles/article-314-provision-for-protection-of-existing-officers-of-certain-services/"}, "315": {"url": "https://www.constitutionofindia.net/articles/article-315-public-service-commissions-for-the-union-and-for-the-states/", "draft": "284", "draftText": "(1) Subject to the provisions of this article there shall be a Public Service Commission for the Union and a Public Service Commission for each State.\n(2) Two or more States may agree-\n(a) That there shall be one Public Service Commission for that group of States; or\n(b) That the Public Service Commission for one of the States shall serve the needs of all the States; and any such agreement may contain such incidental and consequential provisions as may appear necessary or desirable for giving effect to the purposes of the agreement and shall, in the case of an agreement that there shall be one Commission for a group of States, specify by what Governor or Governors the functions which are under this Part of this Constitution to be discharged by the Governor of a State are to be discharged.\n(3) The Public Service Commission for the Union if requested so to do by the Governor of a State may, with the approval of the President, agree to serve all or any of the needs of the State.\n(4) References in this Constitution to the Union Public Service Commission or a State Public Service Commission shall, unless the context otherwise requires, be construed as references to the Commission serving the needs of the Union, or, as the case may be, the State as respects the particular matter in question.", "debated": ["1949-08-22"], "adopted": "1949-08-22"}, "316": {"url": "https://www.constitutionofindia.net/articles/article-316-appointment-and-term-of-office-of-members/", "draft": "285", "draftText": "(1) The Chairman and other members of a Public Service Commission shall be appointed, in the case of the Union Commission, by the President, and in the case of a State Commission, by the Governor of the State in his discretion:\nProvided that at least one-half of the members of every Public Service Commission shall be persons who at the dates of their respective appointments have held office for at least ten years either under the Government of India or under the Government of a State and in computing the said period of ten years any period before the commencement of this Constitution during which a person has held office under the Crown shall be included.\n(2) In the case of the Union Commission, the President and, in the case of a State Commission, the Governor of the State in his discretion may by regulations-\n(a) Determine the number of members of the Commission, their tenure of office and their conditions of service; and(b) Make provision with respect to the number of members of the staff of the Commission and their conditions of service.\n(3) On ceasing to hold office-\n(a) The Chairman of the Union Commission shall be ineligible for further employment either under the Government of India or under the Government of a State;\n(b) The Chairman of a State Commission shall be eligible for appointment as the Chairman or a member of the Union Commission or as the Chairman of another State Commission, but not for any other employment either under the Government of India or under the Government of a State;\n(c) No other member of the Union or of any State Commission shall be eligible for any other appointment either under the Government of India or the Government of a State without the approval in the case of an appointment in connection with the affairs of a State, of the Governor of the State and, in the case of any other appointment, of the President.", "debated": ["1949-08-22"]}, "317": {"url": "https://www.constitutionofindia.net/articles/article-317-removal-and-suspension-of-a-member-of-a-public-service-commission/", "notDebated": true, "addedLater": true}, "318": {"url": "https://www.constitutionofindia.net/articles/article-318-power-to-make-regulations-as-to-conditions-of-service-of-members-and-staff-of-the-commission/"}, "319": {"url": "https://www.constitutionofindia.net/articles/article-319/", "addedLater": true}, "320": {"url": "https://www.constitutionofindia.net/articles/article-320-functions-of-public-service-commissions/", "draft": "286", "draftText": "(1) It shall be the duty of the Union and the State Public Service Commissions to conduct examinations for appointments to the services of the Union and the services of the State respectively.\n(2) It shall also be the duty of the Union Public Service Commission, if requested by any two or more States so to do, to assist those States in framing and operating schemes of joint recruitment for any services for which candidates possessing special qualifications are required.\n(3) The President as respects the All India Services and also as respects other services and posts in connection with the affairs of the Union, and the Governor as respects other services and posts in connection with the affairs of a State, may make regulations specifying the matters in which either generally, or in any particular class of case or in any particular circumstances, it shall not be necessary for a Public Service Commission to be consulted, but, subject to regulations so made and to the provisions of the next succeeding clause, the Union Commission or, as the case may be, the State Commission shall be consulted-\n(a) On all matters relating to methods of recruitment to civil services and for civil posts;\n(b) On the principles to be followed in making appointments to civil services and posts and in making promotions and transfers from one service to another and on the suitability of candidates for such appointments, promotions or transfers;\n(c) On all disciplinary matters affecting a person serving under the Government of India or the Government of a State in a civil capacity, including memorials or petitions relating to such matters;\n(d) On any claim by or in respect of a person who is serving or has served under the Government of India or the Government of a State or under the Crown, in a civil capacity that any costs incurred by him in defending legal proceedings instituted against him in respect of acts done or purporting to be done in the execution of his duty should be paid out of the revenues of India or, as the case may be, the State;\n(e) On any claim for the award of a pension in respect of injuries sustained by a person while serving under the Government of India or the Government of a State or under the Crown in a civil capacity, and any question as to the amount of any such award, and it shall be the duty of a Public Service Commission to advise on any matter so referred to them and on any other matter which the President or, as the case may be, the Governor may refer to them.\n(4) Nothing in this article shall require a Public Service Commission to be consulted as respects the manner in which appointments and posts are to be allocated as between the various communities in the Union or a State.", "debated": ["1949-08-23"]}, "321": {"url": "https://www.constitutionofindia.net/articles/article-321-power-to-extend-functions-of-public-service-commissions/", "draft": "287", "draftText": "Subject to the provisions of this article, an Act made by Parliament or by the Legislature of the State may provide for the exercise of additional functions by the Union Public Service Commission, or, as the case may be, by the State Public Service Commission:\nProvided that where the Act is made by the Legislature of a State, it shall be a term of such Act that the functions conferred by it shall not be exercisable in relation to any person who is not a member of one of the services of the State except with the consent of the President.", "debated": ["1949-08-23"], "adopted": "1949-08-23"}, "322": {"url": "https://www.constitutionofindia.net/articles/article-322-expenses-of-public-service-commissions/", "draft": "288", "draftText": "The expenses of the Union or a State Public Service Commission, including any salaries, allowances and pensions payable to or in respect of the members or staff of the Commission, shall be charged on the revenues of India or, as the case may be, the State.", "debated": ["1949-08-23"]}, "323": {"url": "https://www.constitutionofindia.net/articles/article-323-reports-of-public-service-commissions/", "addedLater": true}, "323A": {"url": "https://www.constitutionofindia.net/articles/article-323a-administrative-tribunals/", "notDebated": true}, "323B": {"url": "https://www.constitutionofindia.net/articles/article-323b-tribunals-for-other-matters/", "notDebated": true}, "324": {"url": "https://www.constitutionofindia.net/articles/article-324-superintendence-direction-and-control-of-elections-to-be-vested-in-an-election-commission/", "draft": "289", "draftText": "(1) The superintendence, direction and control of all elections to Parliament and of elections to the offices of President and Vice-President held under this Constitution, including the appointment of election tribunals for the decision of doubts and disputes arising out of or in connection with the elections to Parliament, shall be vested in a Commission to be appointed by the President.\n(2) The superintendence, direction and control of all elections to the Legislature of a State for the time being specified in Part I of the First Schedule and of elections to the office of Governor of the State elections to constitute a panel for the purpose of the appointment of a Governor of the State held under this Constitution including the appointment of election tribunals for the decision of doubts and disputes arising out of or in connection with elections to the Legislature of such State shall be vested in a Commission to be appointed by the Governor of the State.", "debated": ["1949-06-15", "1949-06-16"], "adopted": "1949-06-16"}, "325": {"url": "https://www.constitutionofindia.net/articles/article-325-no-person-to-be-ineligible-for-inclusion-in-or-to-claim-to-be-included-in-a-special-electoral-roll-on-grounds-of-religion-race-caste-or-sex/", "notDebated": true}, "326": {"url": "https://www.constitutionofindia.net/articles/article-326-elections-to-the-house-of-the-people-and-to-the-legislative-assemblies-of-states-to-be-on-the-basis-of-adult-suffrage/"}, "327": {"url": "https://www.constitutionofindia.net/articles/article-327-power-of-parliament-to-make-provision-with-respect-to-elections-to-legislatures/", "draft": "290", "draftText": "Subject to the provisions of this Constitution, Parliament may, from time to time, by law, make provision with respect to all matters relating to or in connection with elections to either House of Parliament including matters necessary for securing the due constitution of the two Houses of Parliament and the delimitation of constituencies.", "debated": ["1949-06-16"]}, "328": {"url": "https://www.constitutionofindia.net/articles/article-328-power-of-legislature-of-a-state-to-make-provision-with-respect-to-elections-to-such-legislature/", "draft": "291", "draftText": "Subject to the provisions of this Constitution, the Legislature of a State for the time being specified in Part I of the First Schedule may, from time to time, by law, make provision with respect to all matters relating to or in connection with elections to the House or Houses of the Legislature of the State including matters necessary for securing the due constitution of such House or Houses and the delimitation of constituencies.", "debated": ["1949-06-16"]}, "329": {"url": "https://www.constitutionofindia.net/articles/article-329-bar-to-interference-by-courts-in-electoral-matters/", "notDebated": true}, "329A": {"url": "https://www.constitutionofindia.net/articles/article-329a-special-provision-as-to-elections-to-parliament-in-the-case-of-prime-minister-and-speaker/"}, "330": {"url": "https://www.constitutionofindia.net/articles/article-330-reservation-of-seats-for-scheduled-castes-and-scheduled-tribes-in-the-house-of-the-people/", "draft": "292", "draftText": "Seats shall be reserved in the House of the People for-\n(a) The Muslim community and the Scheduled Castes;\n(b) The scheduled tribes in every State for the time being specified in Part I of the first Schedule; and\n(c) The Indian Christian community in the States of Madras and Bombay, according to the scale prescribed in sub-clause (b) of clause (5) of article 67 of this Constitution.", "debated": ["1949-08-23", "1949-08-24"], "adopted": "1949-08-24"}, "331": {"url": "https://www.constitutionofindia.net/articles/article-331-representation-of-the-anglo-indian-community-in-the-house-of-the-people/", "draft": "293", "draftText": "Notwithstanding anything contained in article 67 of this Constitution, the President may, if he is of opinion that the Anglo-Indian community is not adequately represented in the House of the People, nominate not more than two members of the community to the House of the People.", "debated": ["1949-08-24"]}, "332": {"url": "https://www.constitutionofindia.net/articles/article-332-reservation-of-seats-for-scheduled-castes-and-scheduled-tribes-in-the-legislative-assemblies-of-the-states/", "draft": "294", "draftText": "(1) Seats shall be reserved for-\n(a) The Muslim community, the Scheduled Castes and the scheduled tribes (except the scheduled tribes in the autonomous districts of Assam) in the Legislative Assembly of every State for the time being specified in Part I of the First Schedule; and\n(b) The Indian Christian community in the Legislative Assemblies of the States of Madras and Bombay, according to the scale prescribed in clause (3) of article 149 of this Constitution.\n(2) Seats shall be reserved also for the autonomous districts in the Legislative Assembly of the State of Assam.\n(3) The number of seats reserved for any community in the Legislative Assembly of any State for the time being specified in Part I of the First Schedule shall bear, as nearly as may be, the same proportion to the total number of seats in that Assembly as the population of the community in the State bears to the total population of the State.\nExplanation.-All the Scheduled Castes in a State shall be deemed to be a single community for the purposes of this clause and so also all the scheduled tribes in a State.\n(4) The number of seats reserved for an autonomous district in the Legislative Assembly of the State of Assam shall bear to the total number of seats in that Assembly a proportion not less than the population of the district bears to the total population of the State.\n(5) The constituencies for the seats reserved for any autonomous district of the State of Assam shall not comprise any area outside that district.\n(6) No person who is not a member of a scheduled tribe of any autonomous district of the State of Assam shall be eligible for election to the Legislative Assembly of the State from any constituency of that district I [except from the constituency comprising the cantonment and municipality of Shillong.", "debated": ["1949-08-24"]}, "333": {"url": "https://www.constitutionofindia.net/articles/article-333-representation-of-the-anglo-indian-community-in-the-legislative-assemblies-of-the-states/", "draft": "295", "draftText": "Notwithstanding anything contained in article 149 of this Constitution, the Governor of a State may, if he is of opinion that the Anglo Indian community is not adequately represented in the Legislative Assembly of the State, nominate such number of members of the community to the Legislative Assembly as he considers appropriate.", "debated": ["1949-08-24"]}, "334": {"url": "https://www.constitutionofindia.net/articles/article-334-reservation-of-seats-and-special-representation-to-cease-after-certain-period/", "debated": ["1949-08-24", "1949-08-25"]}, "335": {"url": "https://www.constitutionofindia.net/articles/article-335-claims-of-scheduled-castes-and-scheduled-tribes-to-services-and-posts/", "draft": "296", "draftText": "Subject to the provisions of the next succeeding article the claims of all minority communities shall be taken into consideration, consistently with the maintenance of efficiency of administration, in the making of appointments to services and posts in connection with the affairs of the Union or of a State for the time being specified in Part I of the First Schedule.", "debated": ["1948-08-26", "1949-08-26", "1949-10-14"], "adopted": "1949-10-14"}, "336": {"url": "https://www.constitutionofindia.net/articles/article-336-special-provision-for-anglo-indian-community-in-certain-services/", "draft": "297", "draftText": "(1) During the first two years after the commencement of this Constitution, appointments of members of the Anglo-Indian community to posts in the railway, customs, postal and telegraph services of the Union shall be made on the same basis as immediately before the fifteenth day of August 1947.\nDuring every succeeding period of two years, the number of posts reserved for the members of the said community in the said services shall, as nearly as possible, be less by ten per cent than the numbers so reserved during the immediately preceding period of two years:\nProvided that at the end of ten years from the commencement of this Constitution all such reservations shall cease.\n(2) Nothing in clause (1) shall bar the appointment of members of the Anglo-Indian community to posts other than, or in addition to, those reserved for the community under that clause if such members are found qualified for appointment on merit as compared with the members of other communities.", "debated": ["1949-06-16"]}, "337": {"url": "https://www.constitutionofindia.net/articles/article-337-special-provision-with-respect-to-educational-grants-for-the-benefit-of-anglo-indian-community/", "draft": "298", "draftText": "During the first three financial years after the commencement of this Constitution, the same grants, if any, shall be made by the Union and by each State for the time being specified in Part I of the First Schedule for the benefit of the Anglo-Indian community in respect of education as were made in the financial year ending on the 31st day of March 1948. During every succeeding period of three years the grants may be less by ten per cent than those for the immediately preceding period of three years:\nProvided that at the end of ten years from the commencement of this Constitution, such grants, to the extent to which they are a special concession to the Anglo-Indian community, shall cease:\nProvided further that no educational institution shall be entitled to receive any grant under this article unless at least forty per cent of the annual admissions therein are made available to members of communities other than the Anglo-Indian community."}, "338": {"url": "https://www.constitutionofindia.net/articles/article-338-national-commission-for-scheduled-castes/", "draft": "299", "draftText": "(1) There shall be a Special Officer for minorities for the Union who shall be appointed by the President, and a Special Officer for minorities for each State for the time being specified in Part I of the First Schedule who shall be appointed by the Governor of the State.\n(2) It shall be the duty of the Special Officer for the Union to investigate all matters relating to the safeguards provided for minorities under this Constitution in connection with the affairs of the Union and to report to the President upon the working of the safeguards at such intervals as the President may direct, and the President shall cause all such reports to be laid before Parliament.\n(3) It shall be the duty of the Special Officer for a State so specified to investigate all matters relating to the safeguards provided for minorities under this Constitution in connection with the affairs of the State and to report to the Governor of the State upon the working of the safeguards at such intervals as the Governor may direct and the Governor shall cause all such reports to be laid before the Legislature of the State.", "debated": ["1949-08-26", "1949-10-14"], "adopted": "1949-10-14"}, "338B": {"url": "https://www.constitutionofindia.net/articles/article-338b-national-commission-for-backward-classes/"}, "339": {"url": "https://www.constitutionofindia.net/articles/article-339-control-of-the-union-over-the-administration-of-scheduled-areas-and-the-welfare-of-scheduled-tribes/", "draft": "300", "draftText": "(1) The President may at any time and shall, on the expiration of ten years from the commencement of this Constitution, by order, appoint a Commission to report on the administration of the scheduled areas and the welfare of the scheduled tribes in the States for the time being specified in Part I of the First Schedule.\nThe order may define the composition, powers and procedure of the Commission and may contain such incidental or ancillary provisions as the President may consider necessary or desirable.\n(2) The executive power of the Union shall extend to the giving of directions to such a State as to the drawing up and execution of schemes specified in the direction to be essential for the welfare of the scheduled tribes in the State.", "debated": ["1949-06-16"]}, "340": {"url": "https://www.constitutionofindia.net/articles/article-340-appointment-of-a-commission-to-investigate-the-conditions-of-backward-classes/", "draft": "301", "draftText": "(1) The President may by order appoint a Commission consisting of such persons as he thinks fit to investigate the conditions of socially and educationally backward classes within the territory of India and the difficulties under which they labour and to make recommendations as to the steps that should be taken by the Union or any State to remove such difficulties and to improve their condition and as to the grants that should be given for the purpose by the Union or any State and the conditions subject to which such grants should be given, and the order appointing such Commission shall define the procedure to be followed by the Commission.\n(2) A Commission so appointed shall investigate the matters referred to them and present to the President a report setting out the facts as found by them and making such recommendations as they think proper.\n(3) The President shall cause a copy of the report so presented, together with a memorandum explaining the action taken thereon to be laid before Parliament.", "debated": ["1949-06-16"], "adopted": "1949-06-16"}, "342": {"url": "https://www.constitutionofindia.net/articles/article-342-scheduled-tribes-2/"}, "166": {"url": "https://www.constitutionofindia.net/articles/article-166-conduct-of-business-of-the-government-of-a-state/", "draft": "146", "draftText": "(1) All executive action of the Government of a State shall be expressed to be taken in the name of the Governor.\n(2) Orders and other instruments made and executed in the name of the Governor shall be authenticated in such manner as may be specified in rules to be made by the Governor, and the validity of an order or instrument which is so authenticated shall not be called in question on the ground that it is not an order or instrument made or executed by the Governor.", "debated": ["1949-06-02"], "adopted": "1949-06-02"}, "167": {"url": "https://www.constitutionofindia.net/articles/article-167-duties-of-chief-minister-as-respects-the-furnishing-of-information-to-governor-etc/", "draft": "147", "draftText": "It shall be the duty of the Chief Minister of each State-\n(a) To communicate to the Governor of the State all decisions of the Council of ministers relating to the administration of the affairs of the State and proposals for legislation;\n(b) To furnish such information relating to the administration of the affairs of the State and proposals for legislation as the Governor may call for; and\n(c) If the Governor so requires, to submit for the consideration of the Council of ministers any matter on which a decision has been taken by a minister but which has not been considered by the Council.", "debated": ["1949-06-02"]}, "168": {"url": "https://www.constitutionofindia.net/articles/article-168-constitution-of-legislatures-in-states/", "draft": "148", "draftText": "(1) For every State there shall be a Legislature which shall consist of the Governor; and\n(a) In the States of – , two Houses,\n(b) In other States, one House.\n(2) Where there are two Houses of the Legislature of a State, one shall be known as the Legislative Council and the other as the Legislative Assembly and where there is only one House, it shall be known as the Legislative Assembly.", "debated": ["1949-01-06"], "adopted": "1949-01-06"}, "169": {"url": "https://www.constitutionofindia.net/articles/article-169-abolition-or-creation-of-legislative-councils-in-states/", "adopted": "1949-07-30", "draft": "148A", "addedLater": true}, "236": {"url": "https://www.constitutionofindia.net/articles/article-236-interpretation/", "debated": ["1949-09-16"], "adopted": "1949-09-16", "draft": "209D"}, "235": {"url": "https://www.constitutionofindia.net/articles/article-235-control-over-subordinate-courts/", "adopted": "1949-09-16", "draft": "209C", "addedLater": true}, "234": {"url": "https://www.constitutionofindia.net/articles/article-234-recruitment-of-persons-other-than-district-judges-to-the-judicial-service/", "debated": ["1949-09-16"], "adopted": "1949-09-16", "draft": "209B"}, "233": {"url": "https://www.constitutionofindia.net/articles/article-233-appointment-of-district-judges/", "debated": ["1949-09-16"], "adopted": "1949-09-16", "draft": "209A"}, "170": {"url": "https://www.constitutionofindia.net/articles/article-170-composition-of-the-legislative-assemblies/", "draft": "149", "draftText": "(1) Subject to the provisions of articles 294 and 295 of this Constitution the Legislative Assembly of each State shall be composed of members chosen by direct election.\n(2) The election shall be on the basis of adult suffrage; that is to say, every citizen who is not less than twenty-one years of age and is not otherwise disqualified under this Constitution or any law made by the Legislature of the State on the ground of non-residence, unsoundness of mind, crime or corrupt or illegal practice shall be entitled to be registered as a voter at such elections.\n(3) The representation of each territorial constituency in the Legislative Assembly of a State shall be on the basis of the population of that constituency as ascertained at the last preceding census and shall, save in the case of the autonomous districts of Assam, be on a scale of not more than one representative for every lakh of the population:\nProvided that the total number of members in the Legislative Assembly of a State shall in no case be more than three hundred or less than sixty.\n(4) Upon the completion of each census, the representation of the several territorial constituencies in the Legislative Assembly of each State shall, subject to the provisions of article 289 of this Constitution, be readjusted by such authority, in such manner and with effect from such date as the Legislature of the State may by law determine:\nProvided that such readjustment shall not affect representation to the Legislative Assembly until the dissolution of the then existing Assembly.", "debated": ["1949-01-06", "1949-01-07", "1949-01-08", "1949-10-14"], "adopted": "1949-10-14"}, "229": {"url": "https://www.constitutionofindia.net/articles/article-229-officers-and-servants-and-the-expenses-of-high-courts/", "draft": "205", "draftText": "(1) The salaries, allowances and pensions payable to or in respect of the officers and servants of a High Court shall be fixed by the Chief Justice of the court in consultation with the Governor of the State in which the High Court has its principal seat.\n(2) The administrative expenses of a High Court, including all salaries, allowances and pensions payable to or in respect of officers and servants of the court, and the salaries and allowances of the judges of the court, shall be charged upon the revenues of the State, and any fees or other moneys taken by the court shall form part of those revenues.", "debated": ["1949-06-08"], "adopted": "1949-06-08"}, "171": {"url": "https://www.constitutionofindia.net/articles/article-171-composition-of-the-legislative-councils/", "draft": "150", "draftText": "(1) The total number of members in the Legislative Council of a State having such a Council shall not exceed twenty-five per cent of the total number of members in the Legislative Assembly of that State.\n(2) Of the total number of members in the Legislative Council of a State-\n(a) One-half shall be chosen from panels of candidates constituted under clause (3) of this article;\n(b) One-third shall be elected by the members of the Legislative Assembly of the State in accordance with the system of proportional representation by means of the single transferable vote; and\n(c) The remainder shall be nominated by the Governor.\n(3) Before the first general election and, thereafter, before each triennial election under clause (2) of article 151 of this Constitution to the Legislative Council of a State, five panels of candidates shall be formed, of which one shall contain the names of representatives of universities in the State and the remaining four shall respectively contain the names of persons having special knowledge or practical experience in respect of the following subjects, namely:-\n(a) Literature, art and science;\n(b) Agriculture, fisheries and allied subjects;\n(c) Engineering and architecture;\n(d) Public administration and social services.\n(4) Each panel of candidates constituted under clause (3) of this article shall contain at least twice the number to be elected from such panel.\n(5) For bye-elections clauses (3) and (4) of this article shall have effect subject to such adaptations and modifications as may be prescribed by the Legislature of the State by law.", "debated": ["1949-06-02", "1949-07-30", "1949-08-19"], "adopted": "1949-08-19"}, "172": {"url": "https://www.constitutionofindia.net/articles/article-172-duration-of-state-legislatures/", "draft": "151", "draftText": "(1) Every Legislative Assembly of every State, unless sooner dissolved, shall continue for five years from the date appointed for its first meeting and the expiration of the said period of five years shall operate as a dissolution of the Assembly.\n(2) The Legislative Council of a State shall not be subject to dissolution, but as nearly as may be one-third of the members thereof shall retire as soon as may be on the expiration of every third year in accordance with the provisions made in that behalf by the Legislature of the State by law.", "debated": ["1949-06-02"], "adopted": "1949-06-02"}, "182": {"url": "https://www.constitutionofindia.net/articles/article-182-the-chairman-and-deputy-chairman-of-the-legislative-council/", "draft": "160", "draftText": "The Legislative Council of every State having such Council, shall, as soon as may be, choose two members of the Council to be respectively Chairman and Deputy Chairman thereof and, so often as the office of Chairman or Deputy Chairman becomes vacant, the Council shall choose another member to be Chairman or Deputy Chairman, as the case may be.", "debated": ["1949-06-02"], "adopted": "1949-06-02"}, "183": {"url": "https://www.constitutionofindia.net/articles/article-183-vacation-and-resignation-of-and-removal-from-the-offices-of-chairman-and-deputy-chairman/", "draft": "161", "draftText": "A member holding office as Chairman or Deputy Chairman of a Legislative Council-\n(a) Shall vacate his office if he ceases to be a member of the Council;\n(b) May at any time by writing under his hand addressed, if such member is the Chairman, to the Deputy Chairman, and if such member is the Deputy Chairman, to the Chairman, resign his office; and\n(c) May be removed from his office for incapacity or want of confidence by a resolution of the Council passed by a majority of all the then members of the Council:\nProvided that no resolution for the purpose of clause (c) of this article shall be moved unless at least fourteen days' notice has been given of the intention to move the resolution.", "debated": ["1949-06-02"], "adopted": "1949-06-02"}, "184": {"url": "https://www.constitutionofindia.net/articles/article-184-power-of-the-deputy-chairman-or-other-person-to-perform-the-duties-of-the-office-of-or-to-act-as-chairman/", "draft": "162", "draftText": "(1) While the office of Chairman is vacant, the duties of the office shall be performed by the Deputy Chairman or if the office of Deputy Chairman is also vacant by such member of the Council as the Governor may appoint for the purpose.\n(2) During the absence of the Chairman from any sitting of the Council, the Deputy Chairman or, if he is also absent such person as may be determined by the rules of procedure of the Council, or, if no such person is present, such other person as may be determined by the Council, shall act as Chairman.", "debated": ["1949-06-02"], "adopted": "1949-06-02"}, "189": {"url": "https://www.constitutionofindia.net/articles/article-189-voting-in-houses-power-of-houses-to-act-notwithstanding-vacancies-and-quorum/", "draft": "164", "draftText": "(1) Save as provided in this Constitution, all questions in a House or a joint sitting of two Houses of the Legislature of a State shall be determined by a majority of votes of the members present and voting, other than the Speaker or Chairman or person acting as such.\nThe Speaker or Chairman or person acting as such shall not vote in the first instance but shall have and exercise a casting vote in the case of an equality of votes.\n(2) A House of the Legislature of a State shall have power to act notwithstanding any vacancy in the membership thereof, and any proceedings in the Legislature of a State shall be valid notwithstanding that it is discovered subsequently that some person who was not entitled so to do, sat or voted or otherwise took part in the proceedings.\n(3) If at any time during a meeting of the Legislative Assembly or the Legislative Council of a State there is no quorum, it shall be the duty of the Speaker or Chairman or person acting as such either to adjourn the House or to suspend the meeting until there is a quorum.\nThe quorum shall be ten members or one-sixth of the total number of members of the House, whichever is greater.", "debated": ["1949-06-14"], "adopted": "1949-06-14"}, "190": {"url": "https://www.constitutionofindia.net/articles/article-190-vacation-of-seats/", "draft": "166", "draftText": "(1) No person shall be a member of both Houses of the Legislature of a State and provision shall be made by the Legislature of the State by law for the vacation by a person who is chosen a member of both Houses of his seat in one House or the other.\n(2) No person shall be a member both of Parliament and of the Legislature of a State and if a person is chosen a member both of Parliament and of the Legislature of a State, then, at the expiration of such period as may be specified in rules made by the Governor of the State, that person's seat in the Legislature of the State shall become vacant, unless he has previously resigned his seat in Parliament.\n(3) If a member of a House of the Legislature of a State-\n(a) Becomes subject to any of the disqualifications mentioned in clause (i) of the next succeeding article; or\n(b) Resigns his seat by writing under his hand addressed to the Speaker or the Chairman, as the case may be, his seat shall thereupon become vacant.\n(4) If for a period of sixty days a member of a House of the Legislature of a State is without permission of the House absent from all meetings thereof, the House may declare his seat vacant:\nProvided that in computing the said period of sixty days no account shall be taken of any period during which the House is prorogued or is adjourned for more than four consecutive days.", "debated": ["1949-06-02"], "adopted": "1949-06-02"}, "228": {"url": "https://www.constitutionofindia.net/articles/article-228-transfer-of-certain-cases-to-high-court/", "draft": "204", "draftText": "If the High Court is satisfied that a case pending in a court subordinate to it involves a substantial question of law as to the interpretation of this Constitution, it shall withdraw the case to itself and dispose of the same.\nExplanation.-In this article, \"High Court\" includes a court of final jurisdiction in a State for the time being specified in Part III of the First Schedule with regard to the case so pending.", "debated": ["1949-06-07", "1949-06-08"], "adopted": "1949-06-08"}, "191": {"url": "https://www.constitutionofindia.net/articles/article-191-disqualifications-for-membership/", "draft": "167", "draftText": "(1) A person shall be disqualified for being chosen as, and for being, a member of the Legislative Assembly or Legislative Council of a State.\n(a) If he holds any office of profit under the Government of India or the Government of any State for the time being specified in the First Schedule other than an office declared by the Legislature of the State by law not to disqualify its holder;\n(b) If he is of unsound mind and stands so declared by a competent court;\n(c) If he is an undischarged insolvent;\n(d) If he is under any acknowledgment of allegiance or adherence to a foreign power, or is a subject or a citizen or entitled to the rights or privileges of a subject or a citizen of a foreign power;\n(e) If he is so disqualified by or under any law made by the Legislature of the State.\n(2) For the purposes of this article, a person shall not be deemed to hold an office of profit under the Government of India or the Government of any State for the time being specified in the First Schedule by reason only that-\n(a) He is a minister either for India or for any State for the time being specified in Part I of the First Schedule; or\n(b) He is a minister for any State for the time being specified in Part III of the first Schedule is responsible to the Legislature of the State, or\nwhere there are two Houses of the Legislature of the State, to the Lower House of such Legislature and if not less than three-fourths of the members of such Legislature or House, as the case may be, are elected.", "debated": ["1949-06-02"], "adopted": "1949-06-02"}, "227": {"url": "https://www.constitutionofindia.net/articles/article-227-power-of-superintendence-over-all-courts-by-the-high-court/", "draft": "203", "draftText": "(1) Every High Court shall have superintendence over all courts throughout the territories in relation to which it exercises jurisdiction.\n(2) The High Court may-\n(a) Call for returns from such courts;\n(b) Direct the transfer of any suit or appeal from any such court to any other court of equal or superior jurisdiction, or withdraw such suit or appeal from any such court to itself;\n(c) Make and issue general rules and prescribe forms for regulating the practice and proceedings of such courts; and\n(d) Prescribe forms in which books, entries and accounts shall be kept by the officers of any such courts.\n(3) The High Court may also settle tables of fees to be allowed to the sheriff and all clerks and officers of such courts and to attorneys, advocates and pleaders practising therein:\nProvided that any rules made, forms prescribed or tables settled under clause (2) or clause (3) of this article shall not be inconsistent with the provisions of any law for the time being in force, and shall require the previous approval of the Governor.", "debated": ["1949-06-15", "1949-10-16"], "adopted": "1949-10-16"}, "192": {"url": "https://www.constitutionofindia.net/articles/article-192-decision-on-questions-as-to-disqualifications-of-members/", "notDebated": true, "adopted": "1949-06-14", "draft": "167A", "addedLater": true}, "193": {"url": "https://www.constitutionofindia.net/articles/article-193-penalty-for-sitting-and-voting-before-making-oath-or-affirmation-under-article-188-or-when-not-qualified-or-when-disqualified/", "draft": "168", "draftText": "If a person sits or votes as a member of the Legislative Assembly or the Legislative Council of a State before he has complied with the requirements of article 165 of this Constitution, or when he knows that he is not qualified or that he is disqualified for membership thereof or that he is prohibited from so doing by the provisions of any law made by the Legislature of the State, he shall be liable in respect of each day on which he so sits or votes to a penalty of five hundred rupees to be recovered as a debt due to the State.", "notDebated": true, "adopted": "1949-06-03"}, "226": {"url": "https://www.constitutionofindia.net/articles/article-226-power-of-high-courts-to-issue-certain-writs/", "draft": "202", "draftText": "(1) Notwithstanding anything contained in article 25 of this Constitution, every High Court shall have power, throughout the territories in relation to which it exercises jurisdiction, to issue directions or orders in the nature of the writs of habeas corpus, mandamus, prohibition, quo warranto and certiorari, for the enforcement of any of the rights conferred by Part III of this Constitution and for any other purpose.\n(2) The power conferred on a High Court by clause (1) of this article shall not be in derogation of the power conferred on the Supreme Court by clause (2) of article 25 of this Constitution.", "debated": ["1949-06-07", "1949-09-07"], "adopted": "1949-09-07"}, "194": {"url": "https://www.constitutionofindia.net/articles/article-194-powers-privileges-etc-of-the-houses-of-legislatures-and-of-the-members-and-committees-thereof/", "draft": "169", "draftText": "(1) Subject to the rules and standing orders regulating the procedure of the Legislature, there shall be freedom of speech in the Legislature of every State.\n(2) No member of the Legislature of a State shall be liable to any proceedings in any court in respect of anything said or any vote given by him in the Legislature or any committee thereof, and no person shall be so liable in respect of the publication by or under the authority of a House of such a Legislature of any report, paper, votes or proceedings.\n(3) In other respects the privileges and immunities of members of a House of the Legislature of a State shall be such as may from time to time be defined by the Legislature by law, and until so defined, shall be such as are enjoyed by the members of the House of Commons of the Parliament of the United Kingdom at the commencement of this Constitution.\n(4) The provisions of clauses (1), (2) and (3) of this article shall apply in relation to persons who by virtue of this Constitution have the right to speak in, and otherwise take part in the proceedings of, a House of the Legislature of a State as they apply in relation to members of that Legislature.", "debated": ["1949-06-03", "1949-10-16"], "adopted": "1949-10-16"}, "225": {"url": "https://www.constitutionofindia.net/articles/article-225-jurisdiction-of-existing-high-courts/", "draft": "201", "draftText": "Subject to the provisions of this Constitution and to any provisions of any law of the appropriate Legislature made by virtue of the powers conferred on that Legislature by this Constitution, the jurisdiction of, and the law administered in, any existing High Court, and the respective powers of the judges thereof in relation to the administration of justice in the court, including any power to make rules of court and to regulate the sittings of the court and of members thereof sitting alone or in division courts, shall be the same as immediately before the commencement of this Constitution:\nProvided that any restriction to which the exercise of original jurisdiction of any of the High Courts with respect to any matter concerning the revenue or concerning any act ordered or done in the collection thereof was subject immediately before the commencement of this Constitution shall no longer apply to the exercise of such jurisdiction.", "debated": ["1949-06-07"], "adopted": "1949-06-07"}, "195": {"url": "https://www.constitutionofindia.net/articles/article-195-salaries-and-allowances-of-members/", "draft": "170", "draftText": "Members of the Legislative Assembly and the Legislative Council of a State shall be entitled to receive such salaries and allowances as may from time to time be determined by the Legislature of the State by law, and, until provision in that respect is so made, allowances at such rates and upon such conditions as were immediately before the date of commencement of this Constitution applicable in the case of members of the Provincial Legislative Assembly for that State.", "debated": ["1949-06-03"], "adopted": "1949-06-03"}, "196": {"url": "https://www.constitutionofindia.net/articles/article-196-provisions-as-to-introduction-and-passing-of-bills/", "draft": "171", "draftText": "(1) Subject to the provisions of articles 173 and 182 of this Constitution with respect to Money Bills and other financial Bills, a Bill may originate in either House of the Legislature of a State which has a Legislative Council.\n(2) Subject to the provisions of articles 172 and 173 of this Constitution, a Bill shall not be deemed to have been passed by the Houses. of the Legislature of a State having a Legislative Council unless it has been agreed to by both Houses either without amendment or with such amendments only as are agreed to by both Houses.\n(3) A Bill pending in the Legislature of a State shall not lapse by reason of the prorogation of the House or Houses thereof.\n(4) A Bill pending in the Legislative Council of a State which has not been passed by the Legislative Assembly shall not lapse on a dissolution of the Assembly.\n(5) A Bill which is pending in the Legislative Assembly of a State, or which having been passed by the Legislative Assembly is pending in the Legislative Council, shall lapse on a dissolution of the Assembly.", "notDebated": true, "adopted": "1949-06-14"}, "197": {"url": "https://www.constitutionofindia.net/articles/article-197-restriction-on-powers-of-legislative-council-as-to-bills-other-than-money-bills/", "draft": "172", "draftText": "1) If after a Bill has been passed by the Legislative Assembly of a State having a Legislative Council and transmitted to the Legislative Council, more than six months elapse from the date of the reception of the Bill by the Council without the Bill being passed by both Houses, the Governor may, unless the Bill has lapsed by reason of a dissolution of the Legislative Assembly, summon the Houses to meet in a joint sitting for the purposes of deliberating and voting on the Bill:\nProvided that nothing in this clause shall apply to a Money Bill.\n(2) In reckoning any such period of six months as is referred to in clause (1) of this article, no account shall be taken of any time during which both Houses are prorogued or adjourned for more than four days.\n(3) If at the joint sitting of the two Houses summoned in accordance with the provisions of this article the Bill, with such amendments, if any, as are agreed to in joint sitting, is passed by a majority of the total number of members of both Houses present and voting, it shall be deemed for the purposes of this Constitution to have been passed by both Houses:\nProvided that at a joint sitting-\n(a) If the Bill has not been passed by the Legislative Council with amendments and returned to the Legislative Assembly, no amendment shall be proposed to the Bill other than such amendments (if any) as are made necessary by the delay in the passage of the Bill;\n(b) If the Bill has been so passed and returned by the Legislative Council, only such amendments as aforesaid shall be proposed to the Bill and such other amendments as are relevant to the matters with respect to which the Houses have not agreed; and the decision of the person presiding as to the amendments which are admissible under this clause shall be final.", "debated": ["1949-08-01"], "adopted": "1949-08-01"}, "224": {"url": "https://www.constitutionofindia.net/articles/article-224-appointment-of-additional-and-acting-judges/", "draft": "200", "draftText": "Notwithstanding anything contained in this Chapter, the Chief Justice of a High Court may at any time, subject to the provisions of this article, request any person who has held the office of a judge of that court to sit and act as a judge of the court, and every such person so requested shall, while so sitting and acting, have all the jurisdiction, powers and privileges of, but shall not otherwise be deemed to be, a judge of that court:\nProvided that nothing in this article shall be deemed to require any such person as aforesaid to sit and act as a judge of that court unless he consents so to do.", "debated": ["1949-06-07"]}, "198": {"url": "https://www.constitutionofindia.net/articles/article-198-special-procedure-in-respect-of-money-bills/", "draft": "173", "draftText": "1) A Money Bill shall not be introduced in a Legislative Council.\n(2) After a Money Bill has been passed by the Legislative Assembly of a State having a Legislative Council, it shall be transmitted to the Legislative Council for its recommendations, and the Legislative Council shall within a period of thirty days from the date of its receipt of the Bill return the Bill to the Legislative Assembly with its recommendations, and the Legislative Assembly may thereupon either accept or reject all or any of the recommendations of the Legislative Council.\n(3) If the Legislative Assembly accepts any of the recommendations of the Legislative Council, the Money Bill shall be deemed to have been passed by both Houses with the amendments recommended by the Legislative Council and accepted by the Legislative Assembly.\n(4) If the Legislative. Assembly does not accept any of the recommendations of the Legislative Council, the Money Bill shall be deemed to have been passed by the Legislative Assembly without any of the amendments recommended by the Legislative Council.\n(5) If a Money Bill passed by the Legislative Assembly and transmitted to the Legislative Council for its recommendations is not returned to the Legislative Assembly within the said period of thirty days, it shall be deemed to have been passed by both Houses at the expiration of the said period in the form in which it was passed by the Legislative Assembly.", "debated": ["1949-06-10"], "adopted": "1949-07-10"}, "223": {"url": "https://www.constitutionofindia.net/articles/article-223-appointment-of-acting-chief-justice/", "draft": "199", "draftText": "If by reason of any temporary increase in the business of any High Court or by reason of arrears of work in any such court, it appears to the President that the number of the judges of the court should be for the time being increased, the President may, subject to the foregoing provisions of this Chapter with respect to the maximum number of judges, appoint persons duly qualified for appointment as judges to be additional judges of the court for such period not exceeding two years as he may specify.", "debated": ["1949-06-07"], "adopted": "1949-06-07"}, "199": {"url": "https://www.constitutionofindia.net/articles/article-199-definition-of-money-bills/", "draft": "174", "draftText": "(1) For the purposes of this Chapter, a Bill shall be deemed to be a Money Bill if it contains only provisions dealing with all or any of the following matters, namely:-\n(a) The imposition, abolition, remission, alteration or regulation of any tax;\n(b) The regulation of the borrowing of money or the giving of any guarantee by the State, or the amendment of the law with respect to any financial obligations undertaken or to be undertaken by the State;\n(c) Supply;\n(d) The appropriation of the revenues of the State;\n(e) The declaring of any expenditure to be expenditure charged on the revenues of the State, or the increasing of the amount of any such expenditure;\n(f) The receipt of money on account of the revenues of the State or the custody or issue of such money or the audit of the accounts of the State; or\n(g) Any matter incidental to any of the matters specified in items (a) to (f) of this clause.\n(2) A Bill shall not be deemed to be a Money Bill by reason only that it provides for the imposition of fines or other pecuniary penalties, or for the demand or payment of fees for licences or fees for services rendered or by reason that it provides for the imposition, abolition, remission, alteration or regulation of any tax by any local authority or body for local purposes.\n(3) If any question arises whether a Bill introduced in the Legislature of a State which has a Legislative Council is a Money Bill or not, the decision of the Speaker of the Legislative Assembly of such State thereon shall be final.\n(4) There shall be endorsed on every Money Bill when it is transmitted to the Legislative Council under the last preceding article, and when it is presented to the Governor for assent under the next succeeding article, the certificate of the Speaker of the Legislative Assembly signed by him that it is a Money Bill.", "debated": ["1949-06-10"], "adopted": "1949-08-10"}, "221": {"url": "https://www.constitutionofindia.net/articles/article-221-salaries-etc-of-judges/", "draft": "197", "draftText": "The judges of each High Court shall be entitled to such salaries and allowances, and to such rights in respect of leave and pensions, as may from time to time be fixed by or under law made by the Legislature of the State in which the Court has its principal seat, and until they are so fixed, shall be entitled to such salaries, allowances and rights in respect of leave of absence or pension as are specified in the Second Schedule:\nProvided that the salary of the Chief Justice of a High Court shall not be less than four thousand rupees per month and the salary of any other judge of a High Court shall not be less than three thousand and five hundred rupees per month:\nProvided further that neither the salary of a judge nor his rights in respect of leave of absence or pension shall be varied to his disadvantage after his appointment.", "debated": ["1949-08-01"], "adopted": "1949-08-01"}, "200": {"url": "https://www.constitutionofindia.net/articles/article-200-assent-to-bills/", "draft": "175", "draftText": "A Bill which has been passed by the Legislative Assembly of a State or, in the case of a State having a Legislative Council, has been passed by both Houses of the Legislature of the State, shall be presented to the Governor and the Governor shall declare either that he assents to the Bill or that he withholds assent therefrom or that he reserves the Bill for the consideration of the President:\nProvided that where there is only one House of the Legislature and the Bill has been passed by that House, the Governor may, in his discretion, return the Bill together with a message requesting that the House will reconsider the Bill or any specified provisions thereof and, in particular, will reconsider the desirability of introducing any such amendments as he may recommend in his message and, when a Bill is so returned, the House shall reconsider it accordingly and if the Bill is passed again by the House with or without amendment and presented to the Governor for assent, the Governor shall not withhold assent therefrom.", "debated": ["1949-07-30", "1949-08-01", "1949-10-17"], "adopted": "1949-10-17"}, "201": {"url": "https://www.constitutionofindia.net/articles/article-201-bills-reserved-for-consideration/", "draft": "176", "draftText": "When a Bill is reserved by a Governor for the consideration of the President, the President shall declare either that he assents to the Bill or that he withholds assent therefrom:\nProvided that where the Bill is not a Money Bill the President may direct the Governor to return the Bill to the House or, as the case may be, the Houses of the Legislature of the State together with such a message as is mentioned in the proviso to the last preceding article and, when a Bill is so returned, the House or Houses shall reconsider it accordingly within a period of six months from the date of receipt of such message and, if it is again passed by them with or without amendment, it shall be presented again to the President for his consideration.", "notDebated": true, "adopted": "1949-08-01"}, "202": {"url": "https://www.constitutionofindia.net/articles/article-202-annual-financial-statement/", "draft": "177", "draftText": "1) The Governor shall in respect of every financial year cause to be laid before the House or Houses of the Legislature of the State a statement of the estimated receipts and expenditure of the State for that year, in this Part of this Constitution referred to as the \"annual financial statement \".\n(2) The estimates of expenditure embodied in the annual financial statement shall show separately-\n(a) The sums required to meet expenditure described by this Constitution as expenditure charged upon the revenues of the State; and\n(b) The sums required to meet other expenditure proposed to be made from the revenues of the State; and shall distinguish expenditure on revenue account from other expenditure.\n(3) The following expenditure shall be expenditure charged on the revenues of each State-\n(a) The emoluments and allowances of the Governor and other expenditure relating to his office;\n(b) The emoluments and allowances of the Speaker and the Deputy Speaker of the Legislative Assembly, and in the case of a State having a Legislative Council, also of the Chairman and the Deputy Chairman of the Legislative Council;\n(c) Debt charges for which the State is liable including interest, sinking fund charges and redemption charges, and other expenditure relating to the raising of loans and the service and redemption of debt;\n(d) Expenditure in respect of the salaries and allowances of judges of any High Court;\n(e) Any sums required to satisfy any judgment, decree or award of any court or arbitral tribunal;\n(f) Any other expenditure declared by this Constitution or by the Legislature of the State by law to be so charged.", "debated": ["1949-06-10"], "adopted": "1949-06-10"}, "203": {"url": "https://www.constitutionofindia.net/articles/article-203-procedure-in-legislature-with-respect-to-estimates/", "draft": "178", "draftText": "(1) So much of the estimates as relates to expenditure charged upon the revenues of a State shall not be submitted to the vote of the Legislative Assembly, but nothing in this clause shall be construed as preventing the discussion in the Legislature of those estimates.\n(2) So much of the said estimates as relates to other expenditure shall be submitted in the form of demands for grants to the Legislative Assembly, and the Legislative Assembly shall have power to assent, or to refuse to assent, to any demand, or to assent to any demand subject to a reduction of the amount specified therein.\n(3) No demand for a grant shall be made except on the recommendation of the Governor.", "debated": ["1949-06-10"], "adopted": "1949-06-10"}, "204": {"url": "https://www.constitutionofindia.net/articles/article-204-appropriation-bills/", "draft": "179", "draftText": "(1) The Governor shall authenticate by his signature a schedule specifying-\n(a) The grants made by the Assembly under the last preceding article;\n(b) The several sums required to meet the expenditure charged on the revenues of the State, but not exceeding in any case, the sum shown in the statement previously laid before the House or Houses.\n(2) The schedule so authenticated shall be laid before the Assembly but shall not be open to discussion or vote in the Legislature.\n(3) Subject to the provisions of the next two succeeding articles, no expenditure from the revenues of the State shall be deemed to be duly authorised unless it is specified in the schedule so authenticated.", "debated": ["1949-06-10"], "adopted": "1949-06-10"}, "220": {"url": "https://www.constitutionofindia.net/articles/article-220-restriction-on-practice-after-being-a-permanent-judge/", "draft": "196", "draftText": "No person who has held office-\n(a) As a judge of a High Court, or\n(b) As an additional judge or temporary judge of a High Court on having been recruited from the Bar,\nshall plead or act in any Court or before any authority within the territory of India.", "debated": ["1949-06-07"], "adopted": "1949-06-07"}, "205": {"url": "https://www.constitutionofindia.net/articles/article-205-supplementary-additional-or-excess-grants/", "draft": "180", "draftText": "If in respect of any financial year further expenditure from the revenues of the State becomes necessary over and above the expenditure therefore authorised for that year, the Governor shall cause to be laid before the House or Houses a supplementary statement showing the estimated amount of that expenditure, and the provisions of the preceding articles shall have effect in relation to that statement and that expenditure as they have effect in relation to the annual financial statement and the expenditure mentioned therein.", "debated": ["1949-06-10"], "adopted": "1949-06-10"}, "206": {"url": "https://www.constitutionofindia.net/articles/article-206-votes-on-account-votes-of-credit-and-exceptional-grants/", "draft": "181", "draftText": "If in any financial year expenditure from the revenues of the State has been incurred on any service for which the vote of the Legislative Assembly is necessary in excess of the amount granted for that service and for that year, a demand for the excess shall be presented to the Assembly and the provisions of articles 178 and 179 of this Constitution shall have effect in relation to such demand as they have effect in relation to a demand for a grant.", "debated": ["1949-06-10"], "adopted": "1949-06-10"}, "219": {"url": "https://www.constitutionofindia.net/articles/article-219-oath-or-affirmation-by-judges-of-high-courts/", "draft": "195", "draftText": "Every person appointed to be a judge of a High Court in a State shall, before he enters upon his office, make and subscribe before the Governor of the State or some person appointed in that behalf by him a declaration according to the form set out for the purpose in the Third Schedule.", "debated": ["1949-06-07"], "adopted": "1949-06-07"}, "218": {"url": "https://www.constitutionofindia.net/articles/article-218-application-of-certain-provisions-relating-to-supreme-court-to-high-courts/", "draft": "194", "draftText": "The provisions of clauses (4) and (5) of article 103 of this Constitution shall apply in relation to a High Court as they apply in relation to the Supreme Court with the substitution of references to the High Court for references to the Supreme Court.", "debated": ["1949-06-07"]}, "207": {"url": "https://www.constitutionofindia.net/articles/article-207-special-provisions-as-to-financial-bills/", "draft": "182", "draftText": "(1) A Bill or amendment making provision for any of the matters specified in items (a) to (f) of clause (1) of article 174 of this Constitution shall not be introduced or moved except on the recommendation of the Governor, and a Bill making such provision shall not be introduced in a Legislative Council:\nProvided that no recommendation shall be required under this clause for the moving of an amendment making provision for the reduction or abolition of any tax.\n(2) A Bill or amendment shall not be deemed to make provision for any of the matters aforesaid by reason only that it provides for the imposition of fines or other pecuniary penalties, or for the demand or payment of fees for licences or fees for services rendered, or by reason that it provides for the imposition, abolition, remission, alteration or regulation of any tax by any local authority or body for local purposes.\n(3) A Bill which, if enacted and brought into operation, would involve expenditure from the revenues of a State shall not be passed by a House of the Legislature of the State unless the Governor has recommended to that House the consideration of the Bill.", "debated": ["1949-06-10"], "adopted": "1949-06-10"}, "208": {"url": "https://www.constitutionofindia.net/articles/article-208-rules-of-procedure/", "draft": "183", "draftText": "(1) A House of the Legislature of a State may make rules for regulating, subject to the provisions of this Constitution, its procedure and the conduct of its business.\n(2) Until rules are made under clause (1) of this article, the rules of procedure and standing orders in force immediately before the commencement of this Constitution with respect to the Provincial Legislature for' the State shall have effect in relation to the Legislature of that State subject to such modifications and adaptations as may be made therein by the Speaker of the Legislative Assembly, or the Chairman of the Legislative Council, as the case may-be.\n(3) In a State having a Legislative Council the Governor, after consultation with the Speaker of the Legislative Assembly and the Chairman of the Legislative Council, may make rules as to the procedure with respect to joint sittings of, and communications between, the two Houses.\n(4) At a joint sitting of the two Houses the Speaker of the Legislative Assembly, or in his absence such person as may be determined by rules of procedure made under clause (3) of this article, shall preside.", "debated": ["1949-06-10"], "adopted": "1949-06-10"}, "209": {"url": "https://www.constitutionofindia.net/articles/article-209-regulation-by-law-of-procedure-in-the-legislature-of-the-state-in-relation-to-financial-business/", "debated": ["1949-06-10"], "adopted": "1949-06-10", "addedLater": true}, "210": {"url": "https://www.constitutionofindia.net/articles/article-210-language-to-be-used-in-the-legislature/", "draft": "184", "draftText": "(1) In the Legislature of a State, business shall be transacted in the language or languages generally used in that State or in Hindi or in English.\n(2) The Speaker of the Legislative Assembly or the Chairman of the Legislative Council may, whenever he thinks fit, make arrangements for making available in the Assembly or the Council, as the case may be, a summary in any language generally used in the State or in English of the speech delivered by a member in any other language, and such summary shall be included in the record of the proceedings of the House in which the speech has been delivered.", "debated": ["1949-09-17"], "adopted": "1949-09-17"}, "211": {"url": "https://www.constitutionofindia.net/articles/article-211-restriction-on-discussion-in-the-legislature/", "draft": "185", "draftText": "(1) No discussion shall take place in the Legislature of a State with respect to the conduct of any judge of the Supreme Court or of a High Court in the discharge of his duties.\n(2) In this article, the reference to a High Court shall be construed as including a reference to any court in a State for the time being specified in Part III of the First Schedule which is a High Court for any of the purposes of Chapter IV of Part V of this Constitution.", "debated": ["1949-06-10"], "adopted": "1949-06-10"}, "212": {"url": "https://www.constitutionofindia.net/articles/article-212-courts-not-to-inquire-into-proceedings-of-the-legislature/", "draft": "186", "draftText": "(1) The validity of any proceedings in the Legislature of a State shall not be called in question on the ground of any alleged irregularity of procedure.\n(2) No officer or other member of the Legislature of a State in whom powers are vested by or under this Constitution for regulating procedure or the conduct of business, or for maintaining order, in the Legislature shall be subject to the jurisdiction of any court in respect of the exercise by him of those powers.", "notDebated": true, "adopted": "1949-06-10"}, "213": {"url": "https://www.constitutionofindia.net/articles/article-213-power-of-governor-to-promulgate-ordinances-during-recess-of-legislature/", "draft": "187", "draftText": "1) If at any time, except when the Legislative Assembly of a State is in session, or where there is a Legislative Council in a State, except when both Houses of the Legislature are in session, the Governor is satisfied that circumstances exist which render it necessary for him to take immediate action, he may promulgate such Ordinances as the circumstances appear to him to require:\nProvided that the Governor shall not, without instructions from the President, promulgate any such Ordinance if an Act of the Legislature of the State containing the same provisions would under the provisions of this Constitution have been invalid unless, having been reserved for the consideration of the President, it had received the assent of the President.\n(2) An Ordinance promulgated under this article shall have the same force and effect as an Act of the Legislature of the State assented to by the Governor, but every such Ordinance-\n(a) Shall be laid before the Legislative Assembly of the State, or where there is a Legislative Council in the State, before both the Houses, and shall cease to operate at the expiration of six weeks from the reassembly of the Legislature, or if before the expiration of that period a resolution disapproving it is passed by the Legislative Assembly and agreed to by the Legislative Council, if any, upon the passing of the resolution or, as the case may be, on the resolution being agreed to by the Council; and\n(b) May be withdrawn at any time by the Governor.\nExplanation.-Where the Houses of the Legislature of a State having a Legislative Council are summoned to re-assemble on different dates, the period of six weeks shall be reckoned from the later of those dates for the purposes of this clause.\n(3) If and so far as an Ordinance under this article makes any provision which would not be valid if enacted in an Act of the Legislature of the State assented to by the Governor, it shall be void:\nProvided that, for the purposes of the provisions of this Constitution relating to the effect of an Act of the Legislature of a State which is repugnant to an Act of Parliament or an existing law with respect to a matter enumerated in the Concurrent List, an Ordinance promulgated under this article in pursuance of instructions from the President shall be deemed to be an Act of the Legislature of the State which has been reserved for the consideration of the President and assented to by him.", "debated": ["1949-06-14"], "adopted": "1949-06-14"}, "214": {"url": "https://www.constitutionofindia.net/articles/article-214-high-courts-for-states/", "draft": "191", "draftText": "(1) For the purposes of this Constitution the following courts shall, in relation to the territory of India except the States for the time being specified in Part III of the First Schedule, be deemed to be High Courts, that is to say,-\n(a) The High Courts in Calcutta, Madras, Bombay, Allahabad, Patna and Nagpur, the High Court of East Punjab and the Chief Court in Oudh;\n(b) Any other court in any of these States constituted or re-constituted under this Chapter as a High Court; and\n(c) Any other court in any of these States which may be declared by the appropriate Legislature by law to be a High Court for the purposes of this Constitution:\nProvided that if provision is made by the appropriate Legislature for the establishment of a High Court to replace any court or courts mentioned in this clause, then, as from the establishment of the new court, this article shall have effect as if the new court were mentioned therein in lieu of the court or courts so replaced.\n(2) Save as otherwise provided, the provisions of this Chapter shall apply to every High Court referred to in clause (1) of this article.", "debated": ["1949-06-06"], "adopted": "1949-06-06"}, "215": {"url": "https://www.constitutionofindia.net/articles/article-215-high-courts-to-be-courts-of-record/", "draft": "192", "draftText": "Every High Court shall be a court of record and shall consist of a Chief Justice and such other judges as the President may from time to time deem it necessary to appoint: Provided that the judges so appointed together with any additional judges appointed by the President in accordance with the following provisions of this Chapter shall at no time exceed in number such maximum as the President may by order fix in relation to that Court.", "debated": ["1949-06-06"], "adopted": "1949-06-06"}, "216": {"url": "https://www.constitutionofindia.net/articles/article-216-constitution-of-high-courts/", "debated": ["1949-06-06"], "adopted": "1949-06-06", "draft": "192A", "addedLater": true}, "217": {"url": "https://www.constitutionofindia.net/articles/article-217-appointment-and-conditions-of-the-office-of-a-judge-of-a-high-court/", "draft": "193", "draftText": "(1) Every judge of a High Court shall be appointed by the President by a warrant under his hand and seal after consultation with the Chief Justice of India, the Governor of the State, and in the case of appointment of a judge other than the Chief Justice, the Chief Justice of the High Court of the State, and shall hold office until he attains the age of sixty years or such higher age not exceeding sixty-five years as may be fixed in this behalf by law of the Legislature of the State:\nProvided that-\n(a) A judge may, by writing under his hand addressed to the Governor, resign his office;\n(b) A judge may be removed from his office by the President in the manner provided in clause (4) of article 103 of this Constitution for the removal of a judge of the Supreme Court;\n(c) The office of the judge shall be vacated by his being appointed by the President to be a judge of the Supreme Court or of any other High Court.\n(2) A person shall not be qualified for appointment as a judge of a High Court unless he is a citizen of India and-\n(a) Has held for at least ten years a judicial office in any State in or for which there is a High Court; or\n(b) Has been for at least ten years an advocate of a High Court or of two or more such courts in succession.\nExplanation I.-For the purposes of this clause-\n(a) In computing the period during which a person has been an advocate of a High Court, there shall be included any period during which a person held judicial office after he became an advocate;\n(b) In computing the period during which a person has held judicial office in a State for the time being specified in Part I or Part II of the First Schedule or been an advocate of a High Court, there shall be included any period before the commencement of this Constitution during which he held judicial office in any area which was comprised before the fifteenth day of August, 1947, within British India as defined by the Government of India Act, 1935, or has been an advocate of any High Court in any such area, as the case may be.\nExplanation II.-In sub-clauses .(a) and (b) of this clause, the reference to a High Court shall be construed as including a reference to a court in a State for the time being specified in Part III of the First Schedule which is a High Court for the purposes of articles 103 and 106 of this Constitution.", "debated": ["1949-06-06", "1949-06-07"], "adopted": "1949-06-07"}, "152": {"url": "https://www.constitutionofindia.net/articles/article-152-definition/", "draft": "128", "draftText": "In this Part, unless the context otherwise requires, the expression \"State\" means a State for the time being specified in Part I of the First Schedule.", "debated": ["1949-05-30"], "adopted": "1949-05-30"}, "173": {"url": "https://www.constitutionofindia.net/articles/article-173-qualification-for-membership-of-the-state-legislature/", "draft": "152", "draftText": "A person shall not be qualified to be chosen to fill a seat in the Legislature of a State unless he is, in the case of a seat in a Legislative Assembly, not less than twenty-five years of age, and in the case of a seat in a Legislative Council, not less than thirty-five years of age.", "debated": ["1949-06-02"], "adopted": "1949-06-02"}, "174": {"url": "https://www.constitutionofindia.net/articles/article-174-sessions-of-the-state-legislature-prorogation-and-dissolution/", "draft": "153", "draftText": "(1) The House or Houses of the Legislature of the State shall be summoned to meet twice at least in every year, and six months shall not intervene between their last sitting in one session and the date appointed for their first sitting in the next session.\n(2) Subject to the provisions of this article, the Governor may from time to time-\n(a) Summon the Houses or either House to meet at such time and place as he thinks fit;\n(b) Prorogue the House or Houses;\n(c) Dissolve the Legislative Assembly.\n(3) The functions of the Governor under subclauses (a) and (c) of clause (2) of this article shall be exercised by him in his discretion.", "debated": ["1949-06-02"], "adopted": "1949-06-02"}, "175": {"url": "https://www.constitutionofindia.net/articles/article-175-right-of-governor-to-address-and-send-messages-to-the-house-or-houses/", "draft": "154", "draftText": "(1) The Governor may address the Legislative Assembly or in the case of a State having a Legislative Council, either House of the Legislature of the State, or both Houses assembled together, and may for that purpose require the attendance of members.\n(2) The Governor may send messages to the House or Houses of the Legislature of the State whether with respect to a Bill then pending in the Legislature or otherwise, and a House to which any message is so sent shall with all convenient despatch consider any matter required by the message to be taken into consideration.", "debated": ["1949-06-02"], "adopted": "1949-06-02"}, "176": {"url": "https://www.constitutionofindia.net/articles/article-176-special-address-by-the-governor/", "draft": "155", "draftText": "(1) At the commencement of every session, the Governor shall address the Legislative Assembly or in the case of a State having a Legislative Council, both Houses assembled together and inform the Legislature of the cause of its summons.\n(2) Provision shall be made by the rules regulating the procedure of either House for the allotment of time for a discussion of the matters referred to in such address and for the precedence of such discussion over other business of the House.", "debated": ["1949-06-02"], "adopted": "1949-06-02"}, "177": {"url": "https://www.constitutionofindia.net/articles/article-177-rights-of-ministers-and-advocate-general-as-respects-the-houses/", "draft": "156", "draftText": "Every minister and the Advocate-General for a State shall have the right to speak in, and otherwise to take part in the proceedings of, the Legislative Assembly of the State or, in the case of a State having a Legislative Council, both Houses and any joint sitting of the Houses, and to speak in, and otherwise to take part in the proceedings of, any committee of the Legislature of which he may be named a member, but shall not, by virtue of this article, be entitled to vote.", "debated": ["1949-06-02"], "adopted": "1949-06-02"}, "178": {"url": "https://www.constitutionofindia.net/articles/article-178-the-speaker-and-deputy-speaker-of-the-legislative-assembly/", "draft": "157", "draftText": "Every Legislative Assembly of a State shall, as soon as may be, choose two members of the Assembly to be respectively Speaker and Deputy Speaker thereof, and, so often as the office of Speaker or Deputy Speaker becomes vacant, the Assembly shall choose another member to be Speaker or Deputy Speaker, as the case may be.", "debated": ["1949-06-02"], "adopted": "1949-06-02"}, "179": {"url": "https://www.constitutionofindia.net/articles/article-179-vacation-and-resignation-of-and-removal-from-the-offices-of-speaker-and-deputy-speaker/", "draft": "158", "draftText": "A member holding office as Speaker or Deputy Speaker of an Assembly-\n(a) Shall vacate his office if he ceases to be a member of the Assembly;\n(b) May at any time by writing under his hand addressed, if such member is the Speaker, to the Deputy Speaker, and if such member is the Deputy Speaker, to the Speaker, resign his office; and\n(c) May be removed from his office for incapacity or want of confidence by a resolution of the Assembly passed by a majority of all the then members of the Assembly:\nProvided that no resolution for the purpose of clause (c) of this article shall be moved unless at least fourteen days' notice has been given of the intention to move the resolution:\nProvided further that, whenever the Assembly is dissolved, the Speaker shall not vacate his office until immediately before the first meeting of the Assembly after the dissolution.", "debated": ["1949-06-02"], "adopted": "1949-06-02"}, "180": {"url": "https://www.constitutionofindia.net/articles/article-180-power-of-the-deputy-speaker-or-other-person-to-perform-the-duties-of-the-office-of-or-to-act-as-speaker/", "draft": "159", "draftText": "(1) While the office of Speaker is vacant the duties of the office shall be performed by the Deputy Speaker, or if the office of Deputy Speaker is also vacant, by such member of the Assembly as the Governor may appoint for the purpose.\n(2) During the absence of the Speaker from any sitting of the Assembly, the Deputy Speaker or, if he is also absent such person as may be determined by the rules of procedure of the Assembly, or, if no such person is present, such other person as may be determined by the Assembly, shall act as Speaker.", "debated": ["1949-06-02"], "adopted": "1949-06-02"}, "181": {"url": "https://www.constitutionofindia.net/articles/article-181-the-speaker-or-the-deputy-speaker-not-to-preside-while-a-resolution-for-his-removal-from-office-is-under-consideration/", "debated": ["1949-06-02"], "adopted": "1949-06-02", "draft": "159A", "addedLater": true}, "153": {"url": "https://www.constitutionofindia.net/articles/article-153-governors-of-states/", "draft": "129", "draftText": "There shall be a Governor for each State.", "debated": ["1949-05-30"], "adopted": "1949-05-30"}, "154": {"url": "https://www.constitutionofindia.net/articles/article-154-executive-power-of-state/", "draft": "130", "draftText": "(1) The executive power of the State shall be vested in the Governor and may be exercised by him in accordance with the Constitution and the law.\n(2) Nothing in this article shall-\n(a) Be deemed to transfer to the Governor any functions conferred by any existing law on any other authority; or\n(b) Prevent Parliament or the Legislature of the State from conferring by law functions on any authority subordinate to the Governor.", "debated": ["1949-05-30", "1949-10-16"], "adopted": "1949-10-16"}, "155": {"url": "https://www.constitutionofindia.net/articles/article-155-appointment-of-governor/", "draft": "131", "draftText": "The Governor of a State shall be elected by direct vote of all persons who have the right to vote at a general election for the Legislative Assembly of the State.\nAlternatively\nThe Governor of a State shall be appointed by the President by warrant under his hand and seal from a panel of four candidates to be elected by the members of the Legislative Assembly of the State, or, where there is a Legislative Council in the State, by all the members of the Legislative Assembly and of the Legislative Council of the State assembled at a joint meeting, in accordance with the system of proportional representation by means of the single transferable vote and the voting at such election shall be by secret ballot.", "debated": ["1949-05-30", "1949-05-31"], "adopted": "1949-05-31"}, "156": {"url": "https://www.constitutionofindia.net/articles/article-156-term-of-office-of-governor/", "draft": "132", "draftText": "The Governor shall hold office for a term of five years from the date on which he enters upon his office:\nProvided that –\n(a) A Governor may, by resignation under his hand addressed to the Speaker of the Legislative Assembly of the State or where there are two Houses of the Legislature of the State, to the Speaker of the Legislative Assembly and the Chairman of the Legislative Council of the State, resign his office;\n(b) A Governor may, for violation of the Constitution, be removed from office by impeachment in the manner provided in article 137 of this Constitution;\n(c) A Governor shall, notwithstanding the expiration of his term, continue to hold office until his successor enters upon his office.", "debated": ["1949-05-31"], "adopted": "1949-05-31"}, "157": {"url": "https://www.constitutionofindia.net/articles/article-157-qualifications-for-appointment-as-governor/", "draft": "134", "draftText": "(1) No person shall be eligible for election as Governor unless he is a citizen of India and has completed the age of thirty-five years.\n(2) A person shall not be eligible for election as a Governor of a State-\n(a) If he is disqualified for being chosen as a member of the Legislative Assembly of the State:\nProvided that it shall not be necessary for any such person to be a resident of the State; or\n(b) If he holds any office or position of emolument under the Government of India or the Government of any State for the time being specified in the First Schedule, or under any local or other authority subject to the control of any of the said Governments.\nExplanation.-For the purposes of this clause a person shall not be deemed to hold any office or position of emolument by reason only that-\nAlternatively\n(1) No person shall be eligible for appointment as Governor unless he is a citizen of India and has completed the age of thirty-five years.\n(2) A person shall not be eligible for appointment as Governor of a State if he is disqualified for being chosen as a member of the Legislative Assembly of the State:\nProvided that it shall not be necessary for any such person to be a resident of the State.", "debated": ["1949-05-31"], "adopted": "1949-05-31"}, "233A": {"url": "https://www.constitutionofindia.net/articles/article-233a-validation-of-appointments-of-and-judgments-etc-delivered-by-certain-district-judges/"}, "158": {"url": "https://www.constitutionofindia.net/articles/article-158-conditions-of-governors-office/", "draft": "135", "draftText": "(1) The Governor shall not be a member either of Parliament or of the Legislature of any State for the time being specified in the First Schedule, and if a member of Parliament or of the Legislature of any such State be elected (1 appointed) Governor, he shall be deemed to have vacated his seat in Parliament or such Legislature, as the case may be, on the date on which he enters upon his office as Governor.\n(2) The Governor shall not hold any other office or position of emolument.\n(3) The Governor shall have an official residence, and there shall be paid to the Governor such emoluments and allowances as may be determined by the Legislature of the State by law and, until provision in that behalf is so made, such emoluments and allowances as are specified in the Second Schedule.\n(4) The emoluments and allowances of the Governor shall not be diminished during his term of office.", "debated": ["1949-05-31", "1949-10-14"], "adopted": "1949-10-14"}, "159": {"url": "https://www.constitutionofindia.net/articles/article-159-oath-or-affirmation-by-the-governor/", "draft": "136", "draftText": "Every Governor and every person discharging the functions of the Governor shall before entering upon his office make and subscribe in the presence of the members of the Legislature of the State an affirmation or oath in the following form, that is to say:-\n\"I, A. B., do solemnly affirm (or swear) that I will faithfully execute the office of Governor (or discharge the functions of the Governor) of (name of the State) and will to the best of my ability preserve, protect and defend the Constitution and the law and that I will devote myself to the service and well-being of the people of (name of the State).\"", "debated": ["1949-05-31"], "adopted": "1949-05-31"}, "109": {"url": "https://www.constitutionofindia.net/articles/article-109-special-procedure-in-respect-of-money-bills/", "draft": "89", "draftText": "(1) A Money Bill shall not be introduced in the Council of States.\n(2) After a Money Bill has been passed by the House of the People it shall be transmitted to the Council of States for its recommendations and the Council of States shall within a period of thirty days from the date of its receipt of the Bill return the Bill to the House of the People with its recommendations and the House of the People may thereupon either accept or reject all or any of the recommendations of the Council of States.\n(3) If the House of the People accepts any of the recommendations of the Council of States, the Money Bill shall be deemed to have been passed by both Houses with the amendments recommended by the Council of States and accepted by the House of the People.\n(4) If the House of the People does not accept any of the recommendations of the Council of States, the Money Bill shall be deemed to have been passed by both Houses in the form in which it was passed by the House of the People without any of the amendments recommended by the Council of States.\n(5) If a Money Bill passed by the House of the People and transmitted to the Council of States for its recommendations is not returned to the House of the People within the said period of thirty days, it shall be deemed to have been passed by both Houses at the expiration of the said period in the form in which it was passed by the House of the People.", "debated": ["1949-05-20"], "adopted": "1949-05-20"}, "110": {"url": "https://www.constitutionofindia.net/articles/article-110-definition-of-money-bills/", "draft": "90", "draftText": "(1) For the purposes of this Chapter, a Bill shall be deemed to be a Money Bill if it contains only provisions dealing with all or any of the following matters, namely:-\n(a) The imposition, abolition, remission, alteration or regulation of any tax;\n(b) The regulation of the borrowing of money or the giving of any guarantee by the Government of India, or the amendment of the law with respect to any financial obligations undertaken or to be undertaken by the Government of India;\n(c) Supply;\n(d) The appropriation of the revenues of India;\n(e) The declaring of any expenditure to be expenditure charged on the revenues of India or the increasing of the amount of any such expenditure;\n(f) The receipt of money on account of the revenues of India or the custody or issue of such money or the audit of the accounts of the Government of India; or\n(g) Any matter incidental to any of the matters specified in items (a) to (f) of this clause.\n(2) A Bill shall not be deemed to be a Money Bill by reason only that it provides for the imposition of fines or other pecuniary penalties, or for the demand or payment of fees for licences or fees for services rendered or by reason that it provides for the imposition, abolition, remission, alteration or regulation of any tax by any local authority or body for local purposes.\n(3) If any question arises whether a Bill is a Money Bill or not, the decision of the Speaker of the House of the People thereon shall be final.\n(4) There shall be endorsed on every Money Bill when it is transmitted to the Council of States under the last preceding article, and when it is presented to the President for assent under the next succeeding article, the certificate of the Speaker of the House of the People signed by him that it is a Money Bill.", "debated": ["1949-05-20", "1949-06-08"], "adopted": "1949-06-08"}, "85": {"url": "https://www.constitutionofindia.net/articles/article-85-sessions-of-parliament-prorogation-and-dissolution/", "draft": "69", "draftText": "(1) The Houses of Parliament shall be summoned to meet twice at least in every year, and six months shall not intervene between their last sitting in one session and the date appointed for their first sitting in the next session.\n(2) Subject to the provisions of this article, the President may from time to time-\n(a) Summon the Houses or either House of Parliament to meet at such time and place as he thinks fit;\n(b) Prorogue the Houses;\n(c) Dissolve the House of the People.", "debated": ["1949-05-18"], "adopted": "1949-05-18"}, "86": {"url": "https://www.constitutionofindia.net/articles/article-86-right-of-president-to-address-and-send-messages-to-houses/", "draft": "70", "draftText": "(1) The President may address either House of Parliament or both Houses assembled together, and for that purpose require the attendance of members.\n(2) The President may send messages to either House of Parliament, whether with respect to a Bill then pending in Parliament or otherwise, and a House to which any message is so sent shall with all convenient despatch consider any matter required by the message to be taken into consideration.", "adopted": "1949-05-18"}, "111": {"url": "https://www.constitutionofindia.net/articles/article-111-assent-to-bills/", "draft": "91", "draftText": "When a Bill has been passed by the Houses of Parliament, it shall be presented to the President, and the President shall declare either that he assents to the Bill, or that he withholds assent therefrom:\nProvided that the President may, not later than six weeks after the presentation to him of a Bill for assent, return the Bill if it is not a Money Bill to the Houses with a message requesting that they will reconsider the Bill or any specified provision thereof, and, in particular, will consider the desirability of introducing any such amendments as he may recommend in his message, and the Houses shall reconsider the Bill accordingly.", "debated": ["1949-05-20"], "adopted": "1949-05-20"}, "87": {"url": "https://www.constitutionofindia.net/articles/article-87-special-address-by-the-president/", "draft": "71", "draftText": "(1) At the commencement of every session the President shall address both Houses of Parliament assembled together and inform Parliament of the causes of its summons.\n(2) Provision shall be made by the rules regulating the procedure of either House for the allotment of time for discussion of the matters referred to in such address and for the precedence of such discussion over other business of the House.", "debated": ["1949-05-18"]}, "88": {"url": "https://www.constitutionofindia.net/articles/article-88-rights-of-ministers-and-attorney-general-as-respects-houses/", "draft": "72", "draftText": "Every minister and the Attorney-General of India shall have the right to speak in, and otherwise to take part in the proceedings of, either House, any joint sitting of the Houses and any committee of Parliament of which he may be named a member, but shall not by virtue of this article be entitled to vote.", "debated": ["1949-05-18"]}, "89": {"url": "https://www.constitutionofindia.net/articles/article-89-the-chairman-and-deputy-chairman-of-the-council-of-states/", "draft": "73", "draftText": "(1) The Vice-President of India shall be ex-officio Chairman of the Council of States.\n(2) The Council of States shall, as soon as may be, choose a member of the Council to be Deputy Chairman thereof, and so often as the office of Deputy Chairman becomes vacant the Council shall choose another member to be Deputy Chairman thereof.", "debated": ["1949-05-19"]}, "90": {"url": "https://www.constitutionofindia.net/articles/article-90-vacation-and-resignation-of-and-removal-from-the-office-of-deputy-chairman/", "draft": "74", "draftText": "A member holding office as Deputy Chairman of the Council of States-\n(a) Shall vacate his office if he ceases to be a member of the Council;\n(b) May at any time, by writing under his hand addressed to the Chairman, resign his office; and\n(c) May be removed from his office for incapacity or want of confidence by a resolution of the Council passed by a majority of all the then members of the Council:\nProvided that no resolution for the purpose of clause (c) of this article shall be moved unless at least fourteen days' notice has been given of the intention to move the resolution.", "debated": ["1949-05-19"], "adopted": "1949-05-19"}, "112": {"url": "https://www.constitutionofindia.net/articles/article-112-annual-financial-statement/", "draft": "92", "draftText": "(1) The President shall in respect of every financial year cause to be laid before both the Houses of Parliament a statement of the estimated receipts and expenditure of the Government of India for that year, in this Part of this Constitution referred to as the \"annual financial statement\".\n(2) The estimates of expenditure embodied in the annual financial statement shall show separately-\n(a) The sums required to meet expenditure described by this Constitution as expenditure charged upon the revenues of India; and\n(b) The sums required to meet other expenditure proposed to be made from the revenues of India, and shall distinguish expenditure on revenue account from other expenditure.\n(3) The following expenditure shall be expenditure charged on the revenues of India-\n(a) The emoluments and allowances of the President and other expenditure relating to his office;\n(b) The emoluments and allowances of the Chairman and the Deputy Chairman of the Council of States and the Speaker and the Deputy Speaker of the House of the People;\n(c) Debt charges for which the Government of India is liable including interest, sinking fund charges and redemption charges, and other expenditure relating to the raising of loans and the service and redemption of debt;\n(d) (i) The salaries, allowances and pensions payable to or in respect of judges of the Supreme Court;\n(ii) The pensions payable to or in respect of judges of the Federal Court;\n(iii) The pensions payable to or in respect of judges of any High Court which exercises or immediately before the commencement of this Constitution exercised jurisdiction within any area included in the States for the time being specified in Parts I and II of the First Schedule;\n(e) Any sums required to satisfy any judgment, decree or award of any court or arbitral tribunal; and\n(f) Any other expenditure declared by this Constitution or by Parliament by law to be so charged.", "debated": ["1949-06-08", "1949-06-10", "1949-10-13"]}, "91": {"url": "https://www.constitutionofindia.net/articles/article-91-power-of-the-deputy-chairman-or-other-person-to-perform-the-duties-of-the-office-of-or-to-act-as-chairman/", "draft": "75", "draftText": "(1) While the office of Chairman is vacant, or during any period when the Vice-President is acting as, or discharging the functions of the, President under article 54 of this Constitution, the duties of the office shall be performed by the Deputy Chairman, or if the office of Deputy Chairman is also vacant, by such member of the Council of States as the President may appoint for the purpose.\n(2) During the absence of the Chairman from any sitting of the Council of States, the Deputy Chairman or, if he is also absent, such person as may be determined by the rules of procedure of the Council, or, if no such person is present, such other person as may be determined by the Council, shall act as Chairman.", "debated": ["1949-05-19"], "adopted": "1949-05-19"}, "113": {"url": "https://www.constitutionofindia.net/articles/article-113-procedure-in-parliament-with-respect-to-estimates/", "draft": "93", "draftText": "(1) So much of the estimates as relates to expenditure charged upon the revenues of India shall not be submitted to the vote of Parliament, but nothing in this clause shall be construed as preventing the discussion in either House of Parliament of any of these estimates.\n(2) So much of the said estimates as relates to other expenditure shall be submitted in the form of demands for grants to the House of the People and the House of the People shall have power to assent, or to refuse to assent to any demand, or to assent to any demand subject to a reduction of the amount specified therein.\n(3) No demand for a grant shall be made except on the recommendation of the President.", "debated": ["1949-06-10"], "adopted": "1949-06-10"}, "92": {"url": "https://www.constitutionofindia.net/articles/article-92-the-chairman-or-the-deputy-chairman-not-to-preside-while-a-resolution-for-his-removal-from-office-is-under-consideration/", "draft": "75A", "draftText": "At any sitting of the Council of States, while any resolution for the removal of the Vice-President from his office is under consideration, the Chairman, or while any resolution for the removal of the Deputy Chairman from his office is under consideration, the Deputy Chairman, shall not, though he is present, preside, and the provisions of clause (2) of the last preceding article shall apply in relation to every such sitting as they apply in relation to a sitting, from which the Chairman or, as the case may be, the Deputy Chairman, is absent.", "debated": ["1949-05-19"]}, "93": {"url": "https://www.constitutionofindia.net/articles/article-93-the-speaker-and-deputy-speaker-of-the-house-of-the-people/", "draft": "76", "draftText": "The House of the People shall, as soon as may be, choose two members of the House to be respectively Speaker and Deputy Speaker thereof, and, so often as the office of Speaker or Deputy Speaker becomes vacant, the House shall choose another member to be Speaker or Deputy Speaker, as the case may be.", "debated": ["1949-05-19"]}, "94": {"url": "https://www.constitutionofindia.net/articles/article-94-vacation-and-resignation-of-and-removal-from-the-offices-of-speaker-and-deputy-speaker/", "draft": "77", "draftText": "A member holding office as Speaker or Deputy Speaker of the House of the People-\n(a) Shall vacate his office if he ceases to be a member of the House of the People;\n(b) May at any time by writing under his hand addressed, if such member is the Speaker, to the Deputy Speaker, and if such member is the Deputy Speaker, to the Speaker, resign his office; and\n(c) May be removed from his office for incapacity or want of confidence by a resolution of the House of the People passed by a majority of all the then members of the House:\nProvided that no resolution for the purpose of clause (c) of this article shall be moved unless at least fourteen days' notice has been given of the intention to move the resolution:\nProvided further that, whenever the House of the People is dissolved, the Speaker shall not vacate his office until immediately before the first meeting of the House of the People after the dissolution.", "debated": ["1949-05-19"], "adopted": "1949-05-19"}, "95": {"url": "https://www.constitutionofindia.net/articles/article-95-power-of-the-deputy-speaker-or-other-person-to-perform-the-duties-of-the-office-of-or-to-act-as-speaker/", "draft": "78", "draftText": "(1) While the office of Speaker is vacant, the duties of the office shall be performed by the Deputy Speaker, or if the office of Deputy Speaker is also vacant, by such member of the House of the People as the President may appoint for the purpose.\n(2) During the absence of the Speaker from any sitting of the House of the People, the Deputy Speaker or, if he is also absent, such person as may be determined by the rules of procedure of the House, or, if no such person is present, such other person as may be determined by the House, shall act as Speaker.", "debated": ["1949-05-19"], "adopted": "1949-05-19"}, "114": {"url": "https://www.constitutionofindia.net/articles/article-114-appropriation-bills/", "draft": "94", "draftText": "(1) The President shall authenticate by his signature a schedule specifying-\n(a) The grants made by the House of the People under the last preceding article;\n(b) The several sums required to meet the expenditure charged on the revenues of India, but not exceeding in any case, the sum shown in the statement previously laid before Parliament.\n(2) The schedule so authenticated shall be laid before the House of the People, but shall not be open to discussion or vote in Parliament.\n(3) Subject to the provisions of the next two succeeding articles, no expenditure from the revenues of India shall be deemed to be duly authorised unless it is specified in the schedule so authenticated.", "debated": ["1949-06-10"], "adopted": "1949-06-10"}, "96": {"url": "https://www.constitutionofindia.net/articles/article-96-the-speaker-or-the-deputy-speaker-not-to-preside-while-a-resolution-for-his-removal-from-office-is-under-consideration/", "draft": "78A", "draftText": "At any sitting of the House of the people, while any resolution for the removal of the Speaker from his office is under consideration, the Speaker or while any resolution for the removal of the Deputy Speaker from his office is under consideration, the Deputy Speaker, shall not, though he is present, preside and the provisions of clause (2) of the last preceding article shall apply in relation to every such sitting as they apply in relation to a sitting from which the Speaker or, as the case may be, the Deputy Speaker, is absent.", "debated": ["1949-05-19"], "adopted": "1949-05-19"}, "97": {"url": "https://www.constitutionofindia.net/articles/article-97-salaries-and-allowances-of-the-chairman-and-deputy-chairman-and-the-speaker-and-deputy-speaker/", "draft": "79", "draftText": "There shall be paid to the Chairman and the Deputy Chairman of the Council of States, and to the Speaker and the Deputy Speaker of the House of the People, such salaries and allowances as may be respectively fixed by Parliament by law, and, until provision in that behalf is so made, such salaries and allowances as are specified in the Second Schedule.", "debated": ["1949-05-19"], "adopted": "1949-05-19"}, "98": {"url": "https://www.constitutionofindia.net/articles/article-98-secretariat-of-parliament/", "draft": "79A", "draftText": "(1) Each House of Parliament shall have a separate Secretarial Staff:\nProvided that nothing in this clause shall be construed as preventing the creation of posts common to both Houses of Parliament.\n(2)Parliament may by law regulate the recruitment, and the conditions of service of persons appointed, to the secretarial staff of either House of Parliament.\n(3)Until provision is made by Parliament under clause (2) of this article, the President may. after consultation with the Speaker of the House of the People or the Chairman of the Council of States, as the case may be, make rules regulating the recruitment and the conditions of service of persons appointed to the secretarial staff of the House of the People or the Council of States, and any rules so made shall have effect subject to the provisions of any law made under the said clause.", "debated": ["1949-07-30"], "adopted": "1949-07-30"}, "99": {"url": "https://www.constitutionofindia.net/articles/article-99-oath-or-affirmation-by-members/", "draft": "81", "draftText": "Every member of either House of Parliament shall, before taking his seat, make and subscribe before the President, or some person appointed in that behalf by him, a declaration according to the form set out for the purpose in the Third Schedule.", "debated": ["1949-05-19"]}, "100": {"url": "https://www.constitutionofindia.net/articles/article-100-voting-in-houses-power-of-houses-to-act-notwithstanding-vacancies-and-quorum/", "draft": "80", "draftText": "(1) Save as provided in this Constitution, all questions at any sitting or joint sitting of the Houses shall be determined by a majority of votes of the members present and voting, other than the Chairman or Speaker or person acting as such.\nThe Chairman or Speaker or person acting as such shall not vote in the first instance, but shall have and exercise a casting vote in the case of an equality of votes.\n(2) Either House of Parliament shall have power to act notwithstanding any vacancy in the membership thereof, and any proceedings in Parliament shall be valid notwithstanding that it is discovered subsequently that some person who was not entitled so to do sat or voted or otherwise took part in the proceedings.\n(3) If at any time during a meeting of a House, less than one-sixth of the total number of members of the House are present, it shall be the duty of the Chairman or Speaker or person acting as such either to adjourn the House, or to suspend the meeting until at least one-sixth of the members are present.", "debated": ["1949-05-19"], "adopted": "1949-05-19"}, "115": {"url": "https://www.constitutionofindia.net/articles/article-115-supplementary-additional-or-excess-grants/", "draft": "95", "draftText": "If in respect of any financial year further expenditure from the revenues of India becomes necessary over and above the expenditure theretofore authorised for that year, the President shall cause to be laid before both the Houses of Parliament a supplementary statement showing the estimated amount of that expenditure, and the provisions of the preceding articles shall have effect in relation to that statement and that expenditure as they have effect in relation to the annual financial statement and the expenditure mentioned therein.", "debated": ["1949-06-10"], "adopted": "1949-06-10"}, "101": {"url": "https://www.constitutionofindia.net/articles/article-101-vacation-of-seats/", "draft": "82", "draftText": "(1) No person shall be a member of both Houses of Parliament and provision shall be made by Parliament by law for the vacation by a person who is chosen a member of both Houses of his seat in one House or the other.\n(2) If a member of either House of Parliament-\n(a) Becomes subject to any of the disqualifications mentioned in clause (1) of the next succeeding article; or\n(b) Resigns his seat by writing under his hand addressed to the Chairman or the Speaker, as the case may be, his seat shall thereupon become vacant.\n(3) If for a period of sixty days a member of either House of Parliament is without permission of the House absent from all meetings thereof, the House may declare his seat vacant:\nProvided that in computing the said period of sixty days no account shall be taken of any period during which the House is prorogued or is adjourned for more than four consecutive days.", "debated": ["1949-05-19"]}, "102": {"url": "https://www.constitutionofindia.net/articles/article-102-disqualifications-for-membership/", "draft": "83", "draftText": "(1) A person shall be disqualified for being chosen as, and for being, a member of either House of Parliament-\n(a) If he holds any office of profit under the Government of India or the Government of any State other than an office declared by Parliament by law not to disqualify its holder;\n(b) If he is of unsound mind and stands so declared by a competent court;\n(c) If he is an un-discharged insolvent;\n(d) If he is under any acknowledgment of allegiance or adherence to a foreign power, or is a subject or a citizen or entitled to the rights or privileges of a subject or a citizen of a foreign power; and\n(e) If he is so disqualified by or under any law made by Parliament.\n(2) For the purposes of this article a person shall not be deemed to hold an office of profit under the Government of India or the Government of any State by reason only that-\n(a) He is a minister either for India or for any State for the time being specified in Part I of the First Schedule; or\n(b) He is a minister for any State for the time being specified in Part III of the First Schedule, if he is responsible to the Legislature of the State, or where there are two Houses of the Legislature of the State, to the Lower House of such Legislature and if not less than three-fourths of the members of such Legislature or House, as the case may be, are elected.", "debated": ["1949-05-19", "1949-10-13"]}, "103": {"url": "https://www.constitutionofindia.net/articles/article-103-decision-on-questions-as-to-disqualifications-of-members/", "draft": "83A", "draftText": "(1) If any question arises as to whether a member of either House of parliament has been subject to any of the disqualifications mentioned in clause (1) of the last preceding Article, the question shall be referred for the decision of the President and his decision shall be final.\n(2)Before giving any decision on any such question. The President shall obtain the opinion of the Election Commission and shall act according to such opinion.", "notDebated": true, "adopted": "1949-08-01"}, "104": {"url": "https://www.constitutionofindia.net/articles/article-104-penalty-for-sitting-and-voting-before-making-oath-or-affirmation-under-article-99-or-when-not-qualified-or-when-disqualified/", "draft": "84", "draftText": "If a person sits or votes as a member of either House of Parliament before he has complied with the requirements of article 81 of this Constitution, or when he knows that he is not qualified, or that he is disqualified for membership thereof, or that he is prohibited from so doing by the provisions of any law made by Parliament, he shall be liable in respect of each day on which he so sits or votes to a penalty of five hundred rupees to be recovered as a debt due to the Government of India.", "debated": ["1949-05-19"]}, "116": {"url": "https://www.constitutionofindia.net/articles/article-116-votes-on-account-votes-of-credit-and-exceptional-grants/", "draft": "96", "draftText": "If in any financial year expenditure from the revenues of India has been incurred on any service for which the vote of the House of the People is necessary in excess of the amount granted for that service and for that year, a demand for the excess shall be presented to the House of the People and the provisions of articles 93 and 94 of this Constitution shall have effect in relation to such demand as they have effect in relation to a demand for a grant.", "debated": ["1949-06-10"], "adopted": "1949-06-10"}, "105": {"url": "https://www.constitutionofindia.net/articles/article-105-powers-privileges-etc-of-the-houses-of-parliament-and-of-the-members-and-committees-thereof/", "draft": "85", "draftText": "(1) Subject to the rules and standing orders regulating the procedure of Parliament, there shall be freedom of speech in Parliament.\n(2) No member of Parliament shall be liable to any proceedings in any court in respect of anything said or any vote given by him in Parliament or any committee thereof, and no person shall be so liable in respect of the publication by or under the authority of either House of Parliament of any report, paper, votes or proceedings.\n(3) In other respects, the privileges and immunities of members of the Houses shall be such as may from time to time be defined by Parliament by law, and, until so defined, shall be such as are enjoyed by the members of the House of Commons of the Parliament of the United Kingdom at the commencement of this Constitution.\n(4) The provisions of clauses (1), (2) and (3) of this article shall apply in relation to persons who by virtue of this Constitution have the right to speak in, and otherwise take part in the proceedings of, a House of Parliament as they apply in relation to members of Parliament.", "debated": ["1949-05-19", "1949-10-16"]}, "117": {"url": "https://www.constitutionofindia.net/articles/article-117-special-provisions-as-to-financial-bills/", "draft": "97", "draftText": "(1) A Bill or amendment making provision for any of the matters specified in items (a) to (f) of clause (1) of article 90 of this Constitution shall not be introduced or moved except on the recommendation of the President and a Bill making such provision shall not be introduced in the Council of States:\nProvided that no recommendation shall be required under this clause for the moving of an amendment making provision for the reduction or abolition of any tax.\n(2) A Bill or amendment shall not be deemed to make provision for any of the matters aforesaid by reason only that it provides for the imposition of fines or other pecuniary penalties, or for the demand or payment of fees for licences or fees for services rendered or by reason that it provides for the imposition, abolition, remission, alteration or regulation of any tax by any local authority or body for local purposes.\n(3) A Bill which, if enacted and brought into operation, would involve expenditure from the revenues of India shall not be passed by either House of Parliament unless the President has recommended to that House the consideration of the Bill.", "debated": ["1949-06-10"], "adopted": "1949-06-10"}, "118": {"url": "https://www.constitutionofindia.net/articles/article-118-rules-of-procedure/", "draft": "98", "draftText": "(1) Each House of Parliament may make rules for regulating, subject to the provisions of this Constitution, its procedure and the conduct of its business.\n(2) Until rules are made under clause (1) of this article, the rules of procedure and standing orders in force immediately before the commencement of this Constitution with respect to the Legislature of the Dominion of India shall have effect in relation to Parliament subject to such modifications and adaptations as may be made therein by the Chairman of the Council of States or the Speaker of the House of the People, as the case may be.\n(3) The President, after consultation with the Chairman of the Council of States and the Speaker of the House of the People, may make rules as to the procedure with respect to joint sittings of, and communications between, the two Houses.\n(4) At a joint sitting of the two Houses the Speaker of the House of the People, or in his absence such person as may be determined by rules of procedure made under clause (3) of this article, shall preside.", "debated": ["1949-06-10"], "adopted": "1949-06-10"}, "106": {"url": "https://www.constitutionofindia.net/articles/article-106-salaries-and-allowances-of-members/", "draft": "86", "draftText": "Members of either House of Parliament shall be entitled to receive such salaries and allowances as may from time to time be determined by Parliament by law and, until provision in that respect is so made, allowances at such rates and upon such conditions as were immediately before the date of commencement of this Constitution applicable in the case of members of the Legislature of the Dominion of India.", "debated": ["1949-05-20"], "adopted": "1949-05-20"}, "119": {"url": "https://www.constitutionofindia.net/articles/article-119-regulation-by-law-of-procedure-in-parliament-in-relation-to-financial-business/", "draft": "98A", "draftText": "Parliament may, for the purpose of the timely completion of the financial business, regulate by law the procedure of and the conduct of business in, each house of Parliament in relation to any financial matter or to any Bill for appropriation of moneys out of the Consolidated Fund of India, and if and in so far as the provision of any law so made is inconsistent with any rule made by a House Parliament under the last preceding article or with any rule or standing order having effect in relation to Parliament under clause (2) of that article, such provision shall prevail.", "notDebated": true, "adopted": "1949-06-10"}, "107": {"url": "https://www.constitutionofindia.net/articles/article-107-provisions-as-to-introduction-and-passing-of-bills/", "draft": "87", "draftText": "(1) Subject to the provisions of articles 89 and 97 of this Constitution with respect to Money Bills and other financial Bills, a Bill may originate in either House of Parliament.\n(2) Subject to the provisions of articles 88 and 89 of this Constitution, a Bill shall not be deemed to have been passed by the Houses of Parliament unless it has been agreed to by both Houses, either without amendment or with such amendments only as are agreed to by both Houses.\n(3) A Bill pending in Parliament shall not lapse by reason of the prorogation of the Houses.\n(4) A Bill pending in the Council of States which has not been passed by the House of the People shall not lapse on a dissolution of the House of the People.\n(5) A Bill which is pending in the House of the People or which having been passed by the House of the People is pending in the Council of States shall, subject to the provisions of article 88 of this Constitution, lapse on a dissolution of the House of the People.", "debated": ["1949-05-20"], "adopted": "1949-05-20"}, "120": {"url": "https://www.constitutionofindia.net/articles/article-120-language-to-be-used-in-parliament/", "draft": "99", "draftText": "(1) In Parliament business shall be transacted in Hindi or English:\nProvided that the Chairman of the Council of States or the Speaker of the House of the People, as the case may be, may permit any member who cannot adequately express himself in either language to address the House in his mother tongue.\n(2) The Chairman of the Council of States or the Speaker of the House of the People may, whenever he thinks fit, make arrangements for making available in the Council of States or the House of the People, as the case may be, a summary in Hindi or English of the speech delivered by a member in any other language and such summary shall be included in the record of the proceedings of the House in which the speech has been delivered.", "debated": ["1949-09-17"], "adopted": "1949-09-17"}, "121": {"url": "https://www.constitutionofindia.net/articles/article-121-restriction-on-discussion-in-parliament/", "draft": "100", "draftText": "(1) No discussion shall take place in Parliament with respect to the conduct of any judge of the Supreme Court or a High Court in the discharge of his duties except upon a motion for presenting an address to the President praying for the removal of the judge as hereinafter provided.\n(2) In this article the reference to a High Court shall be construed as including a reference to any court in a State for the time being specified in Part III of the First Schedule which is a High Court for any of the purposes of Chapter IV of this Part.", "debated": ["1949-05-23", "1949-10-13"]}, "108": {"url": "https://www.constitutionofindia.net/articles/article-108-joint-sitting-of-both-houses-in-certain-cases/", "draft": "88", "draftText": "(1) If after a Bill has been passed by one House and transmitted to the other House-\n(a) The Bill is rejected by the other House; or\n(b) The Houses have finally disagreed as to the amendments to be made in the Bill; or\n(c) More than six months elapse from the date of the reception of the Bill by the other House without the Bill being passed by it,\nthe President may, unless the Bill has lapsed by reason of a dissolution of the House of the People, notify to the Houses by message if they are sitting or by public notification if they are not sitting, his intention to summon them to meet in a joint sitting for the purpose of deliberating and voting on the Bill:\nProvided that nothing in this clause shall apply to a Money Bill.\n(2) In reckoning any such period of six months as is referred to in clause (1) of this article, no account shall be taken of any time during which both Houses are prorogued or adjourned for more than four days.\n(3) Where the President has under clause (1) of this article notified his intention of summoning the Houses to meet in a joint sitting, neither House shall proceed further with the Bill, but the President may at any time after the date of his notification summon the Houses to meet in a joint sitting for the purpose specified in the notification and, if he does so, the Houses shall meet accordingly.\n(4) If at the joint sitting of the two Houses the Bill with such amendments, if any, as are agreed to in joint sitting, is passed by a majority of the total number of members of both Houses present and voting, it shall be deemed for the purposes of this Constitution to have been passed by both Houses:\nProvided that at a joint sitting-\n(a) If the Bill, having been passed by one House, has not been passed by the other House with amendments and returned to the House in which it originated, no amendment shall be proposed to the Bill other than such amendments (if any) as are made necessary by the delay in the passage of the Bill;\n(b) If the Bill has been so passed and returned, only such amendments as aforesaid shall be proposed to the Bill and such other amendments as are relevant to the matters with respect to which the Houses have not agreed; and the decision of the person presiding as to the amendments which are admissible under this clause shall be final.\n(5) A joint sitting may be held under this article and a Bill passed thereat, notwithstanding that a dissolution of the House of the People has intervened since the President notified his intention to summon the Houses to meet therein.", "debated": ["1949-05-20"]}, "122": {"url": "https://www.constitutionofindia.net/articles/article-122-courts-not-to-inquire-into-proceedings-of-parliament/", "draft": "101", "draftText": "(1) The validity of any proceedings in Parliament shall not be called in question on the ground of any alleged irregularity of procedure.\n(2) No officer or other member of Parliament in whom powers are vested by or under this Constitution for regulating procedure or the conduct of business, or for maintaining order, in Parliament shall be subject to the jurisdiction of any court in respect of the exercise by him of those powers.", "debated": ["1949-05-23"], "adopted": "1949-05-23"}, "84": {"url": "https://www.constitutionofindia.net/articles/article-84-qualification-for-membership-of-parliament/", "draft": "68A", "draftText": "A person shall not be qualified to be chosen to fill a seat in Parliament unless he-\n(a) is a citizen of India;\n(b) is, in the case of a seat in the Council of States, not less than thirty-five years of age and, in the case of a seat in the House of the People, not less than twenty-five years of age, and\n(c) possesses such other qualifications as may be prescribed in this behalf by or under any law made by Parliament."}, "124": {"url": "https://www.constitutionofindia.net/articles/article-124-establishment-and-constitution-of-supreme-court/", "draft": "103", "draftText": "(1) There shall be a Supreme Court of India consisting of a Chief Justice of India and such number of other judges not being less than seven as Parliament may by law prescribe.\n(2) Every judge of the Supreme Court shall be appointed by the President by warrant under his hand and seal after consultation with such of the judges of the Supreme Court and of the High Courts in the States as may be necessary for the purpose and shall hold office until he attains the age of sixty-five years:\nProvided that in the case of appointment of a judge, other than the Chief Justice, the Chief Justice of India shall always be consulted:\nProvided further that—\n(a) A judge may, by writing under his hand addressed to the President, resign his office;\n(b) A judge may be removed from his office in the manner provided in clause (4).\n(3) A person shall not be qualified for appointment as a judge of the Supreme Court unless he is a citizen of India and-\n(a) Has been for at least five years a judge of a High Court or of two or more such courts in succession; or\n(b) Has been for at least ten years an advocate of a High Court or of two or more such courts in succession.\nExplanation I:-In this clause 'High Court' means a High Court which exercises, or which before the commencement of this Constitution exercised, jurisdiction in any part of the territory of India.\nExplanation II:-In computing for the purpose of this clause the period during which a person has been an advocate, any period during which a person held judicial office after he became an advocate, shall be included.\n(4) A judge of the Supreme Court shall not be removed from his office except by an order of the President passed after an address supported by not less than two-thirds of the members present and voting has been presented to the President by both Houses of Parliament in the same session for such removal on the ground of proved misbehaviour or incapacity.\n(5) Parliament may by law regulate the procedure for the presentation of an address and for the investigation and proof of the misbehaviour or incapacity of a judge under the last preceding clause.\n(6) Every person appointed to be a judge of the Supreme Court shall, before he enters upon his office, make and subscribe before the President or some person appointed in that behalf by him a declaration according to the form set out for the purpose in the Third Schedule.\n(7) No person who has held office as a judge of the Supreme Court shall plead or act in any court or before any authority within the territory of India.", "debated": ["1949-05-24"], "adopted": "1949-05-24"}, "125": {"url": "https://www.constitutionofindia.net/articles/article-125-salaries-etc-of-judges/", "draft": "104", "draftText": "The judges of the Supreme Court shall be entitled to such salaries and allowances, and to such rights in respect of leave and pensions, as may from time to time be fixed by or under law made by Parliament, and until they are so fixed shall be entitled to such salaries, allowances and rights in respect of leave of absence or pension as are specified in the Second Schedule:\nProvided that neither the salary of a judge nor his rights in respect of leave of absence or pension shall be varied to his disadvantage after his appointment.", "debated": ["1949-07-30"], "adopted": "1949-07-30"}, "126": {"url": "https://www.constitutionofindia.net/articles/article-126-appointment-of-acting-chief-justice/", "draft": "105", "draftText": "When the office of Chief Justice of India is vacant or when the Chief Justice is, by reason of absence or otherwise, unable to perform the duties of his office, the duties of the office shall be performed by such one of the other judges of the court as the President may appoint for the purpose.", "debated": ["1949-05-27"], "adopted": "1949-05-27"}, "127": {"url": "https://www.constitutionofindia.net/articles/article-127-appointment-of-ad-hoc-judges/", "draft": "106", "draftText": "(1) If at any time there should not be a quorum of the judges of the Supreme Court available to hold or continue any session of the court, the Chief Justice may, after consultation with the Chief Justice of the High Court concerned, request in writing the attendance at the sittings of the court, as an ad hoc judge, for such period as may be necessary, of a judge of a High Court to be nominated by the Chief Justice of India.\n(2) It shall be the duty of the judge, who has been so nominated, in priority to other duties of his office, to attend the sittings of the Supreme Court at the time and for the period for which his attendance is required, and while so attending he shall have all the jurisdiction, powers and privileges, and shall discharge the duties, of a judge of the Supreme Court.", "debated": ["1949-05-27"], "adopted": "1949-05-27"}, "128": {"url": "https://www.constitutionofindia.net/articles/article-128-attendance-of-retired-judges-at-sittings-of-the-supreme-court/", "draft": "107", "draftText": "Notwithstanding anything contained in this Chapter, the Chief Justice of India may at any time, subject to the provisions of this article, request any person who has held the office of a judge of the Supreme Court or of the Federal Court to sit and act as a judge of the Supreme Court, and every such person so requested shall, while so sitting and acting, have all the jurisdiction, powers and privileges of, but shall not otherwise be deemed to be, a judge of that court:\nProvided that nothing in this article shall be deemed to require any such person as aforesaid to sit and act as a judge of that court unless he consents so to do.", "debated": ["1949-05-27"], "adopted": "1949-05-27"}, "130": {"url": "https://www.constitutionofindia.net/articles/article-130-seat-of-supreme-court/", "debated": ["1949-05-27"], "adopted": "1949-05-27", "draft": "108A"}, "129": {"url": "https://www.constitutionofindia.net/articles/article-129-supreme-court-to-be-a-court-of-record/", "draft": "108", "draftText": "The Supreme Court shall be a court of record and shall sit in Delhi and at such other place or places, if any, as the Chief Justice may, with the approval of the President, from time to time, appoint.", "debated": ["1949-05-27"], "adopted": "1949-05-27"}, "131": {"url": "https://www.constitutionofindia.net/articles/article-131-original-jurisdiction-of-the-supreme-court/", "draft": "109", "draftText": "Subject to the provisions of this Constitution, the Supreme Court shall, to the exclusion of any other Court, have original jurisdiction in any dispute-\n(a) Between the Government of India and one or more States, or\n(b) Between the Government of India and any State or States on one side and one or more other States on the other; or\n(c) Between two or more States, if in so far as the dispute involves any question (whether of law or fact) on which the existence or extent of a legal right depends:\nProvided that the said jurisdiction shall not extend to-\n(i) A dispute to which a State for the time being specified in Part III of the First Schedule is a party, if the dispute arises out of any provision of a treaty, agreement, engagement, sanad or other similar instrument which was entered into or executed before the date of commencement of this Constitution and has, or has been, continued in operation after that date;\n(ii) A dispute to which any State is a party, if the dispute arises out of any provision of a treaty, agreement, engagement, sanad or other similar instrument which provides that the said jurisdiction shall not extend to such a dispute.", "debated": ["1949-06-03", "1949-10-14"]}, "132": {"url": "https://www.constitutionofindia.net/articles/article-132-appellate-jurisdiction-of-supreme-court-in-appeals-from-high-courts-in-certain-cases/", "draft": "110", "draftText": "(1) An appeal shall lie to the Supreme Court from any judgment, decree or final order of a High Court in a State, whether in a civil, criminal or other proceeding, if the High Court certifies that the case involves a substantial question of law as to the interpretation of this Constitution.\n(2) Where the High Court has refused to give such a certificate, the Supreme Court may, if it is satisfied that the case involves a substantial question of law as to the interpretation of this Constitution, grant special leave to appeal from such judgment, decree or final order.\n(3) Where such a certificate is given, or such leave is granted, any party in the case may appeal to the Supreme Court not only on the ground that any such question as aforesaid has been wrongly decided, but also on any other ground.\nExplanation.-For the purposes of this article, the expression \"final order\" includes an order deciding an issue which, if decided in favour of the appellant, would be sufficient for the final disposal of the case.", "debated": ["1949-06-03"], "adopted": "1949-06-03"}, "133": {"url": "https://www.constitutionofindia.net/articles/article-133-appellate-jurisdiction-of-supreme-court-in-appeals-from-high-courts-in-regard-to-civil-matters/", "draft": "111", "draftText": "(1) An appeal shall lie to the Supreme Court from a judgment, decree or final order in a civil proceeding of a High Court in the territory of India except the States for the time being specified in Part III of the First Schedule, if the High Court certifies-\n(a) That the amount or value of the subject-matter of the dispute in the court of first instance and still in dispute on appeal was and is not less than twenty thousand rupees; or\n(b) That the judgment, decree or final order involves directly or indirectly some claim or question respecting property of the like amount or value; or\n(c) That the case is a fit one for appeal to the Supreme Court; and, where the judgment, decree or final order appealed from affirms the decision of the court immediately below, in any case other than one referred to in clause (c), if the High Court further certifies that the appeal involves some substantial question of law.\n(2) Notwithstanding anything contained in article 110 of this Constitution, any party appealing to the Supreme Court under clause (1) of this article may urge as one of the grounds in such appeal that the case involves a substantial question of law as to the interpretation of this Constitution which has been wrongly decided.", "debated": ["1949-06-03", "1949-06-06", "1949-10-16"]}, "237": {"url": "https://www.constitutionofindia.net/articles/article-237-application-of-the-provisions-of-this-chapter-to-certain-class-or-classes-of-magistrates/", "debated": ["1949-09-16"], "adopted": "1949-09-16", "draft": "209E"}, "151": {"url": "https://www.constitutionofindia.net/articles/article-151-audit-reports/", "draft": "127", "draftText": "The reports of the Auditor-General of India relating to the accounts of the Government of India shall be submitted to the President, who shall cause them to be laid before Parliament.", "debated": ["1949-05-30"], "adopted": "1949-05-30"}, "134": {"url": "https://www.constitutionofindia.net/articles/article-134-appellate-jurisdiction-of-supreme-court-in-regard-to-criminal-matters/", "debated": ["1949-06-13", "1949-06-14"], "adopted": "1949-06-14", "draft": "111A", "addedLater": true}, "149": {"url": "https://www.constitutionofindia.net/articles/article-149-duties-and-powers-of-the-comptroller-and-auditor-general/", "draft": "125", "draftText": "The Auditor-General shall perform such duties and exercise such powers in relation to the accounts of the Government of India and of the Government of any State as are or may be prescribed by or under any law made by Parliament.\nExplanation.-In this article the expression \"law made by Parliament\" includes any existing law for the time being in force in the territory of India.", "debated": ["1949-05-30"]}, "148": {"url": "https://www.constitutionofindia.net/articles/article-148-comptroller-and-auditor-general-of-india/", "draft": "124", "draftText": "(1) There shall be an Auditor-General of India, who shall be appointed by the President and shall only be removed from office in like manner and on the like grounds as a judge of the Supreme Court.\n(2) The salary, allowances and other conditions of service of the Auditor- General shall be such as may be determined by Parliament by law and until they are so determined shall be as specified in the Second Schedule:\nProvided that neither the salary of an Auditor-General nor his rights in respect of leave of absence, pension or age of retirement shall be varied to his disadvantage after his appointment.\n(3) The Auditor-General shall not be eligible for further office either under the Government of India or under the Government of any State after he has ceased to hold his office.\n(4) The salaries, allowances and pensions payable to or in respect of members of the staff of the Auditor-General shall be fixed by the Auditor- General in consultation with the President.\n(5) The salaries, allowances and pensions payable to or in respect of the Auditor-General and members of his staff shall be charged upon the revenues of India.", "debated": ["1949-05-30"], "adopted": "1949-05-30"}, "147": {"url": "https://www.constitutionofindia.net/articles/article-147-interpretation/", "debated": ["1949-06-06", "1949-10-16"], "adopted": "1949-10-16", "draft": "122A", "addedLater": true}, "150": {"url": "https://www.constitutionofindia.net/articles/article-150-form-of-accounts-of-the-union-and-of-the-states/", "draft": "126", "draftText": "The accounts of the Government of India shall be kept in such form as the Auditor-General of India may, with the approval of the President, prescribe and, in so far as the Auditor-General of India may, with the like approval, give any directions with regard to the methods or principles in accordance with which any accounts of the Government of any State ought to be kept, it shall be the duty of the Government of the State to cause accounts to be kept accordingly.", "debated": ["1949-05-30"], "adopted": "1949-05-30"}, "238": {"url": "https://www.constitutionofindia.net/articles/article-238-application-of-provisions-of-part-vi-to-states-in-part-b-of-the-first-schedule/", "addedLater": true}, "243": {"url": "https://www.constitutionofindia.net/articles/article-243-definitions/", "draft": "215", "draftText": "(1) Any territory specified in Part IV of the First Schedule and any other territory comprised within the territory of India but not specified in that Schedule shall be administered by the President acting, to such extent as he thinks fit, through a Chief Commissioner or other authority to be appointed by him.\n(2) The President may make regulations for the peace and good government of any such territory and any regulation so made may repeal or amend any law made by Parliament or any existing law which is for the time being applicable to such territory and, when promulgated by the President, shall have the same force and effect as an Act of Parliament which applies to such territory."}, "243A": {"url": "https://www.constitutionofindia.net/articles/article-243a-gram-sabha/", "notDebated": true}, "243O": {"url": "https://www.constitutionofindia.net/articles/article-243o-bar-to-interference-by-courts-in-electoral-matters/", "notDebated": true}, "243M": {"url": "https://www.constitutionofindia.net/articles/article-243m-part-not-to-apply-to-certain-areas/", "notDebated": true}, "243L": {"url": "https://www.constitutionofindia.net/articles/article-243l-application-to-union-territories/", "notDebated": true}, "243K": {"url": "https://www.constitutionofindia.net/articles/article-243k-elections-to-the-panchayats/", "notDebated": true}, "243J": {"url": "https://www.constitutionofindia.net/articles/article-243j-audit-of-accounts-of-panchayats/", "notDebated": true}, "243I": {"url": "https://www.constitutionofindia.net/articles/article-243i-constitution-of-finance-commission-to-review-financial-position/", "notDebated": true}, "243H": {"url": "https://www.constitutionofindia.net/articles/article-243h-powers-to-impose-taxes-by-and-funds-of-the-panchayats/", "notDebated": true}, "243G": {"url": "https://www.constitutionofindia.net/articles/article-243g-powers-authority-and-responsibilities-of-panchayats/", "notDebated": true}, "243F": {"url": "https://www.constitutionofindia.net/articles/article-243f-disqualifications-for-membership/", "notDebated": true}, "243E": {"url": "https://www.constitutionofindia.net/articles/article-243e-duration-of-panchayats-etc/", "notDebated": true}, "243D": {"url": "https://www.constitutionofindia.net/articles/article-243d-reservation-of-seats/", "notDebated": true}, "243C": {"url": "https://www.constitutionofindia.net/articles/article-243c-composition-of-panchayats/", "notDebated": true}, "243B": {"url": "https://www.constitutionofindia.net/articles/article-243b-constitution-of-panchayats/", "notDebated": true}, "239": {"url": "https://www.constitutionofindia.net/articles/article-239-administration-of-union-territories/", "notDebated": true}, "243P": {"url": "https://www.constitutionofindia.net/articles/article-243p-definitions/", "notDebated": true}, "243Q": {"url": "https://www.constitutionofindia.net/articles/article-243q-constitution-of-municipalities/", "notDebated": true}, "243R": {"url": "https://www.constitutionofindia.net/articles/article-243r-composition-of-municipalities/", "notDebated": true}, "243T": {"url": "https://www.constitutionofindia.net/articles/article-243t-reservation-of-seats/", "notDebated": true}, "243U": {"url": "https://www.constitutionofindia.net/articles/article-243u-duration-of-municipalities-etc/", "notDebated": true}, "243V": {"url": "https://www.constitutionofindia.net/articles/article-243v-disqualifications-for-membership/", "notDebated": true}, "239A": {"url": "https://www.constitutionofindia.net/articles/article-239a-creation-of-local-legislatures-or-council-of-ministers-or-both-for-certain-union-territories/"}, "243W": {"url": "https://www.constitutionofindia.net/articles/article-243w-powers-authority-and-responsibilities-of-municipalities-etc/", "notDebated": true}, "243X": {"url": "https://www.constitutionofindia.net/articles/article-243x-power-to-impose-taxes-by-and-funds-of-the-municipalities/", "notDebated": true}, "243Y": {"url": "https://www.constitutionofindia.net/articles/article-243y-finance-commission/", "notDebated": true}, "243Z": {"url": "https://www.constitutionofindia.net/articles/article-243z-audit-of-accounts-of-municipalities/", "notDebated": true}, "239AA": {"url": "https://www.constitutionofindia.net/articles/article-239aa-special-provisions-with-respect-to-delhi/"}, "239AB": {"url": "https://www.constitutionofindia.net/articles/article-239ab-provision-in-case-of-failure-of-constitutional-machinery/"}, "243ZA": {"url": "https://www.constitutionofindia.net/articles/article-243za-elections-to-the-municipalities/", "notDebated": true}, "243ZB": {"url": "https://www.constitutionofindia.net/articles/article-243zb-application-to-union-territories/", "notDebated": true}, "243ZC": {"url": "https://www.constitutionofindia.net/articles/article-243zc-part-not-to-apply-to-certain-areas/", "notDebated": true}, "243ZD": {"url": "https://www.constitutionofindia.net/articles/article-243zd-committee-for-district-planning/", "notDebated": true}, "243ZE": {"url": "https://www.constitutionofindia.net/articles/article-243ze-committee-for-metropolitan-planning/", "notDebated": true}, "243ZF": {"url": "https://www.constitutionofindia.net/articles/article-243zf-continuance-of-existing-laws-and-municipalities/", "notDebated": true}, "243ZG": {"url": "https://www.constitutionofindia.net/articles/article-243zg-bar-to-interference-by-courts-in-electoral-matters/", "notDebated": true}, "239B": {"url": "https://www.constitutionofindia.net/articles/article-239b-power-of-administrator-to-promulgate-ordinances-during-recess-of-legislature/"}, "243ZH": {"url": "https://www.constitutionofindia.net/articles/article-243zh-definitions/", "notDebated": true}, "243ZI": {"url": "https://www.constitutionofindia.net/articles/article-243zi-incorporation-of-co-operative-societies/", "notDebated": true}, "243ZJ": {"url": "https://www.constitutionofindia.net/articles/article-243zj-number-and-term-of-members-of-board-and-its-office-bearers/", "notDebated": true}, "243ZK": {"url": "https://www.constitutionofindia.net/articles/article-243zk-election-of-members-of-board/", "notDebated": true}, "243ZL": {"url": "https://www.constitutionofindia.net/articles/article-243zl-supersession-and-suspension-of-board-and-interim-management/", "notDebated": true}, "243ZM": {"url": "https://www.constitutionofindia.net/articles/article-243zm-audit-of-accounts-of-co-operative-societies/", "notDebated": true}, "243ZN": {"url": "https://www.constitutionofindia.net/articles/article-243zn-convening-of-general-body-meetings/", "notDebated": true}, "243ZO": {"url": "https://www.constitutionofindia.net/articles/article-243zo-right-of-a-member-to-get-information/", "notDebated": true}, "243ZP": {"url": "https://www.constitutionofindia.net/articles/article-243zp-returns/", "notDebated": true}, "240": {"url": "https://www.constitutionofindia.net/articles/article-240-power-of-president-to-make-regulations-for-certain-union-territories/", "notDebated": true}, "243ZQ": {"url": "https://www.constitutionofindia.net/articles/article-243zq-offences-and-penalties/", "notDebated": true}, "243ZR": {"url": "https://www.constitutionofindia.net/articles/article-243zr-application-to-multi-state-co-operative-societies/", "notDebated": true}, "243ZS": {"url": "https://www.constitutionofindia.net/articles/article-243zs-application-to-union-territories/", "notDebated": true}, "243ZT": {"url": "https://www.constitutionofindia.net/articles/article-243zt-continuance-of-existing-laws/", "notDebated": true}, "241": {"url": "https://www.constitutionofindia.net/articles/article-241-high-courts-for-union-territories/", "debated": ["1949-08-02"], "adopted": "1949-10-16", "draft": "213A"}, "244": {"url": "https://www.constitutionofindia.net/articles/article-244-administration-of-scheduled-areas-and-tribal-areas/", "draft": "215B", "draftText": "(1) The provisions of the Fifth Schedule shall apply to the administration and control of the scheduled areas and scheduled tribes in any State for the time being specified in Part I or Part III of the First Schedule other than the State of Assam.\n(2) The provisions of the Sixth Schedule shall apply to the administration of the tribunal is in the State of Assam.", "debated": ["1949-08-19"]}, "244A": {"url": "https://www.constitutionofindia.net/articles/article-244a-formation-of-an-autonomous-state-comprising-certain-tribal-areas-in-assam-and-creation-of-local-legislature-or-council-of-ministers-or-both-therefor/", "notDebated": true}, "242": {"url": "https://www.constitutionofindia.net/articles/article-242-coorg/", "draft": "214", "draftText": "Until other provision is made in this behalf by the President, the constitution, powers and functions of the Coorg Legislative Council and the arrangements with respect to revenues collected in Coorg and expenses in respect of Coorg shall remain unchanged."}, "361": {"url": "https://www.constitutionofindia.net/articles/article-361-protection-of-president-and-governors-and-rajpramukhs/", "draft": "302", "draftText": "(1) The President or the Governor of a State shall not be answerable to any court for the exercise and performance of the powers and duties of his office or for any act done or purporting to be done by him in the exercise and performance of those powers and duties:\nProvided that the conduct of the President may be brought under review by any court, tribunal or body appointed or designated by either House of Parliament for the investigation of a charge under article 50 of this Constitution:\nProvided further that nothing in this clause shall be construed as restricting the right of any person to bring against the Government of India or the Government of a State such proceedings as are mentioned in Chapter III of Part X of this Constitution.\n(2) No criminal proceedings whatsoever shall be instituted or continued against the President or the Governor of a State in any court during his term of office.\n(3) No process for the arrest or imprisonment of the President or the Governor of a State shall issue from any court during his term of office.\n(4) No civil proceedings in which relief is claimed against the President or the Governor of a State shall be instituted during his term of office in any court in respect of any act done or purporting to be done by him in his personal capacity, whether before or after he entered upon his office as President or Governor of such State, until the expiration of two months next after notice in writing has been delivered to the President or the Governor, as the case may be, or left at his office stating the nature of the proceedings, the cause of action therefor, the name, description and place of residence of the party by whom such proceedings are to be instituted and the relief which he claims.", "debated": ["1949-09-08"], "adopted": "1949-09-08"}, "361A": {"url": "https://www.constitutionofindia.net/articles/article-361a/"}, "361B": {"url": "https://www.constitutionofindia.net/articles/article-361b-disqualification-for-appointment-on-remunerative-political-post/"}, "363": {"url": "https://www.constitutionofindia.net/articles/article-363-bar-to-interference-by-courts-in-disputes-arising-out-of-certain-treaties-agreements-etc/", "draft": "302A", "draftText": "(1) Notwithstanding anything contained in this Constitution and subject to the provisions of article 119 thereof, neither the Supreme Court nor any other court shall have jurisdiction in any dispute arising out of any provision of a treaty, agreement, covenant, engagement, sanad or other similar instrument which was entered into by any Ruler of an Indian State and to which the Government of the Dominion of India or any of its predecessor Governments was a party and which has or has been continued in operation after the date of commencement of this Constitution, or in any dispute in respect of any right accruing under any of the provisions of this Constitution relating to any such treaty, agreement, covenant engagement, sanad or other similar instrument.\n(2) In this article–\n(a) \"Indian State\"means any territory recognised by His Majesty or the Government of the Dominion of India as being such a State; and\n(b) \"Ruler\" includes, the Prince, Chief or other person recognised by His Majesty or the Government of the Dominion of India as the Ruler of any Indian State."}, "355": {"url": "https://www.constitutionofindia.net/articles/article-355-duty-of-the-union-to-protect-states-against-external-aggression-and-internal-disturbance/", "adopted": "1949-08-04"}, "364": {"url": "https://www.constitutionofindia.net/articles/article-364-special-provisions-as-to-major-ports-and-aerodromes/", "debated": ["1949-10-17"], "adopted": "1949-10-17"}, "356": {"url": "https://www.constitutionofindia.net/articles/article-356-provisions-in-case-of-failure-of-constitutional-machinery-in-states/", "draft": "278", "draftText": "(1) If the President, on receipt of a proclamation issued by the Governor of a State under article 188 of this Constitution, is satisfied that a situation has arisen in which the government of the State cannot be carried on in accordance with the provisions of this Constitution, he may by proclamation-\n(a) Assume to himself all or any of the functions of the Government of the State and all or any of the powers vested in or exercisable by the Governor or any body or authority in the State other than the Legislature of the State;\n(b) Declare that the powers of the Legislature of the State shall be exercisable only by Parliament; and any such proclamation may contain such incidental and consequential provisions as may appear to him to be necessary or desirable for giving effect to the objects of the proclamation, including provisions for suspending in whole or in part the operation of any provisions of this Constitution relating to any body or authority in that State:\nProvided that nothing in this clause shall authorise the President to assume to himself any of the powers vested in or exercisable by a High Court or to suspend, either in whole or in part, the operation of any provision of this Constitution relating to High Courts.\n(2) Any such proclamation may be revoked or varied by a subsequent proclamation.\n(3) A proclamation under this article-\n(a) Shall be laid before each House of Parliament;\n(b) Except where it is a proclamation revoking a previous proclamation, shall cease to operate at the expiration of six months:\nProvided that, if and so often as a resolution approving the continuance in force of such a proclamation is passed by both Houses of Parliament, the proclamation shall, unless revoked, continue in force for a further period of twelve months from the date on which under this clause it would otherwise have ceased to operate, but no such proclamation shall in any case remain in force for more than three years.\n(4) Where by a proclamation issued under clause (1) of this article it has been declared that the powers of the Legislature of the State shall be exercisable only by Parliament, it shall be competent-\n(a) For Parliament to make laws conferring powers and imposing duties, or authorising the conferring of powers and the imposition of duties, upon the Government of India or officers and authorities of the Government of India;\n(b) For the President to promulgate Ordinances under article 102 of this Constitution except when both Houses of Parliament are in session.\n(5) Any law made by Parliament which Parliament would not but for the issue of a proclamation under this article have been competent to make shall to the extent of the incompetency cease to have effect on the expiration of a period of one year after the proclamation has ceased to operate, except as respects things done or omitted to be done before the expiration of the said period unless the provisions which shall so cease to have effect are sooner repealed or re-enacted with or without modification by Act of the Legislature of the State.", "debated": ["1949-08-03", "1949-08-04"], "adopted": "1949-08-04"}, "366": {"url": "https://www.constitutionofindia.net/articles/article-366-definitions/", "draft": "303", "draftText": "(1) In this Constitution, unless the context otherwise requires, the following expressions have the meanings hereby respectively assigned to them, that is to say-\n(a) \"Agricultural income\" means agricultural income as defined for the purposes of the enactments relating to Indian income-tax;\n(b) \"An Anglo-Indian\" means a person whose father or any of whose other male progenitors in the male line is or was of European descent but who is domiciled within the territory of India and is or was born within such territory of parents habitually resident therein and not established there for temporary purposes only;\n(c) \"An Indian Christian\" means a person who professes any form of the Christian religion and is not a European or an Anglo-Indian;\n(d) \"Borrow\" includes the raising of money by the grant of annuities, and \"loan\" shall be construed accordingly;\n(e) \"Chief Justice\" includes in relation to a High Court a Chief Judge;\n(f) \"Corporation tax\" means any tax on income, so far as that tax is payable by companies and is a tax in the case of which the following conditions are fulfilled: –\n(i) That it is not chargeable in respect of agricultural income;\n(ii) That no deduction in respect of the tax paid by companies is, by any enactments which may apply to the tax, authorised to be made from dividends payable by the companies to individuals\n(iii) That no provision exists for taking the tax so paid into account in computing for the purposes of Indian income-tax the total income of individuals receiving such dividends, or in computing the Indian income-tax payable by, or refundable to, such individuals;\n(g) \"Corresponding Province\" or \"corresponding State\" means in cases of doubt such Province or State as may be determined by the President to be the corresponding Province or, as the case may be, the corresponding State for the particular purpose in question;\n(h) \"Debt\" includes any liability in respect of any obligation to repay capital sums by way of annuities and any liability under any guarantee, and \"debt charges\" shall be construed accordingly;\n(i) \"Existing law\" means any law, Ordinance, order, bye-law, rule or regulation passed or made before the commencement of this Constitution by any legislature, authority or person having power to make such a law, Ordinance, order, bye-law, rule or regulation but does not include any Act of Parliament of the United Kingdom or any Order in Council made under any such Act;\n(j) \"Federal Court\" means the Federal Court constituted under the Government of India Act, 1935;\n(k) \"Goods\" includes all materials, commodities, and articles; (1) \"Guarantee\" includes any obligation undertaken before the commencement of this Constitution to make payments in the event of the profits of an undertaking falling short of a specified amount;\n(m) \"Pension\" means a pension, whether contributory or not, of any kind whatsoever payable to or in respect of any person, and includes retired pay so payable, a gratuity so payable and any sum or sums so payable by way of the return, with or without interest thereon or any other addition thereto, of subscriptions to a provident fund;\n(n) \"Public notification\" means a notification in the Gazette of India, or, as the case may be, the official Gazette of a State;\n(o) \"Securities\" includes stock;\n(p) \"Taxation\" includes the imposition of any tax or impost, whether general or local or special, and \"tax\" shall be construed accordingly;\n(q) \"Tax on income\" includes a tax in the nature of an excess profits tax\n(r) \"Railway\" includes a tramway not wholly within a municipal area;\n(s) \"Union railway\" does not include an Indian State railway but, save as aforesaid, includes any railway not being a minor railway;\n(t) \"Indian State railway\" means a railway owned by a State for the time being specified in Part III of the First Schedule and either operated by such State, or operated on behalf of such State otherwise than in accordance with a contract made with that State by or on behalf of the Government of India, or any company operating a Union railway;\n(u) \"Minor railway\" means a railway which is wholly situate in one State and does not form a continuous line of communication with a Union railway, whether of the same gauge or not;\n(v) \"Schedule\" means a Schedule to this Constitution;\n(w) \"Scheduled Castes\" means in relation to any State for the time being specified in Part I of the First Schedule such castes, races or tribes or parts of or groups within castes, races or tribes as are specified in the Government of India (Scheduled Castes) Order, 1936, to be scheduled castes for the purposes of the Fifth and Sixth Schedules to the Government of India Act. 1935, in relation to the corresponding Province;\n(x) \"Scheduled tribes\" means the tribes or communities specified in Parts I to IX of the Eighth Schedule in relation to the States for the time being specified in Part I of the First Schedule to which those Parts respectively relate.", "debated": ["1949-09-16", "1949-09-17", "1949-10-14"]}, "369": {"url": "https://www.constitutionofindia.net/articles/article-369-temporary-power-to-parliament-to-make-laws-with-respect-to-certain-matters-in-the-state-list-as-if-they-were-matters-in-the-concurrent-list/", "draft": "306", "draftText": "Notwithstanding anything in this Constitution, Parliament shall, during a period of five years from the commencement of this Constitution, have power to make laws with respect to the following matters as if they were enumerated in the Concurrent List, namely:-\n(a) Trade and commerce within a State in, and the production, supply and distribution of, cotton and woollen textiles, paper (including newsprint), foodstuffs (including edible oil-seeds and oil), petroleum and petroleum products, spare parts of mechanically propelled vehicles, coal, iron, steel and mica\n(b) Relief and rehabilitation of displaced persons;\n(c) Offences against laws with respect to any of the matters mentioned in clauses (a) and (b) of this article, inquiries and statistics for the purposes of any of those matters, jurisdiction and powers of all courts except the Supreme Court with respect to any of those matters, and fees in respect of any of those matters but not including fees taken in any court; but any law made by Parliament, which Parliament would not but for the provisions of this article have been competent to make, shall to the extent of the incompetency cease to have effect on the expiration of the said period except as respects things done or omitted to be done before the expiration thereof.", "debated": ["1949-10-07"], "adopted": "1949-10-07"}, "370": {"url": "https://www.constitutionofindia.net/articles/article-370-temporary-provisions-with-respect-to-the-state-of-jammu-and-kashmir/", "debated": ["1949-10-17"], "addedLater": true}, "371": {"url": "https://www.constitutionofindia.net/articles/article-371-special-provision-with-respect-to-the-states-of-maharashtra-and-gujarat/", "debated": ["1949-10-13"], "adopted": "1949-10-13"}, "371A": {"url": "https://www.constitutionofindia.net/articles/article-371a-special-provision-with-respect-to-the-state-of-nagaland/"}, "371B": {"url": "https://www.constitutionofindia.net/articles/article-371b-special-provision-with-respect-to-the-state-of-assam/"}, "371C": {"url": "https://www.constitutionofindia.net/articles/article-371c-special-provision-with-respect-to-the-state-of-manipur/"}, "371D": {"url": "https://www.constitutionofindia.net/articles/article-371d-special-provisions-with-respect-to-the-state-of-andhra-pradesh-or-the-state-of-telangana/"}, "371E": {"url": "https://www.constitutionofindia.net/articles/article-371e-establishment-of-central-university-in-andhra-pradesh/"}, "371F": {"url": "https://www.constitutionofindia.net/articles/article-371f-special-provisions-with-respect-to-the-state-of-sikkim/"}, "371G": {"url": "https://www.constitutionofindia.net/articles/article-371g-special-provision-with-respect-to-the-state-of-mizoram/"}, "371H": {"url": "https://www.constitutionofindia.net/articles/article-371h-special-provision-with-respect-to-the-state-of-arunachal-pradesh/"}, "372": {"url": "https://www.constitutionofindia.net/articles/article-372-continuance-in-force-of-existing-laws-and-their-adaptation/", "draft": "307", "draftText": "(1) Subject to the other provisions of this Constitution, all the law in force in the territory of India immediately before the commencement of this Constitution shall continue in force therein until altered or repealed or amended by a competent Legislature or other competent authority.\n(2) The President may, by Order, provide that, as from such date as may be specified in the Order, any law in force in the territory of India or in any part of such territory shall, until repealed or amended by a competent Legislature or other competent authority, have effect subject to such adaptations and modifications, whether by way of repeal or amendment, as appear to him to be necessary or expedient for bringing the provisions of that law into accord with the provisions of this Constitution and any such adaptation or modification shall not be questioned in any court of law.\nExplanation I.-The expression \"law in force\" in this article shall include a law passed or made by a Legislature or other competent authority in the territory of India before the commencement of this Constitution and not previously repealed, notwithstanding that it or parts of it may not be then in operation either at all or in particular areas.\nExplanation II.-Any law passed or made by a Legislature or other competent authority in the territory of India which immediately before the commencement of this Constitution has extra territorial effect as well as effect in the territory of India shall, subject to any such adaptations and modifications as aforesaid, continue to have extra-territorial effect.\nExplanation III.-Nothing in this article shall be construed as continuing any temporary Act in force beyond the date fixed for its expiration.", "debated": ["1949-10-10"]}, "372A": {"url": "https://www.constitutionofindia.net/articles/article-372a-power-of-the-president-to-adapt-laws/"}, "374": {"url": "https://www.constitutionofindia.net/articles/article-374-provisions-as-to-judges-of-the-federal-court-and-proceedings-pending-in-the-federal-court-or-before-his-majesty-in-council/", "debated": ["1949-10-10"], "adopted": "1949-10-10"}, "375": {"url": "https://www.constitutionofindia.net/articles/article-375-courts-authorities-and-officers-to-continue-to-function-subject-to-the-provisions-of-the-constitution/", "draft": "309", "draftText": "All courts of civil, criminal and revenue jurisdiction, all authorities and all officers, judicial, executive and ministerial, throughout the territory of India shall continue to exercise their respective functions subject to the provisions of this Constitution.", "debated": ["1949-10-07"]}, "376": {"url": "https://www.constitutionofindia.net/articles/article-376-provisions-as-to-judges-of-high-courts/", "debated": ["1949-10-10"], "adopted": "1949-10-10"}, "377": {"url": "https://www.constitutionofindia.net/articles/article-377-provisions-as-to-comptroller-and-auditor-general-of-india/", "adopted": "1949-10-07"}, "378A": {"url": "https://www.constitutionofindia.net/articles/article-378a-special-provision-as-to-duration-of-andhra-pradesh-legislative-assembly/"}, "393": {"url": "https://www.constitutionofindia.net/articles/article-393-short-title/", "debated": ["1949-10-17"], "adopted": "1949-10-17"}, "360": {"url": "https://www.constitutionofindia.net/articles/article-360-provisions-as-to-financial-emergency/", "addedLater": true}, "395": {"url": "https://www.constitutionofindia.net/articles/article-395-repeals/", "draft": "315", "draftText": "The Indian Independence Act, 1947, and the Government of India Act, 1935, including the India (Central Government and Legislature) Act, 1946, and all other enactments amending or supplementing the Government of India Act, 1935, shall cease to have effect.", "debated": ["1949-10-17"], "adopted": "1949-10-17"}, "357": {"url": "https://www.constitutionofindia.net/articles/article-357-exercise-of-legislative-powers-under-proclamation-issued-under-article-356/", "debated": ["1949-08-03", "1949-08-04"], "adopted": "1949-08-04"}, "359A": {"url": "https://www.constitutionofindia.net/articles/article-359a-application-of-this-part-to-the-state-of-punjab/"}, "359": {"url": "https://www.constitutionofindia.net/articles/article-359-suspension-of-the-enforcement-of-the-rights-conferred-by-part-iii-during-emergencies/", "debated": ["1949-08-04", "1949-08-20"]}, "358": {"url": "https://www.constitutionofindia.net/articles/article-358-suspension-of-provisions-of-article-19-during-emergencies/", "draft": "279", "draftText": "While a Proclamation of Emergency is in operation, nothing in article 13 of Part III of this Constitution shall restrict the power of the State as defined in that Part to make any law or to take any executive action which the State would otherwise be competent to make or to take.", "debated": ["1949-08-04"], "adopted": "1949-08-04"}, "350B": {"url": "https://www.constitutionofindia.net/articles/article-350b-special-officer-for-linguistic-minorities/"}, "350A": {"url": "https://www.constitutionofindia.net/articles/article-350a-facilities-for-instruction-in-mothertongue-at-primary-stage/"}, "342A": {"url": "https://www.constitutionofindia.net/articles/article-342a-socially-and-educationally-backward-classes/"}, "378": {"url": "https://www.constitutionofindia.net/articles/article-378-provisions-as-to-public-service-commissions/", "adopted": "1949-10-07", "addedLater": true}, "380": {"url": "https://www.constitutionofindia.net/articles/article-380-provision-as-to-president-omitted/"}, "381": {"url": "https://www.constitutionofindia.net/articles/article-381-council-of-ministers-of-the-president-omitted/"}, "382": {"url": "https://www.constitutionofindia.net/articles/article-382-provisions-as-to-provisional-legislatures-for-states-in-part-a-of-the-first-schedule-omitted/"}, "383": {"url": "https://www.constitutionofindia.net/articles/article-383-provision-as-to-governors-of-provinces-omitted/"}, "384": {"url": "https://www.constitutionofindia.net/articles/article-384-council-of-ministers-of-the-governors-omitted/"}, "385": {"url": "https://www.constitutionofindia.net/articles/article-385-provision-as-to-provisional-legislatures-in-states-in-part-b-of-the-first-schedule-omitted/"}, "386": {"url": "https://www.constitutionofindia.net/articles/article-386-council-of-ministers-for-states-in-part-b-of-the-first-schedule-omitted/"}, "387": {"url": "https://www.constitutionofindia.net/articles/article-387-special-provision-as-to-determination-of-population-for-the-purposes-of-certain-elections-omitted/"}, "388": {"url": "https://www.constitutionofindia.net/articles/article-388-provisions-as-to-the-filling-of-casual-vacancies-in-the-provisional-parliament-and-provisional-legislatures-of-the-states-omitted/"}, "389": {"url": "https://www.constitutionofindia.net/articles/article-389-provision-as-to-bills-pending-in-the-dominion-legislatures-and-in-the-legislatures-of-provinces-and-indian-states-omitted/"}, "390": {"url": "https://www.constitutionofindia.net/articles/article-390-money-received-or-raised-or-expenditure-incurred-between-the-commencement-of-the-constitution-and-the-31st-day-of-march-1950-omitted/"}, "222": {"url": "https://www.constitutionofindia.net/articles/article-222-transfer-of-a-judge-from-one-high-court-to-another/", "draft": "198", "draftText": "(1) When the office of Chief Justice of a High Court is vacant or when any such Chief Justice is, by reason of absence or otherwise, unable to perform the duties of his office, the duties of the office shall be performed by such one of the other judges of the court as the President may appoint for the purpose.\n(2) (a) When the office of any other judge of a High Court is vacant or when any such judge is appointed to act temporarily as a Chief Justice, or is unable to perform the duties of his office by reason of absence or otherwise, the President may appoint a person duly qualified for appointment as a judge to act as a judge of that court.\n(b) The person appointed shall, while so acting, be deemed to be a judge of the court.\n(c) Nothing contained in this clause shall prevent the President from revoking any appointment made under this clause."}, "362": {"url": "https://www.constitutionofindia.net/articles/article-362/"}, "363A": {"url": "https://www.constitutionofindia.net/articles/article-363a-recognition-granted-to-rulers-of-indian-states-to-cease-and-privy-purses-to-be-abolished/"}, "365": {"url": "https://www.constitutionofindia.net/articles/article-365-effect-of-failure-to-comply-with-or-to-give-effect-to-directions-given-by-the-union/"}, "367": {"url": "https://www.constitutionofindia.net/articles/article-367-interpretation/"}, "373": {"url": "https://www.constitutionofindia.net/articles/article-373-power-of-president-to-make-order-in-respect-of-persons-under-preventive-detention-in-certain-cases/"}, "379": {"url": "https://www.constitutionofindia.net/articles/article-379-provisions-as-to-provisional-parliament-and-the-speaker-and-deputy-speaker-thereof-omitted/", "draft": "311", "draftText": "(1) Until both Houses of Parliament have been duly constituted and summoned to meet for the first session under this Constitution, the Constituent Assembly of the Dominion of India shall itself exercise all the powers and perform all the duties conferred on Parliament and may in particular make law for securing the due constitution of the two Houses of Parliament and for providing for all matters relating to or connected with elections to either House of Parliament including the delimitation of constituencies and for such other ancillary and consequential matters as may be deemed necessary for the purpose of giving effect to the provisions of this Constitution.\nExplanation:-For the purposes of this clause, the Constituent Assembly of the Dominion of India includes members chosen to fill casual vacancies in that Assembly in accordance with rules made in that behalf by the Assembly, but shall not include any members representing any territory not included in the First Schedule.\n(2) The Speaker of the Constituent Assembly when functioning as the Dominion Legislature under the Government of India Act, 1935, shall continue to be the Speaker of such Assembly functioning under clause (1) of this article.\n(3) Such person as the Constituent Assembly of the Dominion of India shall have elected in this behalf shall be the provisional President of India until a President has been elected in accordance with the provisions contained in Chapter I of Part V of this Constitution and has entered upon his office.\n(4) All persons holding office as ministers for the Dominion of India immediately before the commencement of this Constitution shall after such commencement become members of the Council of ministers of the provisional President under this Constitution."}, "391": {"url": "https://www.constitutionofindia.net/articles/article-391-power-of-the-president-to-amend-the-first-and-fourth-schedules-in-certain-contingencies-omitted/"}};
